// Contenido original de los 16 cursos de Fluent (generado desde content/uNN.json).
window.COURSES=[{"id":1,"title_es":"Saludos y presentaciones","title_en":"Greetings and introductions","level":"A1","goal_es":"Al terminar podrás saludar, despedirte, decir tu nombre, deletrearlo y hablar con cortesía.","lessons":[{"id":"1-1","title_es":"Hola y adiós","words":[{"en":"hello","es":"hola","pos":"interj","ex_en":"Hello, Ana.","ex_es":"Hola, Ana."},{"en":"hi","es":"hola (informal)","pos":"interj","ex_en":"Hi, Tom!","ex_es":"¡Hola, Tom!"},{"en":"goodbye","es":"adiós","pos":"interj","ex_en":"Goodbye, Carlos.","ex_es":"Adiós, Carlos."},{"en":"bye","es":"adiós, bye (informal)","pos":"interj","ex_en":"Bye, Sara!","ex_es":"¡Bye, Sara!"},{"en":"good morning","es":"buenos días","pos":"phrase","ex_en":"Good morning, Luis.","ex_es":"Buenos días, Luis."},{"en":"good afternoon","es":"buenas tardes","pos":"phrase","ex_en":"Good afternoon, Emma.","ex_es":"Buenas tardes, Emma."},{"en":"good night","es":"buenas noches (al despedirse)","pos":"phrase","ex_en":"Good night, Mom.","ex_es":"Buenas noches, mamá."},{"en":"see you later","es":"nos vemos luego","pos":"phrase","ex_en":"Bye, Tom. See you later!","ex_es":"Adiós, Tom. ¡Nos vemos luego!"}],"sentences":[{"en":"Hello, Luis!","es":"¡Hola, Luis!"},{"en":"Hi, good morning!","es":"¡Hola, buenos días!"},{"en":"Good afternoon, Ana.","es":"Buenas tardes, Ana."},{"en":"Goodbye, Carlos. Good night!","es":"Adiós, Carlos. ¡Buenas noches!"},{"en":"Bye, Emma! See you later.","es":"¡Adiós, Emma! Nos vemos luego."}],"tip_es":"Good night solo se usa para despedirse o antes de dormir. Si llegas a un lugar en la noche, saluda con good evening. Hi y bye son informales, perfectos con amigos."},{"id":"1-2","title_es":"¿Cómo te llamas?","words":[{"en":"name","es":"nombre","pos":"noun","ex_en":"My name is Luis.","ex_es":"Me llamo Luis."},{"en":"my","es":"mi","pos":"pron","ex_en":"My name is Sara.","ex_es":"Mi nombre es Sara."},{"en":"I","es":"yo","pos":"pron","ex_en":"I am Tom.","ex_es":"Yo soy Tom."},{"en":"I'm","es":"yo soy, yo estoy","pos":"phrase","ex_en":"I'm Carlos.","ex_es":"Soy Carlos."},{"en":"you","es":"tú, usted","pos":"pron","ex_en":"And you?","ex_es":"¿Y tú?"},{"en":"what","es":"qué, cuál","pos":"pron","ex_en":"What is your name?","ex_es":"¿Cuál es tu nombre?"},{"en":"nice to meet you","es":"mucho gusto","pos":"phrase","ex_en":"Nice to meet you, Ana.","ex_es":"Mucho gusto, Ana."},{"en":"too","es":"también","pos":"adv","ex_en":"I'm Ana too!","ex_es":"¡Yo también soy Ana!"}],"sentences":[{"en":"Hi, I'm Carlos.","es":"Hola, soy Carlos."},{"en":"My name is Sara.","es":"Me llamo Sara."},{"en":"What's your name?","es":"¿Cómo te llamas?"},{"en":"I'm Luis. And you?","es":"Soy Luis. ¿Y tú?"},{"en":"Nice to meet you too, Emma.","es":"Igualmente, Emma. Mucho gusto."}],"tip_es":"I'm es la forma corta de I am y es la más común al hablar. En inglés nunca se omite el sujeto: se dice I'm Carlos, no solo am Carlos. Además, I (yo) siempre se escribe con mayúscula."},{"id":"1-3","title_es":"¿Cómo estás?","words":[{"en":"how are you","es":"cómo estás","pos":"phrase","ex_en":"Hi, Ana! How are you?","ex_es":"¡Hola, Ana! ¿Cómo estás?"},{"en":"fine","es":"bien","pos":"adj","ex_en":"I'm fine.","ex_es":"Estoy bien."},{"en":"good","es":"bien, bueno","pos":"adj","ex_en":"I'm good. And you?","ex_es":"Estoy bien. ¿Y tú?"},{"en":"great","es":"muy bien, excelente","pos":"adj","ex_en":"I'm great!","ex_es":"¡Estoy muy bien!"},{"en":"okay","es":"bien, normal","pos":"adj","ex_en":"I'm okay.","ex_es":"Estoy bien, normal."},{"en":"not bad","es":"nada mal","pos":"phrase","ex_en":"Not bad. And you?","ex_es":"Nada mal. ¿Y tú?"},{"en":"tired","es":"cansado, cansada","pos":"adj","ex_en":"I'm tired.","ex_es":"Estoy cansado."},{"en":"very","es":"muy","pos":"adv","ex_en":"I'm very tired.","ex_es":"Estoy muy cansada."}],"sentences":[{"en":"Good morning! How are you?","es":"¡Buenos días! ¿Cómo estás?"},{"en":"I'm fine. And you?","es":"Estoy bien. ¿Y tú?"},{"en":"I'm great, Luis!","es":"¡Estoy muy bien, Luis!"},{"en":"Not bad. I'm very tired.","es":"Nada mal. Estoy muy cansado."},{"en":"Hi, Tom! I'm good. How are you?","es":"¡Hola, Tom! Estoy bien. ¿Cómo estás?"}],"tip_es":"I'm sirve para soy y para estoy: I'm Ana (soy Ana), I'm tired (estoy cansada). Los adjetivos en inglés no cambian por género, así que tired es igual para hombre o mujer."},{"id":"1-4","title_es":"El alfabeto y deletrear","words":[{"en":"letter","es":"letra","pos":"noun","ex_en":"What letter is it?","ex_es":"¿Qué letra es?"},{"en":"alphabet","es":"abecedario, alfabeto","pos":"noun","ex_en":"The English alphabet has 26 letters.","ex_es":"El alfabeto inglés tiene 26 letras."},{"en":"spell","es":"deletrear","pos":"verb","ex_en":"How do you spell it?","ex_es":"¿Cómo se escribe?"},{"en":"first name","es":"nombre (de pila)","pos":"phrase","ex_en":"My first name is Laura.","ex_es":"Mi nombre es Laura."},{"en":"last name","es":"apellido","pos":"phrase","ex_en":"My last name is Ruiz.","ex_es":"Mi apellido es Ruiz."},{"en":"again","es":"otra vez, de nuevo","pos":"adv","ex_en":"Spell it again.","ex_es":"Deletréalo otra vez."},{"en":"slowly","es":"despacio","pos":"adv","ex_en":"Spell your name slowly.","ex_es":"Deletrea tu nombre despacio."},{"en":"repeat","es":"repetir","pos":"verb","ex_en":"Repeat the letter.","ex_es":"Repite la letra."}],"sentences":[{"en":"What's your last name?","es":"¿Cuál es tu apellido?"},{"en":"My last name is Ruiz. R, U, I, Z.","es":"Mi apellido es Ruiz. R, U, I, Z."},{"en":"How do you spell your first name?","es":"¿Cómo se escribe tu nombre?"},{"en":"Is it B or V?","es":"¿Es B o V?"},{"en":"Repeat it again slowly.","es":"Repítelo otra vez, despacio."}],"tip_es":"Ojo con las vocales: en inglés la A se dice ei, la E se dice i y la I se dice ai. Son las letras que más confunden al deletrear, así que practica tu nombre con ellas."},{"id":"1-5","title_es":"Por favor y gracias","words":[{"en":"please","es":"por favor","pos":"adv","ex_en":"Slowly, please.","ex_es":"Despacio, por favor."},{"en":"thank you","es":"gracias","pos":"phrase","ex_en":"Thank you, Ana.","ex_es":"Gracias, Ana."},{"en":"thanks","es":"gracias (informal)","pos":"interj","ex_en":"Thanks, Tom!","ex_es":"¡Gracias, Tom!"},{"en":"you're welcome","es":"de nada","pos":"phrase","ex_en":"You're welcome, Luis.","ex_es":"De nada, Luis."},{"en":"excuse me","es":"disculpe, con permiso","pos":"phrase","ex_en":"Excuse me, what's your name?","ex_es":"Disculpe, ¿cómo se llama?"},{"en":"sorry","es":"perdón, lo siento","pos":"interj","ex_en":"Sorry, Emma!","ex_es":"¡Perdón, Emma!"},{"en":"no problem","es":"no hay problema","pos":"phrase","ex_en":"No problem, Carlos.","ex_es":"No hay problema, Carlos."},{"en":"of course","es":"claro, por supuesto","pos":"phrase","ex_en":"Of course, Sara.","ex_es":"Claro, Sara."}],"sentences":[{"en":"Thank you very much, Emma!","es":"¡Muchas gracias, Emma!"},{"en":"Excuse me, how do you spell it?","es":"Disculpe, ¿cómo se escribe?"},{"en":"Sorry, repeat it slowly, please.","es":"Perdón, repítalo despacio, por favor."},{"en":"No problem. You're welcome.","es":"No hay problema. De nada."},{"en":"Thanks, Carlos. See you later!","es":"Gracias, Carlos. ¡Nos vemos luego!"}],"tip_es":"Usa excuse me antes de interrumpir o pedir algo, como disculpe. Usa sorry después de un error, como perdón. Si no escuchaste bien, di Sorry? con tono de pregunta."},{"id":"1-6","title_es":"Conocer gente","words":[{"en":"friend","es":"amigo, amiga","pos":"noun","ex_en":"Tom is my friend.","ex_es":"Tom es mi amigo."},{"en":"teacher","es":"maestro, maestra","pos":"noun","ex_en":"Ana is my teacher.","ex_es":"Ana es mi maestra."},{"en":"student","es":"estudiante, alumno","pos":"noun","ex_en":"I'm a student.","ex_es":"Soy estudiante."},{"en":"Mr.","es":"señor (Sr.)","pos":"noun","ex_en":"Good morning, Mr. Brown.","ex_es":"Buenos días, señor Brown."},{"en":"Mrs.","es":"señora (Sra.)","pos":"noun","ex_en":"Thank you, Mrs. Clark.","ex_es":"Gracias, señora Clark."},{"en":"this is","es":"este es, esta es","pos":"phrase","ex_en":"This is my friend Luis.","ex_es":"Él es mi amigo Luis."},{"en":"yes","es":"sí","pos":"adv","ex_en":"Yes, I'm Sara.","ex_es":"Sí, soy Sara."},{"en":"no","es":"no","pos":"adv","ex_en":"No, I'm Emma.","ex_es":"No, soy Emma."}],"sentences":[{"en":"This is my friend Carlos.","es":"Él es mi amigo Carlos."},{"en":"Are you a student? Yes.","es":"¿Eres estudiante? Sí."},{"en":"No, I'm a teacher.","es":"No, soy maestra."},{"en":"Good morning, Mrs. Clark. How are you?","es":"Buenos días, señora Clark. ¿Cómo está?"},{"en":"Mr. Brown, this is my friend Ana.","es":"Señor Brown, le presento a mi amiga Ana."}],"tip_es":"En inglés se pone a antes de una profesión: I'm a student, I'm a teacher. En español decimos soy estudiante sin artículo, pero en inglés no se puede quitar."}],"dialogue":{"title_es":"El primer día de clase","setting_es":"Es tu primer día en la clase de inglés y una compañera te saluda.","lines":[{"who":"A","en":"Hi! Good morning. I'm Emma.","es":"¡Hola! Buenos días. Soy Emma."},{"who":"B","en":"Hello, Emma. My name is Carlos.","es":"Hola, Emma. Me llamo Carlos."},{"who":"A","en":"Nice to meet you, Carlos. How are you?","es":"Mucho gusto, Carlos. ¿Cómo estás?"},{"who":"B","en":"I'm fine, thanks. And you?","es":"Estoy bien, gracias. ¿Y tú?"},{"who":"A","en":"I'm great! What's your last name?","es":"¡Muy bien! ¿Cuál es tu apellido?"},{"who":"B","en":"Ruiz. R, U, I, Z.","es":"Ruiz. R, U, I, Z."},{"who":"A","en":"Sorry? Spell it slowly, please.","es":"¿Perdón? Deletréalo despacio, por favor."},{"who":"B","en":"Of course. R, U, I, Z.","es":"Claro. R, U, I, Z."},{"who":"A","en":"Thank you! Are you a student?","es":"¡Gracias! ¿Eres estudiante?"},{"who":"B","en":"Yes, I am. See you later, Emma!","es":"Sí. ¡Nos vemos luego, Emma!"}]}},{"id":2,"title_es":"Números, edad y datos personales","title_en":"Numbers and personal information","level":"A1","goal_es":"Al terminar podrás contar hasta 100, decir tu edad, tu teléfono, tu correo y de dónde eres, usando el verbo to be.","lessons":[{"id":"2-1","title_es":"Del cero al siete","words":[{"en":"zero","es":"cero","pos":"num","ex_en":"The number is zero.","ex_es":"El número es cero."},{"en":"one","es":"uno","pos":"num","ex_en":"One coffee, please.","ex_es":"Un café, por favor."},{"en":"two","es":"dos","pos":"num","ex_en":"Two, please.","ex_es":"Dos, por favor."},{"en":"three","es":"tres","pos":"num","ex_en":"Number three, please.","ex_es":"El número tres, por favor."},{"en":"four","es":"cuatro","pos":"num","ex_en":"My name has four letters.","ex_es":"Mi nombre tiene cuatro letras."},{"en":"five","es":"cinco","pos":"num","ex_en":"Five, four, three, two, one!","ex_es":"¡Cinco, cuatro, tres, dos, uno!"},{"en":"six","es":"seis","pos":"num","ex_en":"Lesson six is easy.","ex_es":"La lección seis es fácil."},{"en":"seven","es":"siete","pos":"num","ex_en":"Seven is my number.","ex_es":"El siete es mi número."}],"sentences":[{"en":"One, two, three, four, five.","es":"Uno, dos, tres, cuatro, cinco."},{"en":"Number seven, please.","es":"El número siete, por favor."},{"en":"Is it six or seven?","es":"¿Es seis o siete?"},{"en":"It's zero, not six.","es":"Es cero, no seis."},{"en":"Two, three, or four?","es":"¿Dos, tres o cuatro?"}],"tip_es":"Para decir three pon la punta de la lengua entre los dientes y sopla suave, no digas tri. En números de teléfono el cero muchas veces se dice o, como la letra: 502 se dice five, o, two."},{"id":"2-2","title_es":"Del ocho al veinte","words":[{"en":"eight","es":"ocho","pos":"num","ex_en":"My number is eight.","ex_es":"Mi número es el ocho."},{"en":"nine","es":"nueve","pos":"num","ex_en":"Lesson nine, please.","ex_es":"Lección nueve, por favor."},{"en":"ten","es":"diez","pos":"num","ex_en":"I have ten friends.","ex_es":"Tengo diez amigos."},{"en":"eleven","es":"once","pos":"num","ex_en":"Eleven is a good number.","ex_es":"El once es un buen número."},{"en":"twelve","es":"doce","pos":"num","ex_en":"I'm twelve.","ex_es":"Tengo doce años."},{"en":"thirteen","es":"trece","pos":"num","ex_en":"Thirteen, not thirty.","ex_es":"Trece, no treinta."},{"en":"fifteen","es":"quince","pos":"num","ex_en":"Ana is fifteen.","ex_es":"Ana tiene quince años."},{"en":"twenty","es":"veinte","pos":"num","ex_en":"Twenty letters? No, twenty-six!","ex_es":"¿Veinte letras? ¡No, veintiséis!"}],"sentences":[{"en":"Eight, nine, ten, eleven, twelve.","es":"Ocho, nueve, diez, once, doce."},{"en":"Is it thirteen or fifteen?","es":"¿Es trece o quince?"},{"en":"I'm fifteen. And you?","es":"Tengo quince años. ¿Y tú?"},{"en":"Sixteen, seventeen, eighteen, nineteen, twenty!","es":"¡Dieciséis, diecisiete, dieciocho, diecinueve, veinte!"},{"en":"The number is eleven, not seven.","es":"El número es once, no siete."}],"tip_es":"Del 13 al 19 los números terminan en teen: thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen. Ojo, se dice fifteen y no fiveteen, y thirteen y no threeteen."},{"id":"2-3","title_es":"Las decenas hasta el cien","words":[{"en":"thirty","es":"treinta","pos":"num","ex_en":"I'm thirty years old.","ex_es":"Tengo treinta años."},{"en":"forty","es":"cuarenta","pos":"num","ex_en":"My teacher is forty.","ex_es":"Mi maestro tiene cuarenta años."},{"en":"fifty","es":"cincuenta","pos":"num","ex_en":"Mr. Brown is fifty.","ex_es":"El señor Brown tiene cincuenta años."},{"en":"sixty","es":"sesenta","pos":"num","ex_en":"Sixty is not old!","ex_es":"¡Sesenta no es ser viejo!"},{"en":"seventy","es":"setenta","pos":"num","ex_en":"Mrs. Clark is seventy.","ex_es":"La señora Clark tiene setenta años."},{"en":"eighty","es":"ochenta","pos":"num","ex_en":"Eighty, not eighteen.","ex_es":"Ochenta, no dieciocho."},{"en":"ninety","es":"noventa","pos":"num","ex_en":"Ninety, ninety-one, ninety-two.","ex_es":"Noventa, noventa y uno, noventa y dos."},{"en":"one hundred","es":"cien","pos":"num","ex_en":"From one to one hundred.","ex_es":"Del uno al cien."}],"sentences":[{"en":"Twenty-one, twenty-two, twenty-three.","es":"Veintiuno, veintidós, veintitrés."},{"en":"Is it forty or fourteen?","es":"¿Es cuarenta o catorce?"},{"en":"Mr. Brown is fifty-five.","es":"El señor Brown tiene cincuenta y cinco años."},{"en":"I'm thirty-seven. And you?","es":"Tengo treinta y siete años. ¿Y tú?"},{"en":"Ninety-eight, ninety-nine, one hundred!","es":"¡Noventa y ocho, noventa y nueve, cien!"}],"tip_es":"Para formar números como 21 o 99 se unen las dos palabras con un guion: twenty-one, ninety-nine. Fíjate en la fuerza de la voz: thirTEEN lleva el acento al final y THIRty al inicio, así no los confundes."},{"id":"2-4","title_es":"El verbo to be","words":[{"en":"he","es":"él","pos":"pron","ex_en":"He is my friend.","ex_es":"Él es mi amigo."},{"en":"she","es":"ella","pos":"pron","ex_en":"She is a teacher.","ex_es":"Ella es maestra."},{"en":"it","es":"eso (para cosas y animales)","pos":"pron","ex_en":"Is it seven? Yes, it is.","ex_es":"¿Es el siete? Sí."},{"en":"we","es":"nosotros, nosotras","pos":"pron","ex_en":"We are students.","ex_es":"Somos estudiantes."},{"en":"they","es":"ellos, ellas","pos":"pron","ex_en":"They are my friends.","ex_es":"Ellos son mis amigos."},{"en":"is","es":"es, está","pos":"verb","ex_en":"Luis is tired.","ex_es":"Luis está cansado."},{"en":"are","es":"eres, son, están","pos":"verb","ex_en":"Are you okay?","ex_es":"¿Estás bien?"},{"en":"not","es":"no","pos":"adv","ex_en":"I'm not tired.","ex_es":"No estoy cansado."}],"sentences":[{"en":"He's my friend Tom.","es":"Él es mi amigo Tom."},{"en":"She's a teacher, not a student.","es":"Ella es maestra, no estudiante."},{"en":"We're students. Are you a teacher?","es":"Somos estudiantes. ¿Tú eres maestro?"},{"en":"They aren't tired. They're great!","es":"No están cansados. ¡Están muy bien!"},{"en":"What is it? It's a number.","es":"¿Qué es? Es un número."}],"tip_es":"Formas cortas: he's, she's, it's, we're, they're. Para negar agrega not: he isn't, we aren't. En inglés nunca se omite el sujeto, así que es maestra se dice she's a teacher."},{"id":"2-5","title_es":"Edad, teléfono y correo","words":[{"en":"how old","es":"qué edad, cuántos años","pos":"phrase","ex_en":"How old are you?","ex_es":"¿Cuántos años tienes?"},{"en":"years old","es":"años (de edad)","pos":"phrase","ex_en":"I'm twenty years old.","ex_es":"Tengo veinte años."},{"en":"age","es":"edad","pos":"noun","ex_en":"Age: thirty-two.","ex_es":"Edad: treinta y dos."},{"en":"phone number","es":"número de teléfono","pos":"phrase","ex_en":"What's your phone number?","ex_es":"¿Cuál es tu número de teléfono?"},{"en":"cell phone","es":"celular","pos":"noun","ex_en":"Is this your cell phone?","ex_es":"¿Este es tu celular?"},{"en":"email","es":"correo electrónico","pos":"noun","ex_en":"What's your email?","ex_es":"¿Cuál es tu correo?"},{"en":"address","es":"dirección","pos":"noun","ex_en":"My address is forty Oak Street.","ex_es":"Mi dirección es calle Oak número cuarenta."},{"en":"birthday","es":"cumpleaños","pos":"noun","ex_en":"Today is my birthday!","ex_es":"¡Hoy es mi cumpleaños!"}],"sentences":[{"en":"How old are you? I'm nineteen.","es":"¿Cuántos años tienes? Tengo diecinueve."},{"en":"She's twenty-four years old.","es":"Ella tiene veinticuatro años."},{"en":"What's your cell phone number?","es":"¿Cuál es tu número de celular?"},{"en":"It's five, five, five, eight, one, zero.","es":"Es cinco, cinco, cinco, ocho, uno, cero."},{"en":"My email is ana at fluent dot com.","es":"Mi correo es ana arroba fluent punto com."}],"tip_es":"Para decir tu edad se usa to be, no tener: I'm 20 o I'm 20 years old, nunca I have 20 years. Al dictar un correo, la arroba se dice at y el punto se dice dot."},{"id":"2-6","title_es":"¿De dónde eres?","words":[{"en":"where","es":"dónde","pos":"adv","ex_en":"Where is Tom?","ex_es":"¿Dónde está Tom?"},{"en":"from","es":"de (origen)","pos":"prep","ex_en":"I'm from Puebla.","ex_es":"Soy de Puebla."},{"en":"country","es":"país","pos":"noun","ex_en":"Mexico is a big country.","ex_es":"México es un país grande."},{"en":"city","es":"ciudad","pos":"noun","ex_en":"My city is Monterrey.","ex_es":"Mi ciudad es Monterrey."},{"en":"Mexico","es":"México","pos":"noun","ex_en":"I'm from Mexico.","ex_es":"Soy de México."},{"en":"the United States","es":"Estados Unidos","pos":"noun","ex_en":"Tom is from the United States.","ex_es":"Tom es de Estados Unidos."},{"en":"Mexican","es":"mexicano, mexicana","pos":"adj","ex_en":"We're Mexican.","ex_es":"Somos mexicanos."},{"en":"American","es":"estadounidense","pos":"adj","ex_en":"Emma is American.","ex_es":"Emma es estadounidense."}],"sentences":[{"en":"Where are you from?","es":"¿De dónde eres?"},{"en":"I'm from Guadalajara, Mexico.","es":"Soy de Guadalajara, México."},{"en":"Where is she from?","es":"¿De dónde es ella?"},{"en":"He's American, from Chicago.","es":"Él es estadounidense, de Chicago."},{"en":"We're Mexican. What city are you from?","es":"Somos mexicanos. ¿De qué ciudad eres?"}],"tip_es":"Países y nacionalidades siempre llevan mayúscula en inglés: Mexico, Mexican, American. La pregunta termina con from: Where are you from?, que literalmente es dónde eres de."}],"dialogue":{"title_es":"Inscripción en el gimnasio","setting_es":"Te inscribes en un gimnasio y la recepcionista te pide tus datos.","lines":[{"who":"A","en":"Hi! What's your name, please?","es":"¡Hola! ¿Cómo te llamas, por favor?"},{"who":"B","en":"My name is Laura Ortiz.","es":"Me llamo Laura Ortiz."},{"who":"A","en":"Nice to meet you. How old are you?","es":"Mucho gusto. ¿Cuántos años tienes?"},{"who":"B","en":"I'm twenty-eight years old.","es":"Tengo veintiocho años."},{"who":"A","en":"Great. Where are you from?","es":"Muy bien. ¿De dónde eres?"},{"who":"B","en":"I'm from Mexico, from Puebla.","es":"Soy de México, de Puebla."},{"who":"A","en":"What's your phone number?","es":"¿Cuál es tu número de teléfono?"},{"who":"B","en":"It's five, five, five, zero, one, four, nine.","es":"Es cinco, cinco, cinco, cero, uno, cuatro, nueve."},{"who":"A","en":"Thanks. And your email?","es":"Gracias. ¿Y tu correo?"},{"who":"B","en":"It's laura at fluent dot com.","es":"Es laura arroba fluent punto com."}]}},{"id":3,"title_es":"Familia y personas","title_en":"Family and people","level":"A1","goal_es":"Al terminar podrás hablar de tu familia, describir cómo son las personas por fuera y por dentro, y usar his, her, our y their.","lessons":[{"id":"3-1","title_es":"Mi familia","words":[{"en":"family","es":"familia","pos":"noun","ex_en":"This is my family.","ex_es":"Esta es mi familia."},{"en":"mother","es":"madre","pos":"noun","ex_en":"My mother is fifty.","ex_es":"Mi madre tiene cincuenta años."},{"en":"father","es":"padre","pos":"noun","ex_en":"My father is from Oaxaca.","ex_es":"Mi padre es de Oaxaca."},{"en":"mom","es":"mamá","pos":"noun","ex_en":"Hi, Mom!","ex_es":"¡Hola, mamá!"},{"en":"dad","es":"papá","pos":"noun","ex_en":"Thanks, Dad!","ex_es":"¡Gracias, papá!"},{"en":"brother","es":"hermano","pos":"noun","ex_en":"Luis is my brother.","ex_es":"Luis es mi hermano."},{"en":"sister","es":"hermana","pos":"noun","ex_en":"My sister is a student.","ex_es":"Mi hermana es estudiante."},{"en":"parents","es":"papás, padres","pos":"noun","ex_en":"My parents are sixty.","ex_es":"Mis papás tienen sesenta años."}],"sentences":[{"en":"This is my mom, Rosa.","es":"Ella es mi mamá, Rosa."},{"en":"My dad is a teacher.","es":"Mi papá es maestro."},{"en":"Are they your parents?","es":"¿Son tus papás?"},{"en":"My brother is twenty-two.","es":"Mi hermano tiene veintidós años."},{"en":"My sister and I are students.","es":"Mi hermana y yo somos estudiantes."}],"tip_es":"Parents significa papás (mamá y papá juntos), no parientes. Para parientes en general se dice relatives. Es un falso amigo muy común."},{"id":"3-2","title_es":"Hijos, pareja y abuelos","words":[{"en":"son","es":"hijo","pos":"noun","ex_en":"My son is a student.","ex_es":"Mi hijo es estudiante."},{"en":"daughter","es":"hija","pos":"noun","ex_en":"My daughter is twelve years old.","ex_es":"Mi hija tiene doce años."},{"en":"husband","es":"esposo","pos":"noun","ex_en":"My husband is from Texas.","ex_es":"Mi esposo es de Texas."},{"en":"wife","es":"esposa","pos":"noun","ex_en":"This is my wife, Laura.","ex_es":"Ella es mi esposa, Laura."},{"en":"grandmother","es":"abuela","pos":"noun","ex_en":"My grandmother is eighty.","ex_es":"Mi abuela tiene ochenta años."},{"en":"grandfather","es":"abuelo","pos":"noun","ex_en":"My grandfather is ninety-one.","ex_es":"Mi abuelo tiene noventa y un años."},{"en":"uncle","es":"tío","pos":"noun","ex_en":"My uncle is American.","ex_es":"Mi tío es estadounidense."},{"en":"aunt","es":"tía","pos":"noun","ex_en":"Aunt Carmen is my mom's sister.","ex_es":"La tía Carmen es hermana de mi mamá."}],"sentences":[{"en":"Is he your son?","es":"¿Es tu hijo?"},{"en":"My wife and I are from Monterrey.","es":"Mi esposa y yo somos de Monterrey."},{"en":"My grandmother is my dad's mother.","es":"Mi abuela es la mamá de mi papá."},{"en":"My uncle Pedro is my mom's brother.","es":"Mi tío Pedro es hermano de mi mamá."},{"en":"My husband is forty-three years old.","es":"Mi esposo tiene cuarenta y tres años."}],"tip_es":"Para decir de quién es algo se usa 's: my mom's sister es la hermana de mi mamá. El orden es al revés que en español, primero el dueño y luego la cosa. De cariño se dice grandma y grandpa."},{"id":"3-3","title_es":"Su, nuestro y tener","words":[{"en":"your","es":"tu, su (de usted)","pos":"pron","ex_en":"Is she your sister?","ex_es":"¿Ella es tu hermana?"},{"en":"his","es":"su (de él)","pos":"pron","ex_en":"His name is Pedro.","ex_es":"Su nombre es Pedro."},{"en":"her","es":"su (de ella)","pos":"pron","ex_en":"Her name is Carmen.","ex_es":"Su nombre es Carmen."},{"en":"our","es":"nuestro, nuestra","pos":"pron","ex_en":"Our mom is a teacher.","ex_es":"Nuestra mamá es maestra."},{"en":"their","es":"su (de ellos)","pos":"pron","ex_en":"Their son is six.","ex_es":"Su hijo tiene seis años."},{"en":"have","es":"tener","pos":"verb","ex_en":"I have two sisters.","ex_es":"Tengo dos hermanas."},{"en":"has","es":"tiene","pos":"verb","ex_en":"She has a son.","ex_es":"Ella tiene un hijo."},{"en":"cousin","es":"primo, prima","pos":"noun","ex_en":"My cousin is from Chicago.","ex_es":"Mi primo es de Chicago."}],"sentences":[{"en":"Her brother is my friend.","es":"Su hermano es mi amigo."},{"en":"His wife has two brothers.","es":"Su esposa tiene dos hermanos."},{"en":"We have three cousins.","es":"Tenemos tres primos."},{"en":"Their parents are from Mexico.","es":"Sus papás son de México."},{"en":"What's your cousin's name?","es":"¿Cómo se llama tu primo?"}],"tip_es":"His es su cuando el dueño es hombre y her cuando es mujer: his mom (la mamá de él), her mom (la mamá de ella). Con he, she e it, el verbo have cambia a has."},{"id":"3-4","title_es":"Alto, bajo, joven y grande","words":[{"en":"tall","es":"alto, alta","pos":"adj","ex_en":"My brother is very tall.","ex_es":"Mi hermano es muy alto."},{"en":"short","es":"bajo, chaparro","pos":"adj","ex_en":"My grandmother is short.","ex_es":"Mi abuela es chaparrita."},{"en":"young","es":"joven","pos":"adj","ex_en":"Her mom is very young.","ex_es":"Su mamá es muy joven."},{"en":"old","es":"viejo, grande (de edad)","pos":"adj","ex_en":"My grandfather is old.","ex_es":"Mi abuelo ya está grande."},{"en":"big","es":"grande","pos":"adj","ex_en":"Our family is big.","ex_es":"Nuestra familia es grande."},{"en":"small","es":"pequeño, chico","pos":"adj","ex_en":"Their baby is small.","ex_es":"Su bebé es chiquito."},{"en":"thin","es":"delgado, delgada","pos":"adj","ex_en":"My uncle is tall and thin.","ex_es":"Mi tío es alto y delgado."},{"en":"strong","es":"fuerte","pos":"adj","ex_en":"My dad is strong.","ex_es":"Mi papá es fuerte."}],"sentences":[{"en":"Is your sister tall or short?","es":"¿Tu hermana es alta o bajita?"},{"en":"He's young, but he's very strong.","es":"Es joven, pero es muy fuerte."},{"en":"My parents aren't old.","es":"Mis papás no están grandes."},{"en":"We have a big family.","es":"Tenemos una familia grande."},{"en":"Her cousin is short and thin.","es":"Su prima es bajita y delgada."}],"tip_es":"El adjetivo va antes del sustantivo: a big family es una familia grande. Además, nunca cambia por género ni número: tall sirve para alto, alta, altos y altas."},{"id":"3-5","title_es":"Pelo, ojos y apariencia","words":[{"en":"hair","es":"pelo, cabello","pos":"noun","ex_en":"She has long hair.","ex_es":"Ella tiene el pelo largo."},{"en":"eyes","es":"ojos","pos":"noun","ex_en":"He has big eyes.","ex_es":"Tiene los ojos grandes."},{"en":"long","es":"largo, larga","pos":"adj","ex_en":"My sister's hair is long.","ex_es":"Mi hermana tiene el pelo largo."},{"en":"curly","es":"chino, rizado","pos":"adj","ex_en":"Her hair is curly.","ex_es":"Ella tiene el pelo chino."},{"en":"beard","es":"barba","pos":"noun","ex_en":"My grandfather has a beard.","ex_es":"Mi abuelo tiene barba."},{"en":"glasses","es":"lentes","pos":"noun","ex_en":"My aunt has glasses.","ex_es":"Mi tía usa lentes."},{"en":"pretty","es":"bonita, bonito","pos":"adj","ex_en":"Your daughter is very pretty.","ex_es":"Tu hija está muy bonita."},{"en":"handsome","es":"guapo","pos":"adj","ex_en":"Her husband is handsome.","ex_es":"Su esposo es guapo."}],"sentences":[{"en":"She has long, curly hair.","es":"Ella tiene el pelo largo y chino."},{"en":"My dad has a beard and glasses.","es":"Mi papá tiene barba y usa lentes."},{"en":"Your mom is very pretty.","es":"Tu mamá es muy bonita."},{"en":"He's tall and handsome.","es":"Es alto y guapo."},{"en":"Their son has big eyes.","es":"Su hijo tiene los ojos grandes."}],"tip_es":"Para describir el pelo y los ojos se usa have o has: she has long hair (tiene el pelo largo). Ojo, hair va en singular cuando hablas de todo el pelo, nunca hairs."},{"id":"3-6","title_es":"La personalidad","words":[{"en":"nice","es":"buena onda, amable","pos":"adj","ex_en":"Your parents are very nice.","ex_es":"Tus papás son muy buena onda."},{"en":"funny","es":"chistoso, divertido","pos":"adj","ex_en":"My uncle is funny.","ex_es":"Mi tío es chistoso."},{"en":"kind","es":"amable, bondadoso","pos":"adj","ex_en":"Thank you, you're very kind.","ex_es":"Gracias, eres muy amable."},{"en":"smart","es":"inteligente, listo","pos":"adj","ex_en":"Our daughter is smart.","ex_es":"Nuestra hija es inteligente."},{"en":"shy","es":"tímido, tímida","pos":"adj","ex_en":"My brother is a little shy.","ex_es":"Mi hermano es un poco tímido."},{"en":"friendly","es":"amigable, amistoso","pos":"adj","ex_en":"The students are friendly.","ex_es":"Los estudiantes son amigables."},{"en":"serious","es":"serio, seria","pos":"adj","ex_en":"My dad is very serious.","ex_es":"Mi papá es muy serio."},{"en":"lazy","es":"flojo, floja","pos":"adj","ex_en":"My cousin is lazy.","ex_es":"Mi primo es flojo."}],"sentences":[{"en":"My sister is smart and funny.","es":"Mi hermana es inteligente y chistosa."},{"en":"Is your teacher nice or serious?","es":"¿Tu maestro es buena onda o serio?"},{"en":"He isn't lazy, he's tired!","es":"¡No es flojo, está cansado!"},{"en":"Our grandmother is very kind.","es":"Nuestra abuela es muy amable."},{"en":"My son is shy, but friendly.","es":"Mi hijo es tímido, pero amigable."}],"tip_es":"Cuidado con este falso amigo: sensible en inglés significa sensato. Si quieres decir que alguien es sensible, usa sensitive. Para decir que alguien es simpático o buena onda, lo más natural es nice."}],"dialogue":{"title_es":"Fotos de familia","setting_es":"Una amiga ve las fotos de tu familia en tu celular.","lines":[{"who":"A","en":"Is this your family?","es":"¿Es tu familia?"},{"who":"B","en":"Yes! This is my mom, Rosa.","es":"¡Sí! Ella es mi mamá, Rosa."},{"who":"A","en":"She's very pretty. Who is the tall man?","es":"Es muy bonita. ¿Quién es el señor alto?"},{"who":"B","en":"That's my brother, Daniel. He's thirty.","es":"Es mi hermano Daniel. Tiene treinta años."},{"who":"A","en":"He's handsome! Is he nice?","es":"¡Es guapo! ¿Es buena onda?"},{"who":"B","en":"Yes, he's very funny. He's a teacher.","es":"Sí, es muy chistoso. Es maestro."},{"who":"A","en":"And the girl with curly hair?","es":"¿Y la niña de pelo chino?"},{"who":"B","en":"That's Sofia, my brother's daughter.","es":"Es Sofía, la hija de mi hermano."},{"who":"A","en":"How old is she?","es":"¿Cuántos años tiene?"},{"who":"B","en":"She's six. She's shy, but very smart.","es":"Tiene seis años. Es tímida, pero muy inteligente."}]}},{"id":4,"title_es":"La casa y los objetos","title_en":"Home and things","level":"A1","goal_es":"Al terminar podrás describir tu casa, decir qué hay en cada cuarto con there is y there are, y explicar dónde están las cosas.","lessons":[{"id":"4-1","title_es":"Los cuartos de la casa","words":[{"en":"house","es":"casa","pos":"noun","ex_en":"My house is small.","ex_es":"Mi casa es chica."},{"en":"apartment","es":"departamento","pos":"noun","ex_en":"We live in an apartment.","ex_es":"Vivimos en un departamento."},{"en":"room","es":"cuarto","pos":"noun","ex_en":"My house has five rooms.","ex_es":"Mi casa tiene cinco cuartos."},{"en":"bedroom","es":"recámara","pos":"noun","ex_en":"My bedroom is big.","ex_es":"Mi recámara es grande."},{"en":"bathroom","es":"baño","pos":"noun","ex_en":"Where is the bathroom?","ex_es":"¿Dónde está el baño?"},{"en":"kitchen","es":"cocina","pos":"noun","ex_en":"Mom is in the kitchen.","ex_es":"Mamá está en la cocina."},{"en":"living room","es":"sala","pos":"noun","ex_en":"The living room is very big.","ex_es":"La sala es muy grande."},{"en":"yard","es":"patio, jardín","pos":"noun","ex_en":"The dog is in the yard.","ex_es":"El perro está en el patio."}],"sentences":[{"en":"This is my house.","es":"Esta es mi casa."},{"en":"Our apartment has two bedrooms.","es":"Nuestro departamento tiene dos recámaras."},{"en":"Excuse me, where is the bathroom?","es":"Disculpe, ¿dónde está el baño?"},{"en":"My grandmother is in the kitchen.","es":"Mi abuela está en la cocina."},{"en":"The yard is big, the house is small.","es":"El patio es grande y la casa es chica."}],"tip_es":"En México decimos recámara, pero en inglés es bedroom: bed (cama) más room (cuarto). Muchos cuartos se forman igual: bathroom, living room, dining room (comedor)."},{"id":"4-2","title_es":"Los muebles","words":[{"en":"bed","es":"cama","pos":"noun","ex_en":"The bed is big.","ex_es":"La cama es grande."},{"en":"table","es":"mesa","pos":"noun","ex_en":"The table is in the kitchen.","ex_es":"La mesa está en la cocina."},{"en":"chair","es":"silla","pos":"noun","ex_en":"We have six chairs.","ex_es":"Tenemos seis sillas."},{"en":"couch","es":"sillón, sofá","pos":"noun","ex_en":"The couch is in the living room.","ex_es":"El sillón está en la sala."},{"en":"desk","es":"escritorio","pos":"noun","ex_en":"My desk is in my bedroom.","ex_es":"Mi escritorio está en mi recámara."},{"en":"closet","es":"clóset","pos":"noun","ex_en":"My closet is small.","ex_es":"Mi clóset es chico."},{"en":"lamp","es":"lámpara","pos":"noun","ex_en":"My sister has a pretty lamp.","ex_es":"Mi hermana tiene una lámpara bonita."},{"en":"shelf","es":"repisa, estante","pos":"noun","ex_en":"My shelf has ten books.","ex_es":"Mi repisa tiene diez libros."}],"sentences":[{"en":"The bed is in the bedroom.","es":"La cama está en la recámara."},{"en":"We have a table and four chairs.","es":"Tenemos una mesa y cuatro sillas."},{"en":"Is your desk big or small?","es":"¿Tu escritorio es grande o chico?"},{"en":"Her closet is very big.","es":"Su clóset es muy grande."},{"en":"Their couch is old, but nice.","es":"Su sillón es viejo, pero bonito."}],"tip_es":"Usa the para algo específico y a para algo en general: a chair (una silla), the chair (la silla). Antes de un sonido de vocal, a cambia a an: an apartment."},{"id":"4-3","title_es":"Objetos de la casa","words":[{"en":"door","es":"puerta","pos":"noun","ex_en":"Where is the door?","ex_es":"¿Dónde está la puerta?"},{"en":"window","es":"ventana","pos":"noun","ex_en":"My bedroom has a big window.","ex_es":"Mi recámara tiene una ventana grande."},{"en":"key","es":"llave","pos":"noun","ex_en":"Where is my key?","ex_es":"¿Dónde está mi llave?"},{"en":"TV","es":"tele, televisión","pos":"noun","ex_en":"The TV is in the living room.","ex_es":"La tele está en la sala."},{"en":"mirror","es":"espejo","pos":"noun","ex_en":"The bathroom has a mirror.","ex_es":"El baño tiene un espejo."},{"en":"clock","es":"reloj (de pared)","pos":"noun","ex_en":"The kitchen clock is old.","ex_es":"El reloj de la cocina es viejo."},{"en":"book","es":"libro","pos":"noun","ex_en":"This book is very good.","ex_es":"Este libro es muy bueno."},{"en":"plant","es":"planta","pos":"noun","ex_en":"My mom has ten plants.","ex_es":"Mi mamá tiene diez plantas."}],"sentences":[{"en":"Where are my keys?","es":"¿Dónde están mis llaves?"},{"en":"The window is very big.","es":"La ventana es muy grande."},{"en":"We have a TV in the kitchen.","es":"Tenemos una tele en la cocina."},{"en":"Her bedroom has a mirror and a clock.","es":"Su recámara tiene un espejo y un reloj."},{"en":"Our house has plants and books.","es":"Nuestra casa tiene plantas y libros."}],"tip_es":"Para el plural casi siempre se agrega s: book, books. Si la palabra termina en sh, ch o x se agrega es: watch, watches. Y algunas cambian, como shelf, que en plural es shelves."},{"id":"4-4","title_es":"Hay: there is y there are","words":[{"en":"there is","es":"hay (una cosa)","pos":"phrase","ex_en":"There is a TV in my room.","ex_es":"Hay una tele en mi cuarto."},{"en":"there are","es":"hay (varias cosas)","pos":"phrase","ex_en":"There are two bathrooms.","ex_es":"Hay dos baños."},{"en":"is there","es":"¿hay? (una cosa)","pos":"phrase","ex_en":"Is there a bathroom?","ex_es":"¿Hay baño?"},{"en":"are there","es":"¿hay? (varias cosas)","pos":"phrase","ex_en":"Are there chairs in the kitchen?","ex_es":"¿Hay sillas en la cocina?"},{"en":"how many","es":"cuántos, cuántas","pos":"phrase","ex_en":"How many rooms are there?","ex_es":"¿Cuántos cuartos hay?"},{"en":"floor","es":"piso","pos":"noun","ex_en":"There are books on the floor.","ex_es":"Hay libros en el piso."},{"en":"stairs","es":"escaleras","pos":"noun","ex_en":"The stairs are next to the kitchen.","ex_es":"Las escaleras están junto a la cocina."},{"en":"garage","es":"cochera","pos":"noun","ex_en":"Our house has a garage.","ex_es":"Nuestra casa tiene cochera."}],"sentences":[{"en":"There's a bed and a desk.","es":"Hay una cama y un escritorio."},{"en":"There are three plants in the kitchen.","es":"Hay tres plantas en la cocina."},{"en":"Is there a TV in the bedroom?","es":"¿Hay tele en la recámara?"},{"en":"Are there stairs in your house?","es":"¿Hay escaleras en tu casa?"},{"en":"How many chairs are there? There are six.","es":"¿Cuántas sillas hay? Hay seis."}],"tip_es":"En español hay sirve para todo, pero en inglés se dice there is con una cosa y there are con varias. Para preguntar se cambia el orden: is there, are there. La forma corta de there is es there's."},{"id":"4-5","title_es":"¿Dónde está?","words":[{"en":"in","es":"en, dentro de","pos":"prep","ex_en":"The keys are in the kitchen.","ex_es":"Las llaves están en la cocina."},{"en":"on","es":"sobre, encima de","pos":"prep","ex_en":"The book is on the table.","ex_es":"El libro está en la mesa."},{"en":"under","es":"debajo de","pos":"prep","ex_en":"The cat is under the bed.","ex_es":"El gato está debajo de la cama."},{"en":"next to","es":"junto a, al lado de","pos":"prep","ex_en":"The lamp is next to the bed.","ex_es":"La lámpara está junto a la cama."},{"en":"behind","es":"detrás de","pos":"prep","ex_en":"The yard is behind the house.","ex_es":"El patio está detrás de la casa."},{"en":"in front of","es":"enfrente de","pos":"prep","ex_en":"The TV is in front of the couch.","ex_es":"La tele está enfrente del sillón."},{"en":"between","es":"entre","pos":"prep","ex_en":"The bathroom is between the bedrooms.","ex_es":"El baño está entre las recámaras."},{"en":"near","es":"cerca de","pos":"prep","ex_en":"Is the bathroom near the kitchen?","ex_es":"¿El baño está cerca de la cocina?"}],"sentences":[{"en":"My cell phone is on the desk.","es":"Mi celular está en el escritorio."},{"en":"There's a dog under the table.","es":"Hay un perro debajo de la mesa."},{"en":"The mirror is behind the door.","es":"El espejo está detrás de la puerta."},{"en":"Is the clock between the windows?","es":"¿El reloj está entre las ventanas?"},{"en":"My keys are in front of the TV.","es":"Mis llaves están enfrente de la tele."}],"tip_es":"En español decimos en para todo, pero en inglés in es dentro de algo y on es encima de algo: the keys are in the closet, the keys are on the table. Piensa si la cosa está adentro o arriba."},{"id":"4-6","title_es":"Cómo es tu casa","words":[{"en":"new","es":"nuevo, nueva","pos":"adj","ex_en":"Our apartment is new.","ex_es":"Nuestro departamento es nuevo."},{"en":"clean","es":"limpio, limpia","pos":"adj","ex_en":"The kitchen is very clean.","ex_es":"La cocina está muy limpia."},{"en":"dirty","es":"sucio, sucia","pos":"adj","ex_en":"The floor is dirty.","ex_es":"El piso está sucio."},{"en":"messy","es":"desordenado, tirado","pos":"adj","ex_en":"My brother's room is messy.","ex_es":"El cuarto de mi hermano está desordenado."},{"en":"comfortable","es":"cómodo, cómoda","pos":"adj","ex_en":"This couch is very comfortable.","ex_es":"Este sillón es muy cómodo."},{"en":"beautiful","es":"hermoso, precioso","pos":"adj","ex_en":"Your house is beautiful!","ex_es":"¡Tu casa está preciosa!"},{"en":"quiet","es":"tranquilo, silencioso","pos":"adj","ex_en":"My street is quiet.","ex_es":"Mi calle es tranquila."},{"en":"noisy","es":"ruidoso, ruidosa","pos":"adj","ex_en":"The city is very noisy.","ex_es":"La ciudad es muy ruidosa."}],"sentences":[{"en":"My bedroom is small, but comfortable.","es":"Mi recámara es chica, pero cómoda."},{"en":"Is the kitchen clean or dirty?","es":"¿La cocina está limpia o sucia?"},{"en":"Sorry, my apartment is very messy!","es":"¡Perdón, mi departamento está muy desordenado!"},{"en":"There's a beautiful window in the living room.","es":"Hay una ventana preciosa en la sala."},{"en":"Our new house isn't noisy, it's quiet.","es":"Nuestra casa nueva no es ruidosa, es tranquila."}],"tip_es":"Comfortable se dice en tres sílabas, algo como KÓMF-ter-bol, no com-for-ta-ble. Y recuerda que el adjetivo va antes del sustantivo: a new house es una casa nueva."}],"dialogue":{"title_es":"Buscando departamento","setting_es":"Visitas un departamento en renta y el dueño te lo enseña.","lines":[{"who":"A","en":"Hi! Welcome. This is the apartment.","es":"¡Hola! Bienvenido. Este es el departamento."},{"who":"B","en":"It's beautiful! How many bedrooms are there?","es":"¡Está precioso! ¿Cuántas recámaras hay?"},{"who":"A","en":"There are two bedrooms and one bathroom.","es":"Hay dos recámaras y un baño."},{"who":"B","en":"Is there a closet in the bedroom?","es":"¿Hay clóset en la recámara?"},{"who":"A","en":"Yes, there's a big closet next to the bed.","es":"Sí, hay un clóset grande junto a la cama."},{"who":"B","en":"Great. And where is the kitchen?","es":"Muy bien. ¿Y dónde está la cocina?"},{"who":"A","en":"It's behind the living room. It's new.","es":"Está detrás de la sala. Es nueva."},{"who":"B","en":"Is the street noisy?","es":"¿La calle es ruidosa?"},{"who":"A","en":"No, it's very quiet. There's a park near here.","es":"No, es muy tranquila. Hay un parque cerca."},{"who":"B","en":"Perfect! I like it.","es":"¡Perfecto! Me gusta."}]}},{"id":5,"title_es":"Comida y restaurante","title_en":"Food and eating out","level":"A1","goal_es":"Al terminar podrás hablar de la comida que te gusta y pedir en un restaurante.","lessons":[{"id":"5-1","title_es":"Comida básica","words":[{"en":"bread","es":"pan","pos":"noun","ex_en":"The bread is fresh.","ex_es":"El pan está fresco."},{"en":"rice","es":"arroz","pos":"noun","ex_en":"I like rice with beans.","ex_es":"Me gusta el arroz con frijoles."},{"en":"egg","es":"huevo","pos":"noun","ex_en":"I want two eggs, please.","ex_es":"Quiero dos huevos, por favor."},{"en":"chicken","es":"pollo","pos":"noun","ex_en":"The chicken is very good.","ex_es":"El pollo está muy bueno."},{"en":"beef","es":"carne de res","pos":"noun","ex_en":"We don't eat beef.","ex_es":"No comemos carne de res."},{"en":"fish","es":"pescado","pos":"noun","ex_en":"My mom makes fish on Fridays.","ex_es":"Mi mamá hace pescado los viernes."},{"en":"cheese","es":"queso","pos":"noun","ex_en":"Do you want cheese on your tacos?","ex_es":"¿Quieres queso en tus tacos?"},{"en":"beans","es":"frijoles","pos":"noun","ex_en":"Beans are cheap and healthy.","ex_es":"Los frijoles son baratos y saludables."}],"sentences":[{"en":"I like chicken.","es":"Me gusta el pollo."},{"en":"I don't like fish.","es":"No me gusta el pescado."},{"en":"Do you like eggs?","es":"¿Te gustan los huevos?"},{"en":"We eat rice and beans every day.","es":"Comemos arroz y frijoles todos los días."},{"en":"My brother loves bread with cheese.","es":"A mi hermano le encanta el pan con queso."}],"tip_es":"Cuando hablas de comida en general, en inglés no se usa artículo: I like chicken, no I like the chicken. Además, like no cambia con el plural: Me gustan los huevos se dice I like eggs."},{"id":"5-2","title_es":"Frutas y verduras","words":[{"en":"apple","es":"manzana","pos":"noun","ex_en":"I eat an apple every morning.","ex_es":"Como una manzana cada mañana."},{"en":"banana","es":"plátano","pos":"noun","ex_en":"This banana is very sweet.","ex_es":"Este plátano está muy dulce."},{"en":"orange","es":"naranja","pos":"noun","ex_en":"The oranges are from Veracruz.","ex_es":"Las naranjas son de Veracruz."},{"en":"strawberry","es":"fresa","pos":"noun","ex_en":"She loves strawberry ice cream.","ex_es":"A ella le encanta el helado de fresa."},{"en":"tomato","es":"jitomate","pos":"noun","ex_en":"We need tomatoes for the salsa.","ex_es":"Necesitamos jitomates para la salsa."},{"en":"onion","es":"cebolla","pos":"noun","ex_en":"Do you want onion on your burger?","ex_es":"¿Quieres cebolla en tu hamburguesa?"},{"en":"potato","es":"papa","pos":"noun","ex_en":"The potatoes are in the kitchen.","ex_es":"Las papas están en la cocina."},{"en":"avocado","es":"aguacate","pos":"noun","ex_en":"I put avocado on my eggs.","ex_es":"Le pongo aguacate a mis huevos."}],"sentences":[{"en":"I like apples and bananas.","es":"Me gustan las manzanas y los plátanos."},{"en":"Are there oranges in the kitchen?","es":"¿Hay naranjas en la cocina?"},{"en":"Strawberries are my favorite fruit.","es":"Las fresas son mi fruta favorita."},{"en":"I don't eat onion.","es":"No como cebolla."},{"en":"We need tomatoes, onions and avocados.","es":"Necesitamos jitomates, cebollas y aguacates."}],"tip_es":"Ojo con los plurales: tomato y potato agregan -es (tomatoes, potatoes). Si la palabra termina en consonante + y, cambia a -ies: strawberry, strawberries."},{"id":"5-3","title_es":"Bebidas","words":[{"en":"water","es":"agua","pos":"noun","ex_en":"I drink a lot of water.","ex_es":"Tomo mucha agua."},{"en":"juice","es":"jugo","pos":"noun","ex_en":"The kids want apple juice.","ex_es":"Los niños quieren jugo de manzana."},{"en":"coffee","es":"café","pos":"noun","ex_en":"I drink coffee in the morning.","ex_es":"Tomo café en la mañana."},{"en":"tea","es":"té","pos":"noun","ex_en":"My grandma drinks tea with honey.","ex_es":"Mi abuela toma té con miel."},{"en":"milk","es":"leche","pos":"noun","ex_en":"Is there milk in the fridge?","ex_es":"¿Hay leche en el refrigerador?"},{"en":"soda","es":"refresco","pos":"noun","ex_en":"Soda has a lot of sugar.","ex_es":"El refresco tiene mucha azúcar."},{"en":"beer","es":"cerveza","pos":"noun","ex_en":"Two beers, please.","ex_es":"Dos cervezas, por favor."},{"en":"cup","es":"taza","pos":"noun","ex_en":"Do you want a cup of coffee?","ex_es":"¿Quieres una taza de café?"}],"sentences":[{"en":"I want water, please.","es":"Quiero agua, por favor."},{"en":"Do you drink coffee or tea?","es":"¿Tomas café o té?"},{"en":"I don't drink soda.","es":"No tomo refresco."},{"en":"We want two cups of tea.","es":"Queremos dos tazas de té."},{"en":"Orange juice is good in the morning.","es":"El jugo de naranja es bueno en la mañana."}],"tip_es":"En México decimos tomar café, pero en inglés se dice drink coffee, no take coffee. Fíjate también en el orden: jugo de naranja es orange juice, porque la palabra que describe va primero."},{"id":"5-4","title_es":"Las comidas del día","words":[{"en":"breakfast","es":"desayuno","pos":"noun","ex_en":"Breakfast is at eight.","ex_es":"El desayuno es a las ocho."},{"en":"lunch","es":"comida","pos":"noun","ex_en":"We have lunch at two.","ex_es":"Comemos a las dos."},{"en":"dinner","es":"cena","pos":"noun","ex_en":"Dinner is ready!","ex_es":"¡La cena está lista!"},{"en":"hungry","es":"con hambre","pos":"adj","ex_en":"I'm very hungry.","ex_es":"Tengo mucha hambre."},{"en":"thirsty","es":"con sed","pos":"adj","ex_en":"Are you thirsty?","ex_es":"¿Tienes sed?"},{"en":"delicious","es":"delicioso","pos":"adj","ex_en":"This soup is delicious.","ex_es":"Esta sopa está deliciosa."},{"en":"eat","es":"comer","pos":"verb","ex_en":"What do you want to eat?","ex_es":"¿Qué quieres comer?"},{"en":"drink","es":"tomar, beber","pos":"verb","ex_en":"I want to drink something cold.","ex_es":"Quiero tomar algo frío."}],"sentences":[{"en":"I'm hungry. Let's eat!","es":"Tengo hambre. ¡Vamos a comer!"},{"en":"What do you have for breakfast?","es":"¿Qué desayunas?"},{"en":"I have eggs and coffee for breakfast.","es":"Desayuno huevos y café."},{"en":"We have dinner at nine.","es":"Cenamos a las nueve."},{"en":"The chicken soup is delicious.","es":"La sopa de pollo está deliciosa."}],"tip_es":"Tengo hambre se dice I'm hungry, con el verbo to be. Nunca digas I have hungry. Para desayunar, comer y cenar se usa have: have breakfast, have lunch, have dinner."},{"id":"5-5","title_es":"En el restaurante","words":[{"en":"menu","es":"menú","pos":"noun","ex_en":"Can we see the menu, please?","ex_es":"¿Podemos ver el menú, por favor?"},{"en":"waiter","es":"mesero","pos":"noun","ex_en":"The waiter is very friendly.","ex_es":"El mesero es muy amable."},{"en":"reservation","es":"reservación","pos":"noun","ex_en":"We have a reservation for four.","ex_es":"Tenemos una reservación para cuatro."},{"en":"order","es":"ordenar, pedir","pos":"verb","ex_en":"Are you ready to order?","ex_es":"¿Están listos para ordenar?"},{"en":"I'd like","es":"quisiera, me gustaría","pos":"phrase","ex_en":"I'd like the fish tacos, please.","ex_es":"Quisiera los tacos de pescado, por favor."},{"en":"can I have","es":"me da","pos":"phrase","ex_en":"Can I have more water, please?","ex_es":"¿Me da más agua, por favor?"},{"en":"check","es":"cuenta","pos":"noun","ex_en":"Can we have the check, please?","ex_es":"¿Nos trae la cuenta, por favor?"},{"en":"tip","es":"propina","pos":"noun","ex_en":"Don't forget the tip.","ex_es":"No olvides la propina."}],"sentences":[{"en":"A table for two, please.","es":"Una mesa para dos, por favor."},{"en":"I'd like a coffee, please.","es":"Quisiera un café, por favor."},{"en":"Can I have the chicken with rice?","es":"¿Me da el pollo con arroz?"},{"en":"What do you recommend?","es":"¿Qué me recomienda?"},{"en":"Excuse me, can we have the check?","es":"Disculpe, ¿nos trae la cuenta?"}],"tip_es":"I'd like es la forma corta de I would like y suena más amable que I want. Evita Give me, que en inglés suena brusco. En EE. UU. la cuenta es the check y se acostumbra dejar entre 15 y 20 por ciento de propina."},{"id":"5-6","title_es":"Some y any en la mesa","words":[{"en":"some","es":"un poco de, unos","pos":"adj","ex_en":"I want some water.","ex_es":"Quiero un poco de agua."},{"en":"any","es":"nada de, ningún","pos":"adj","ex_en":"We don't have any milk.","ex_es":"No tenemos nada de leche."},{"en":"sugar","es":"azúcar","pos":"noun","ex_en":"Is there any sugar?","ex_es":"¿Hay azúcar?"},{"en":"salt","es":"sal","pos":"noun","ex_en":"Can you pass the salt, please?","ex_es":"¿Me pasas la sal, por favor?"},{"en":"spoon","es":"cuchara","pos":"noun","ex_en":"I need a spoon for my soup.","ex_es":"Necesito una cuchara para mi sopa."},{"en":"fork","es":"tenedor","pos":"noun","ex_en":"Can I have a fork, please?","ex_es":"¿Me da un tenedor, por favor?"},{"en":"knife","es":"cuchillo","pos":"noun","ex_en":"This knife is dirty.","ex_es":"Este cuchillo está sucio."},{"en":"napkin","es":"servilleta","pos":"noun","ex_en":"Here are some napkins.","ex_es":"Aquí hay unas servilletas."}],"sentences":[{"en":"I'd like some bread, please.","es":"Quisiera un poco de pan, por favor."},{"en":"Do you have any orange juice?","es":"¿Tiene jugo de naranja?"},{"en":"There isn't any salt on the table.","es":"No hay sal en la mesa."},{"en":"Can I have some more napkins?","es":"¿Me da más servilletas?"},{"en":"We don't need any forks, thanks.","es":"No necesitamos tenedores, gracias."}],"tip_es":"Usa some en oraciones afirmativas y al pedir u ofrecer algo (Can I have some water?). Usa any en negativas y preguntas (We don't have any milk). Agua, azúcar y sal no se cuentan: no digas a sugar ni sugars."}],"dialogue":{"title_es":"En el restaurante","setting_es":"Estás en un restaurante en Austin y el mesero te toma la orden.","lines":[{"who":"A","en":"Hi! Welcome. Are you ready to order?","es":"¡Hola! Bienvenido. ¿Está listo para ordenar?"},{"who":"B","en":"Yes. I'd like the chicken tacos, please.","es":"Sí. Quisiera los tacos de pollo, por favor."},{"who":"A","en":"Sure. Do you want rice and beans?","es":"Claro. ¿Quiere arroz y frijoles?"},{"who":"B","en":"Just beans, please. No onion.","es":"Solo frijoles, por favor. Sin cebolla."},{"who":"A","en":"No problem. And to drink?","es":"No hay problema. ¿Y de tomar?"},{"who":"B","en":"Can I have an orange juice?","es":"¿Me da un jugo de naranja?"},{"who":"A","en":"Sorry, we don't have any orange juice.","es":"Lo siento, no tenemos jugo de naranja."},{"who":"B","en":"That's OK. Some water, please.","es":"Está bien. Agua, por favor."},{"who":"A","en":"Here you go. Enjoy your meal!","es":"Aquí tiene. ¡Buen provecho!"},{"who":"B","en":"Thank you! It looks delicious.","es":"¡Gracias! Se ve delicioso."}]}},{"id":6,"title_es":"Rutina diaria y la hora","title_en":"My daily routine","level":"A1","goal_es":"Al terminar podrás describir tu rutina, decir la hora y hablar de qué tan seguido haces las cosas.","lessons":[{"id":"6-1","title_es":"Por la mañana","words":[{"en":"wake up","es":"despertarse","pos":"verb","ex_en":"I wake up at six.","ex_es":"Me despierto a las seis."},{"en":"get up","es":"levantarse","pos":"verb","ex_en":"I get up at six fifteen.","ex_es":"Me levanto a las seis y cuarto."},{"en":"take a shower","es":"bañarse","pos":"phrase","ex_en":"I take a shower every morning.","ex_es":"Me baño todas las mañanas."},{"en":"brush","es":"cepillarse, lavarse","pos":"verb","ex_en":"I brush my teeth after breakfast.","ex_es":"Me lavo los dientes después del desayuno."},{"en":"get dressed","es":"vestirse","pos":"verb","ex_en":"I get dressed in my room.","ex_es":"Me visto en mi cuarto."},{"en":"shave","es":"rasurarse","pos":"verb","ex_en":"I don't shave every day.","ex_es":"No me rasuro todos los días."},{"en":"leave","es":"salir, irse","pos":"verb","ex_en":"I leave the house at seven thirty.","ex_es":"Salgo de la casa a las siete y media."},{"en":"early","es":"temprano","pos":"adv","ex_en":"I go to work early.","ex_es":"Me voy a trabajar temprano."}],"sentences":[{"en":"I wake up early.","es":"Me despierto temprano."},{"en":"Then I take a shower.","es":"Luego me baño."},{"en":"I get dressed and brush my hair.","es":"Me visto y me cepillo el pelo."},{"en":"I don't have breakfast at home.","es":"No desayuno en casa."},{"en":"I leave the house at seven.","es":"Salgo de la casa a las siete."}],"tip_es":"Muchos verbos que en español son reflexivos (despertarse, vestirse) en inglés no llevan myself: se dice I get dressed, no I dress myself. Con partes del cuerpo usa el posesivo: I brush my teeth, no the teeth."},{"id":"6-2","title_es":"¿Qué hora es?","words":[{"en":"what time","es":"qué hora","pos":"phrase","ex_en":"What time is it?","ex_es":"¿Qué hora es?"},{"en":"o'clock","es":"en punto","pos":"adv","ex_en":"It's nine o'clock.","ex_es":"Son las nueve en punto."},{"en":"half past","es":"y media","pos":"phrase","ex_en":"It's half past four.","ex_es":"Son las cuatro y media."},{"en":"quarter","es":"cuarto","pos":"noun","ex_en":"It's a quarter to ten.","ex_es":"Son quince para las diez."},{"en":"minute","es":"minuto","pos":"noun","ex_en":"Wait five minutes, please.","ex_es":"Espera cinco minutos, por favor."},{"en":"hour","es":"hora","pos":"noun","ex_en":"The class is an hour long.","ex_es":"La clase dura una hora."},{"en":"noon","es":"mediodía","pos":"noun","ex_en":"We have lunch at noon.","ex_es":"Comemos al mediodía."},{"en":"midnight","es":"medianoche","pos":"noun","ex_en":"The party ends at midnight.","ex_es":"La fiesta termina a medianoche."}],"sentences":[{"en":"Excuse me, what time is it?","es":"Disculpa, ¿qué hora es?"},{"en":"It's ten thirty.","es":"Son las diez y media."},{"en":"It's a quarter past eight.","es":"Son las ocho y cuarto."},{"en":"My English class is at noon.","es":"Mi clase de inglés es al mediodía."},{"en":"What time do you get up?","es":"¿A qué hora te levantas?"}],"tip_es":"Para la hora siempre usa It's, aunque en español digas son las tres: It's three o'clock. Para decir a las usa at: at noon, at seven thirty. La h de hour no suena, por eso se dice an hour."},{"id":"6-3","title_es":"Él y ella: presente simple","words":[{"en":"work","es":"trabajar","pos":"verb","ex_en":"My sister works in a hospital.","ex_es":"Mi hermana trabaja en un hospital."},{"en":"study","es":"estudiar","pos":"verb","ex_en":"I study English at night.","ex_es":"Estudio inglés en la noche."},{"en":"start","es":"empezar","pos":"verb","ex_en":"Class starts at eight.","ex_es":"La clase empieza a las ocho."},{"en":"finish","es":"terminar","pos":"verb","ex_en":"She finishes work at five.","ex_es":"Ella termina de trabajar a las cinco."},{"en":"watch","es":"ver","pos":"verb","ex_en":"My dad watches TV after dinner.","ex_es":"Mi papá ve la tele después de cenar."},{"en":"cook","es":"cocinar","pos":"verb","ex_en":"My husband cooks every night.","ex_es":"Mi esposo cocina todas las noches."},{"en":"read","es":"leer","pos":"verb","ex_en":"She reads before bed.","ex_es":"Ella lee antes de dormir."},{"en":"walk","es":"caminar","pos":"verb","ex_en":"He walks to school.","ex_es":"Él se va caminando a la escuela."}],"sentences":[{"en":"I work, and my wife studies.","es":"Yo trabajo y mi esposa estudia."},{"en":"He starts work at nine.","es":"Él empieza a trabajar a las nueve."},{"en":"She watches the news in the morning.","es":"Ella ve las noticias en la mañana."},{"en":"My brother doesn't cook.","es":"Mi hermano no cocina."},{"en":"Does your son walk to school?","es":"¿Tu hijo camina a la escuela?"}],"tip_es":"Con he, she e it el verbo lleva -s: she works, he reads. Después de sh, ch, x u o se agrega -es: watches, finishes, goes. Si termina en consonante + y, cambia a -ies: studies. El error más común es decir she work."},{"id":"6-4","title_es":"Los días de la semana","words":[{"en":"Monday","es":"lunes","pos":"noun","ex_en":"I go to the gym on Mondays.","ex_es":"Voy al gimnasio los lunes."},{"en":"Tuesday","es":"martes","pos":"noun","ex_en":"My English class is on Tuesday.","ex_es":"Mi clase de inglés es el martes."},{"en":"Wednesday","es":"miércoles","pos":"noun","ex_en":"We play soccer on Wednesdays.","ex_es":"Jugamos futbol los miércoles."},{"en":"Thursday","es":"jueves","pos":"noun","ex_en":"She cooks pasta on Thursdays.","ex_es":"Ella cocina pasta los jueves."},{"en":"Friday","es":"viernes","pos":"noun","ex_en":"Friday is my favorite day.","ex_es":"El viernes es mi día favorito."},{"en":"Saturday","es":"sábado","pos":"noun","ex_en":"I clean the house on Saturdays.","ex_es":"Limpio la casa los sábados."},{"en":"Sunday","es":"domingo","pos":"noun","ex_en":"We visit my parents on Sundays.","ex_es":"Visitamos a mis papás los domingos."},{"en":"weekend","es":"fin de semana","pos":"noun","ex_en":"What do you do on the weekend?","ex_es":"¿Qué haces el fin de semana?"}],"sentences":[{"en":"Today is Monday.","es":"Hoy es lunes."},{"en":"I don't work on Saturdays.","es":"No trabajo los sábados."},{"en":"My new class starts on Tuesday.","es":"Mi nueva clase empieza el martes."},{"en":"He studies on Wednesdays and Fridays.","es":"Él estudia los miércoles y los viernes."},{"en":"What do you do on Sundays?","es":"¿Qué haces los domingos?"}],"tip_es":"En inglés los días siempre van con mayúscula y con la preposición on: on Monday. Para algo que haces cada semana usa el plural: on Mondays significa los lunes. En Wednesday la primera d no suena: se pronuncia wénz-dei."},{"id":"6-5","title_es":"¿Qué tan seguido?","words":[{"en":"always","es":"siempre","pos":"adv","ex_en":"I always drink coffee in the morning.","ex_es":"Siempre tomo café en la mañana."},{"en":"usually","es":"normalmente","pos":"adv","ex_en":"We usually eat at home.","ex_es":"Normalmente comemos en casa."},{"en":"often","es":"seguido","pos":"adv","ex_en":"Do you often walk to work?","ex_es":"¿Caminas seguido al trabajo?"},{"en":"sometimes","es":"a veces","pos":"adv","ex_en":"Sometimes I cook dinner.","ex_es":"A veces preparo la cena."},{"en":"rarely","es":"casi nunca","pos":"adv","ex_en":"She rarely watches TV.","ex_es":"Ella casi nunca ve la tele."},{"en":"never","es":"nunca","pos":"adv","ex_en":"I never get up late.","ex_es":"Nunca me levanto tarde."},{"en":"every day","es":"todos los días","pos":"phrase","ex_en":"He reads the news every day.","ex_es":"Él lee las noticias todos los días."},{"en":"once a week","es":"una vez a la semana","pos":"phrase","ex_en":"We go to the market once a week.","ex_es":"Vamos al mercado una vez a la semana."}],"sentences":[{"en":"I always wake up early.","es":"Siempre me despierto temprano."},{"en":"She usually takes a shower at night.","es":"Ella normalmente se baña en la noche."},{"en":"We sometimes eat out on Fridays.","es":"A veces comemos fuera los viernes."},{"en":"He never works on the weekend.","es":"Él nunca trabaja el fin de semana."},{"en":"How often do you go to the gym?","es":"¿Qué tan seguido vas al gimnasio?"}],"tip_es":"Los adverbios de frecuencia van antes del verbo principal (I always eat) pero después de to be (I am always tired). No digas I eat always. Las expresiones como every day y once a week van al final de la oración."},{"id":"6-6","title_es":"Por la tarde y la noche","words":[{"en":"get home","es":"llegar a casa","pos":"phrase","ex_en":"I get home at six.","ex_es":"Llego a casa a las seis."},{"en":"relax","es":"descansar, relajarse","pos":"verb","ex_en":"I relax on the sofa after work.","ex_es":"Descanso en el sillón después del trabajo."},{"en":"do homework","es":"hacer la tarea","pos":"phrase","ex_en":"The kids do homework after dinner.","ex_es":"Los niños hacen la tarea después de cenar."},{"en":"wash the dishes","es":"lavar los trastes","pos":"phrase","ex_en":"I wash the dishes every night.","ex_es":"Lavo los trastes todas las noches."},{"en":"go to bed","es":"acostarse","pos":"phrase","ex_en":"I go to bed at eleven.","ex_es":"Me acuesto a las once."},{"en":"sleep","es":"dormir","pos":"verb","ex_en":"I sleep seven hours a night.","ex_es":"Duermo siete horas cada noche."},{"en":"late","es":"tarde","pos":"adv","ex_en":"My husband gets home late.","ex_es":"Mi esposo llega tarde a casa."},{"en":"evening","es":"la tarde, la noche","pos":"noun","ex_en":"I study English in the evening.","ex_es":"Estudio inglés en la noche."}],"sentences":[{"en":"What time do you get home?","es":"¿A qué hora llegas a casa?"},{"en":"I do my homework in the evening.","es":"Hago mi tarea en la noche."},{"en":"He doesn't wash the dishes.","es":"Él no lava los trastes."},{"en":"Do you go to bed late?","es":"¿Te acuestas tarde?"},{"en":"She usually relaxes and reads before bed.","es":"Ella normalmente descansa y lee antes de dormir."}],"tip_es":"Para negar y preguntar en presente simple usa do o does con el verbo en forma base: She doesn't work, Does he cook? La -s pasa a does, así que nunca digas She doesn't works ni Does he cooks?"}],"dialogue":{"title_es":"Una semana ocupada","setting_es":"Platicas con una amiga sobre tu rutina diaria.","lines":[{"who":"A","en":"You look tired. What time do you get up?","es":"Te ves cansado. ¿A qué hora te levantas?"},{"who":"B","en":"I get up at five thirty.","es":"Me levanto a las cinco y media."},{"who":"A","en":"Wow, that's early! Why?","es":"¡Guau, qué temprano! ¿Por qué?"},{"who":"B","en":"I start work at seven.","es":"Empiezo a trabajar a las siete."},{"who":"A","en":"And what time do you finish?","es":"¿Y a qué hora terminas?"},{"who":"B","en":"At four. Then I study English.","es":"A las cuatro. Luego estudio inglés."},{"who":"A","en":"Every day?","es":"¿Todos los días?"},{"who":"B","en":"No, on Mondays, Wednesdays and Fridays.","es":"No, los lunes, miércoles y viernes."},{"who":"A","en":"What do you do on the weekend?","es":"¿Qué haces el fin de semana?"},{"who":"B","en":"I relax and sleep late!","es":"¡Descanso y duermo hasta tarde!"}]}},{"id":7,"title_es":"Ropa, compras y precios","title_en":"Clothes and shopping","level":"A2","goal_es":"Al terminar podrás comprar ropa, preguntar tallas y precios, y pagar en una tienda.","lessons":[{"id":"7-1","title_es":"La ropa","words":[{"en":"shirt","es":"camisa","pos":"noun","ex_en":"I need a new shirt for work.","ex_es":"Necesito una camisa nueva para el trabajo."},{"en":"pants","es":"pantalones","pos":"noun","ex_en":"These pants are very comfortable.","ex_es":"Estos pantalones son muy cómodos."},{"en":"dress","es":"vestido","pos":"noun","ex_en":"She has a beautiful dress.","ex_es":"Ella tiene un vestido muy bonito."},{"en":"shoes","es":"zapatos","pos":"noun","ex_en":"My shoes are old.","ex_es":"Mis zapatos están viejos."},{"en":"jacket","es":"chamarra","pos":"noun","ex_en":"Take a jacket. It's cold.","ex_es":"Llévate una chamarra. Hace frío."},{"en":"sweater","es":"suéter","pos":"noun","ex_en":"This sweater is very warm.","ex_es":"Este suéter abriga mucho."},{"en":"socks","es":"calcetines","pos":"noun","ex_en":"I can't find my socks.","ex_es":"No encuentro mis calcetines."},{"en":"wear","es":"usar, traer puesto","pos":"verb","ex_en":"I wear a uniform at work.","ex_es":"Uso uniforme en el trabajo."}],"sentences":[{"en":"I wear pants and a shirt to work.","es":"Uso pantalón y camisa para ir al trabajo."},{"en":"She usually wears a dress on Sundays.","es":"Ella normalmente usa vestido los domingos."},{"en":"Where are my shoes?","es":"¿Dónde están mis zapatos?"},{"en":"Put on your jacket. It's cold outside.","es":"Ponte la chamarra. Hace frío afuera."},{"en":"I need new socks and a sweater.","es":"Necesito calcetines nuevos y un suéter."}],"tip_es":"Pants siempre es plural en inglés: My pants are new, no My pants is new. Para contarlos se dice a pair of pants. Wear es traer puesto, y put on es la acción de ponerse algo."},{"id":"7-2","title_es":"Los colores","words":[{"en":"red","es":"rojo","pos":"adj","ex_en":"She has a red dress.","ex_es":"Ella tiene un vestido rojo."},{"en":"blue","es":"azul","pos":"adj","ex_en":"My favorite color is blue.","ex_es":"Mi color favorito es el azul."},{"en":"green","es":"verde","pos":"adj","ex_en":"He wears a green jacket.","ex_es":"Él usa una chamarra verde."},{"en":"yellow","es":"amarillo","pos":"adj","ex_en":"The taxis in New York are yellow.","ex_es":"Los taxis de Nueva York son amarillos."},{"en":"black","es":"negro","pos":"adj","ex_en":"I need black shoes for the party.","ex_es":"Necesito zapatos negros para la fiesta."},{"en":"white","es":"blanco","pos":"adj","ex_en":"Do you have this shirt in white?","ex_es":"¿Tiene esta camisa en blanco?"},{"en":"gray","es":"gris","pos":"adj","ex_en":"My dad always wears gray pants.","ex_es":"Mi papá siempre usa pantalones grises."},{"en":"pink","es":"rosa","pos":"adj","ex_en":"The baby has pink socks.","ex_es":"La bebé trae calcetines rosas."}],"sentences":[{"en":"What color is your car?","es":"¿De qué color es tu coche?"},{"en":"I like the blue shirt.","es":"Me gusta la camisa azul."},{"en":"She's wearing a black dress and red shoes.","es":"Ella trae un vestido negro y zapatos rojos."},{"en":"Do you have it in green?","es":"¿Lo tiene en verde?"},{"en":"My new sweater is dark gray.","es":"Mi suéter nuevo es gris oscuro."}],"tip_es":"En inglés el color va antes de la cosa y nunca cambia: a red shirt, red shoes. No digas reds shoes ni shoes red. Para preguntar por el color se dice What color is it?"},{"id":"7-3","title_es":"Tallas y probadores","words":[{"en":"size","es":"talla","pos":"noun","ex_en":"What size are you?","ex_es":"¿Qué talla eres?"},{"en":"small","es":"chico","pos":"adj","ex_en":"I need a small, please.","ex_es":"Necesito talla chica, por favor."},{"en":"medium","es":"mediano","pos":"adj","ex_en":"Do you have a medium?","ex_es":"¿Tiene talla mediana?"},{"en":"large","es":"grande","pos":"adj","ex_en":"My husband wears a large.","ex_es":"Mi esposo usa talla grande."},{"en":"try on","es":"probarse","pos":"verb","ex_en":"Can I try on these pants?","ex_es":"¿Me puedo probar estos pantalones?"},{"en":"fitting room","es":"probador","pos":"noun","ex_en":"The fitting room is over there.","ex_es":"El probador está por allá."},{"en":"fit","es":"quedar","pos":"verb","ex_en":"These shoes don't fit me.","ex_es":"Estos zapatos no me quedan."},{"en":"tight","es":"apretado","pos":"adj","ex_en":"This shirt is too tight.","ex_es":"Esta camisa me queda muy apretada."}],"sentences":[{"en":"Excuse me, can I try this on?","es":"Disculpe, ¿me puedo probar esto?"},{"en":"Do you have this in a bigger size?","es":"¿Tiene esto en una talla más grande?"},{"en":"The jacket fits very well.","es":"La chamarra me queda muy bien."},{"en":"These pants are too tight.","es":"Estos pantalones me quedan muy apretados."},{"en":"Where's the fitting room, please?","es":"¿Dónde está el probador, por favor?"}],"tip_es":"Too significa demasiado y suena negativo: too tight, too big. Con try on, si usas it o them va en medio: try it on, nunca try on it."},{"id":"7-4","title_es":"¿Cuánto cuesta?","words":[{"en":"how much","es":"cuánto","pos":"phrase","ex_en":"How much is this jacket?","ex_es":"¿Cuánto cuesta esta chamarra?"},{"en":"cost","es":"costar","pos":"verb","ex_en":"How much do these shoes cost?","ex_es":"¿Cuánto cuestan estos zapatos?"},{"en":"price","es":"precio","pos":"noun","ex_en":"The price is on the tag.","ex_es":"El precio está en la etiqueta."},{"en":"dollar","es":"dólar","pos":"noun","ex_en":"It's twenty dollars.","ex_es":"Son veinte dólares."},{"en":"cheap","es":"barato","pos":"adj","ex_en":"This store is very cheap.","ex_es":"Esta tienda es muy barata."},{"en":"expensive","es":"caro","pos":"adj","ex_en":"That dress is too expensive.","ex_es":"Ese vestido está demasiado caro."},{"en":"sale","es":"oferta, rebaja","pos":"noun","ex_en":"Everything is on sale today.","ex_es":"Todo está en oferta hoy."},{"en":"discount","es":"descuento","pos":"noun","ex_en":"Is there a discount on shoes?","ex_es":"¿Hay descuento en zapatos?"}],"sentences":[{"en":"How much is it?","es":"¿Cuánto cuesta?"},{"en":"It's forty-nine ninety-nine.","es":"Son cuarenta y nueve con noventa y nueve."},{"en":"How much are these socks?","es":"¿Cuánto cuestan estos calcetines?"},{"en":"The sweater is on sale for twenty dollars.","es":"El suéter está en oferta a veinte dólares."},{"en":"It's nice, but it's very expensive.","es":"Está bonito, pero está muy caro."}],"tip_es":"Usa How much is...? para una cosa y How much are...? para varias. Con el verbo cost necesitas do o does: How much does it cost? Los precios se dicen en dos partes: 15.50 es fifteen fifty."},{"id":"7-5","title_es":"This, that, these, those","words":[{"en":"this","es":"este, esta","pos":"pron","ex_en":"This shirt is my size.","ex_es":"Esta camisa es de mi talla."},{"en":"that","es":"ese, esa","pos":"pron","ex_en":"Can I see that belt, please?","ex_es":"¿Me enseña ese cinturón, por favor?"},{"en":"these","es":"estos, estas","pos":"pron","ex_en":"These shoes are on sale.","ex_es":"Estos zapatos están en oferta."},{"en":"those","es":"esos, esas","pos":"pron","ex_en":"Those pants over there are cheap.","ex_es":"Esos pantalones de allá están baratos."},{"en":"pair","es":"par","pos":"noun","ex_en":"I need a new pair of shoes.","ex_es":"Necesito un par de zapatos nuevos."},{"en":"hat","es":"sombrero, gorra","pos":"noun","ex_en":"That hat looks good on you.","ex_es":"Ese sombrero se te ve bien."},{"en":"belt","es":"cinturón","pos":"noun","ex_en":"This belt is too short.","ex_es":"Este cinturón está muy corto."},{"en":"bag","es":"bolsa","pos":"noun","ex_en":"I like those black bags.","ex_es":"Me gustan esas bolsas negras."}],"sentences":[{"en":"I like this one.","es":"Me gusta este."},{"en":"How much are those hats?","es":"¿Cuánto cuestan esos sombreros?"},{"en":"Is that bag on sale?","es":"¿Esa bolsa está en oferta?"},{"en":"These socks are three dollars a pair.","es":"Estos calcetines cuestan tres dólares el par."},{"en":"Can I try on those pants, please?","es":"¿Me puedo probar esos pantalones, por favor?"}],"tip_es":"This y these son para lo que está cerca, y that y those para lo que está lejos. Cuida la pronunciación: this tiene una i corta y these una i larga, como iii. Para no repetir la cosa di this one o that one."},{"id":"7-6","title_es":"En la caja","words":[{"en":"store","es":"tienda","pos":"noun","ex_en":"The store opens at ten.","ex_es":"La tienda abre a las diez."},{"en":"cashier","es":"cajero","pos":"noun","ex_en":"Ask the cashier for a bag.","ex_es":"Pídele una bolsa al cajero."},{"en":"pay","es":"pagar","pos":"verb","ex_en":"Can I pay with my phone?","ex_es":"¿Puedo pagar con mi celular?"},{"en":"cash","es":"efectivo","pos":"noun","ex_en":"Do you have cash?","ex_es":"¿Traes efectivo?"},{"en":"credit card","es":"tarjeta de crédito","pos":"noun","ex_en":"Do you take credit cards?","ex_es":"¿Aceptan tarjeta de crédito?"},{"en":"receipt","es":"ticket, recibo","pos":"noun","ex_en":"Here's your receipt.","ex_es":"Aquí está su ticket."},{"en":"change","es":"cambio","pos":"noun","ex_en":"Here's your change.","ex_es":"Aquí tiene su cambio."},{"en":"return","es":"devolver","pos":"verb","ex_en":"I want to return these shoes.","ex_es":"Quiero devolver estos zapatos."}],"sentences":[{"en":"Cash or credit?","es":"¿Efectivo o tarjeta?"},{"en":"I'd like to pay with a credit card.","es":"Quisiera pagar con tarjeta de crédito."},{"en":"Do you need a bag?","es":"¿Necesita bolsa?"},{"en":"Can I return it if it doesn't fit?","es":"¿Lo puedo devolver si no me queda?"},{"en":"Keep your receipt, please.","es":"Guarde su ticket, por favor."}],"tip_es":"En receipt la p no suena: se pronuncia ri-sít. En México decimos ticket de compra, pero en inglés ticket es un boleto o una multa. Para el comprobante de pago di receipt."}],"dialogue":{"title_es":"En una tienda de ropa","setting_es":"Estás en un centro comercial y quieres comprar una chamarra.","lines":[{"who":"A","en":"Hi there! Can I help you?","es":"¡Hola! ¿En qué le puedo ayudar?"},{"who":"B","en":"Yes, how much is this jacket?","es":"Sí, ¿cuánto cuesta esta chamarra?"},{"who":"A","en":"It's sixty dollars, but it's on sale today.","es":"Cuesta sesenta dólares, pero hoy está en oferta."},{"who":"B","en":"Great! Do you have it in black?","es":"¡Qué bien! ¿La tiene en negro?"},{"who":"A","en":"Yes. What size are you?","es":"Sí. ¿Qué talla es?"},{"who":"B","en":"Medium, I think. Can I try it on?","es":"Mediana, creo. ¿Me la puedo probar?"},{"who":"A","en":"Sure. The fitting room is over there.","es":"Claro. El probador está por allá."},{"who":"B","en":"It fits well. I'll take it.","es":"Me queda bien. Me la llevo."},{"who":"A","en":"Perfect. Cash or credit card?","es":"Perfecto. ¿Efectivo o tarjeta de crédito?"},{"who":"B","en":"Credit card, please.","es":"Con tarjeta, por favor."}]}},{"id":8,"title_es":"Ciudad, direcciones y transporte","title_en":"Getting around the city","level":"A2","goal_es":"Al terminar podrás pedir y dar indicaciones, usar el transporte y decir qué está pasando ahora.","lessons":[{"id":"8-1","title_es":"Lugares de la ciudad","words":[{"en":"bank","es":"banco","pos":"noun","ex_en":"The bank closes at four.","ex_es":"El banco cierra a las cuatro."},{"en":"pharmacy","es":"farmacia","pos":"noun","ex_en":"Is there a pharmacy near here?","ex_es":"¿Hay una farmacia cerca de aquí?"},{"en":"supermarket","es":"supermercado","pos":"noun","ex_en":"I buy food at the supermarket.","ex_es":"Compro comida en el supermercado."},{"en":"hospital","es":"hospital","pos":"noun","ex_en":"The hospital is on Main Street.","ex_es":"El hospital está en la calle Main."},{"en":"park","es":"parque","pos":"noun","ex_en":"The kids play in the park.","ex_es":"Los niños juegan en el parque."},{"en":"museum","es":"museo","pos":"noun","ex_en":"The museum is free on Sundays.","ex_es":"El museo es gratis los domingos."},{"en":"post office","es":"oficina de correos","pos":"noun","ex_en":"Where's the post office?","ex_es":"¿Dónde está la oficina de correos?"},{"en":"gas station","es":"gasolinera","pos":"noun","ex_en":"There's a gas station on this street.","ex_es":"Hay una gasolinera en esta calle."}],"sentences":[{"en":"Where's the bank?","es":"¿Dónde está el banco?"},{"en":"The pharmacy is next to the supermarket.","es":"La farmacia está al lado del supermercado."},{"en":"Is there a park near your house?","es":"¿Hay un parque cerca de tu casa?"},{"en":"The post office is closed on Sundays.","es":"La oficina de correos cierra los domingos."},{"en":"We need gas. Is there a gas station nearby?","es":"Necesitamos gasolina. ¿Hay una gasolinera cerca?"}],"tip_es":"Con lugares de la ciudad se usa the: go to the bank, go to the park. Pero se dice go to work, go to school y go home sin artículo. En pharmacy, ph suena como f."},{"id":"8-2","title_es":"Izquierda, derecha y derecho","words":[{"en":"turn","es":"dar vuelta","pos":"verb","ex_en":"Turn at the next street.","ex_es":"Da vuelta en la siguiente calle."},{"en":"left","es":"izquierda","pos":"noun","ex_en":"Turn left at the bank.","ex_es":"Da vuelta a la izquierda en el banco."},{"en":"right","es":"derecha","pos":"noun","ex_en":"The museum is on your right.","ex_es":"El museo está a tu derecha."},{"en":"straight ahead","es":"derecho","pos":"adv","ex_en":"Go straight ahead for two blocks.","ex_es":"Sigue derecho dos cuadras."},{"en":"corner","es":"esquina","pos":"noun","ex_en":"The store is on the corner.","ex_es":"La tienda está en la esquina."},{"en":"block","es":"cuadra","pos":"noun","ex_en":"It's three blocks from here.","ex_es":"Está a tres cuadras de aquí."},{"en":"street","es":"calle","pos":"noun","ex_en":"What street is it on?","ex_es":"¿En qué calle está?"},{"en":"traffic light","es":"semáforo","pos":"noun","ex_en":"Turn right at the traffic light.","ex_es":"Da vuelta a la derecha en el semáforo."}],"sentences":[{"en":"Go straight ahead and turn left.","es":"Sigue derecho y da vuelta a la izquierda."},{"en":"The bank is on the corner.","es":"El banco está en la esquina."},{"en":"Turn right at the second traffic light.","es":"Da vuelta a la derecha en el segundo semáforo."},{"en":"The park is two blocks from here.","es":"El parque está a dos cuadras de aquí."},{"en":"The pharmacy is on the left.","es":"La farmacia está a la izquierda."}],"tip_es":"Cuidado: derecho (seguir sin dar vuelta) es straight, y derecha es right. Si dices go right, la persona va a dar vuelta. Recuerda las preposiciones: on the corner, at the traffic light, on your left."},{"id":"8-3","title_es":"El transporte","words":[{"en":"bus","es":"camión, autobús","pos":"noun","ex_en":"I take the bus to work.","ex_es":"Tomo el camión para ir al trabajo."},{"en":"subway","es":"metro","pos":"noun","ex_en":"The subway is fast and cheap.","ex_es":"El metro es rápido y barato."},{"en":"taxi","es":"taxi","pos":"noun","ex_en":"Let's take a taxi. It's late.","ex_es":"Tomemos un taxi. Ya es tarde."},{"en":"train","es":"tren","pos":"noun","ex_en":"The train leaves at nine.","ex_es":"El tren sale a las nueve."},{"en":"bike","es":"bici","pos":"noun","ex_en":"I go to work by bike.","ex_es":"Voy al trabajo en bici."},{"en":"bus stop","es":"parada del camión","pos":"noun","ex_en":"The bus stop is on the corner.","ex_es":"La parada del camión está en la esquina."},{"en":"ticket","es":"boleto","pos":"noun","ex_en":"How much is a train ticket?","ex_es":"¿Cuánto cuesta un boleto de tren?"},{"en":"by car","es":"en coche","pos":"phrase","ex_en":"We go to the beach by car.","ex_es":"Vamos a la playa en coche."}],"sentences":[{"en":"How do you get to work?","es":"¿Cómo te vas al trabajo?"},{"en":"I usually take the subway.","es":"Normalmente tomo el metro."},{"en":"She goes to school by bus.","es":"Ella va a la escuela en camión."},{"en":"Where can I buy a ticket?","es":"¿Dónde puedo comprar un boleto?"},{"en":"Does this bus go to the airport?","es":"¿Este camión va al aeropuerto?"}],"tip_es":"Con by no se usa artículo: by bus, by car, by train. Pero a pie es on foot, no by foot. Con take sí va the: take the bus, take the subway."},{"id":"8-4","title_es":"Pedir indicaciones","words":[{"en":"how do I get to","es":"cómo llego a","pos":"phrase","ex_en":"How do I get to the museum?","ex_es":"¿Cómo llego al museo?"},{"en":"cross","es":"cruzar","pos":"verb","ex_en":"Cross the street at the light.","ex_es":"Cruza la calle en el semáforo."},{"en":"follow","es":"seguir","pos":"verb","ex_en":"Follow this street to the park.","ex_es":"Sigue esta calle hasta el parque."},{"en":"stop","es":"parar, detenerse","pos":"verb","ex_en":"Stop at the corner, please.","ex_es":"Pare en la esquina, por favor."},{"en":"keep going","es":"seguir adelante","pos":"phrase","ex_en":"Keep going until you see the bank.","ex_es":"Sigue adelante hasta que veas el banco."},{"en":"map","es":"mapa","pos":"noun","ex_en":"Can you show me on the map?","ex_es":"¿Me lo puede enseñar en el mapa?"},{"en":"lost","es":"perdido","pos":"adj","ex_en":"Excuse me, I'm lost.","ex_es":"Disculpe, estoy perdido."},{"en":"directions","es":"indicaciones","pos":"noun","ex_en":"Can you give me directions?","ex_es":"¿Me puede dar indicaciones?"}],"sentences":[{"en":"Excuse me, how do I get to the bank?","es":"Disculpe, ¿cómo llego al banco?"},{"en":"Cross the street and turn right.","es":"Cruza la calle y da vuelta a la derecha."},{"en":"Don't turn here. Keep going.","es":"No des vuelta aquí. Sigue adelante."},{"en":"Follow the signs to the subway.","es":"Sigue los letreros hacia el metro."},{"en":"We're lost. Do you have a map?","es":"Estamos perdidos. ¿Tienes un mapa?"}],"tip_es":"El imperativo es el verbo en forma base sin sujeto: Turn left, Cross the street. Para negar usa Don't: Don't turn here. Ojo, falso amigo: directions son indicaciones, y dirección (de una casa) es address."},{"id":"8-5","title_es":"¿Qué estás haciendo ahorita?","words":[{"en":"right now","es":"ahorita, ahora mismo","pos":"adv","ex_en":"I'm driving right now.","ex_es":"Ahorita voy manejando."},{"en":"at the moment","es":"en este momento","pos":"phrase","ex_en":"He's working at the moment.","ex_es":"Él está trabajando en este momento."},{"en":"drive","es":"manejar","pos":"verb","ex_en":"I'm learning to drive.","ex_es":"Estoy aprendiendo a manejar."},{"en":"wait","es":"esperar","pos":"verb","ex_en":"I'm waiting for the bus.","ex_es":"Estoy esperando el camión."},{"en":"arrive","es":"llegar","pos":"verb","ex_en":"The train arrives at six.","ex_es":"El tren llega a las seis."},{"en":"ride","es":"andar en, viajar en","pos":"verb","ex_en":"Do you ride the subway every day?","ex_es":"¿Viajas en metro todos los días?"},{"en":"get on","es":"subirse a","pos":"phrase","ex_en":"Get on the bus at the front.","ex_es":"Súbete al camión por adelante."},{"en":"get off","es":"bajarse de","pos":"phrase","ex_en":"Get off at the next stop.","ex_es":"Bájate en la siguiente parada."}],"sentences":[{"en":"Where are you? I'm waiting for you.","es":"¿Dónde estás? Te estoy esperando."},{"en":"I'm riding the subway right now.","es":"Ahorita voy en el metro."},{"en":"We're getting off at the next stop.","es":"Nos bajamos en la siguiente parada."},{"en":"Is she driving or taking the train?","es":"¿Ella viene manejando o en tren?"},{"en":"The bus isn't coming. Let's take a taxi.","es":"El camión no viene. Vamos a tomar un taxi."}],"tip_es":"El presente continuo (am, is, are + verbo con -ing) es para lo que pasa ahora. Si el verbo termina en e, quítala: drive, driving. Si termina en vocal + consonante, dobla la consonante: get, getting. Para rutinas usa presente simple: I take the bus every day."},{"id":"8-6","title_es":"Por la ciudad","words":[{"en":"traffic","es":"tráfico","pos":"noun","ex_en":"There's a lot of traffic today.","ex_es":"Hay mucho tráfico hoy."},{"en":"rush hour","es":"hora pico","pos":"noun","ex_en":"Don't drive at rush hour.","ex_es":"No manejes en hora pico."},{"en":"station","es":"estación","pos":"noun","ex_en":"Meet me at the train station.","ex_es":"Te veo en la estación del tren."},{"en":"downtown","es":"el centro","pos":"adv","ex_en":"I work downtown.","ex_es":"Trabajo en el centro."},{"en":"neighborhood","es":"colonia, barrio","pos":"noun","ex_en":"My neighborhood is very quiet.","ex_es":"Mi colonia es muy tranquila."},{"en":"sidewalk","es":"banqueta","pos":"noun","ex_en":"Walk on the sidewalk, please.","ex_es":"Camina por la banqueta, por favor."},{"en":"bridge","es":"puente","pos":"noun","ex_en":"Cross the bridge and turn left.","ex_es":"Cruza el puente y da vuelta a la izquierda."},{"en":"crowded","es":"lleno de gente","pos":"adj","ex_en":"The subway is crowded at eight.","ex_es":"El metro va lleno a las ocho."}],"sentences":[{"en":"The traffic is terrible right now.","es":"El tráfico está horrible ahorita."},{"en":"Is the station far from downtown?","es":"¿La estación está lejos del centro?"},{"en":"The bus is very crowded at rush hour.","es":"El camión va muy lleno en hora pico."},{"en":"I live in a quiet neighborhood near the park.","es":"Vivo en una colonia tranquila cerca del parque."},{"en":"We're crossing the bridge. We're almost there!","es":"Estamos cruzando el puente. ¡Ya casi llegamos!"}],"tip_es":"Downtown no lleva the ni to: I go downtown es voy al centro, no I go to the downtown. Traffic no se cuenta: di a lot of traffic, nunca traffics."}],"dialogue":{"title_es":"¿Cómo llego al museo?","setting_es":"Estás de visita en Chicago y una señora te ayuda a llegar al museo.","lines":[{"who":"A","en":"Hi! Are you OK? You look lost.","es":"¡Hola! ¿Estás bien? Te ves perdido."},{"who":"B","en":"Yes. How do I get to the museum?","es":"Sí. ¿Cómo llego al museo?"},{"who":"A","en":"It's far. You can take the subway.","es":"Está lejos. Puedes tomar el metro."},{"who":"B","en":"Where is the subway station?","es":"¿Dónde está la estación del metro?"},{"who":"A","en":"Go straight ahead and turn left at the light.","es":"Sigue derecho y da vuelta a la izquierda en el semáforo."},{"who":"B","en":"And then?","es":"¿Y luego?"},{"who":"A","en":"The station is on the corner, by a bank.","es":"La estación está en la esquina, junto a un banco."},{"who":"B","en":"Great. Where do I get off?","es":"Perfecto. ¿Dónde me bajo?"},{"who":"A","en":"Get off at Lake Street. It's three stops.","es":"Bájate en Lake Street. Son tres paradas."},{"who":"B","en":"Thank you so much!","es":"¡Muchísimas gracias!"}]}},{"id":9,"title_es":"El pasado: fin de semana y vacaciones","title_en":"Last weekend","level":"A2","goal_es":"Al terminar podrás contar qué hiciste ayer, el fin de semana y en tus vacaciones.","lessons":[{"id":"9-1","title_es":"Ayer: was y were","words":[{"en":"yesterday","es":"ayer","pos":"adv","ex_en":"I was very busy yesterday.","ex_es":"Ayer estuve muy ocupado."},{"en":"last night","es":"anoche","pos":"phrase","ex_en":"Where were you last night?","ex_es":"¿Dónde estabas anoche?"},{"en":"last week","es":"la semana pasada","pos":"phrase","ex_en":"We were in Puebla last week.","ex_es":"Estuvimos en Puebla la semana pasada."},{"en":"last month","es":"el mes pasado","pos":"phrase","ex_en":"My cousin was here last month.","ex_es":"Mi primo estuvo aquí el mes pasado."},{"en":"ago","es":"hace (tiempo)","pos":"adv","ex_en":"I was in Cancún two years ago.","ex_es":"Estuve en Cancún hace dos años."},{"en":"the day before yesterday","es":"antier","pos":"phrase","ex_en":"The day before yesterday was my birthday.","ex_es":"Antier fue mi cumpleaños."},{"en":"born","es":"nacido","pos":"adj","ex_en":"I was born in Monterrey.","ex_es":"Nací en Monterrey."},{"en":"bored","es":"aburrido","pos":"adj","ex_en":"The kids were bored at home.","ex_es":"Los niños estaban aburridos en casa."}],"sentences":[{"en":"I was at home last night.","es":"Estuve en casa anoche."},{"en":"Were you tired yesterday?","es":"¿Estabas cansado ayer?"},{"en":"The movie was very good.","es":"La película estuvo muy buena."},{"en":"We weren't at school last week.","es":"No estuvimos en la escuela la semana pasada."},{"en":"Where was your sister born?","es":"¿Dónde nació tu hermana?"}],"tip_es":"El pasado de to be tiene dos formas: was (con I, he, she, it) y were (con you, we, they). Para decir hace dos años, ago va después del tiempo: two years ago, nunca ago two years. Y para decir nací se usa I was born."},{"id":"9-2","title_es":"Verbos regulares con -ed","words":[{"en":"watch / watched","es":"ver / vi","pos":"verb","ex_en":"We watched a movie last night.","ex_es":"Vimos una película anoche."},{"en":"visit / visited","es":"visitar / visité","pos":"verb","ex_en":"I visited my grandma on Sunday.","ex_es":"Visité a mi abuela el domingo."},{"en":"play / played","es":"jugar / jugué","pos":"verb","ex_en":"They played soccer in the park.","ex_es":"Jugaron futbol en el parque."},{"en":"stay / stayed","es":"quedarse / me quedé","pos":"verb","ex_en":"She stayed home all weekend.","ex_es":"Se quedó en casa todo el fin de semana."},{"en":"clean / cleaned","es":"limpiar / limpié","pos":"verb","ex_en":"I cleaned my room yesterday.","ex_es":"Limpié mi cuarto ayer."},{"en":"cook / cooked","es":"cocinar / cociné","pos":"verb","ex_en":"My dad cooked enchiladas for us.","ex_es":"Mi papá nos cocinó enchiladas."},{"en":"study / studied","es":"estudiar / estudié","pos":"verb","ex_en":"Luis studied English last night.","ex_es":"Luis estudió inglés anoche."},{"en":"call / called","es":"llamar / llamé","pos":"verb","ex_en":"I called my mom this morning.","ex_es":"Le hablé a mi mamá esta mañana."}],"sentences":[{"en":"I worked late on Friday.","es":"Trabajé tarde el viernes."},{"en":"We walked to the market.","es":"Caminamos al mercado."},{"en":"She listened to music all afternoon.","es":"Escuchó música toda la tarde."},{"en":"They watched TV and cooked dinner.","es":"Vieron la tele y cocinaron la cena."},{"en":"I visited Oaxaca with my family last summer.","es":"Visité Oaxaca con mi familia el verano pasado."}],"tip_es":"Los verbos regulares forman el pasado con -ed y es igual para todas las personas: I played, she played. Si terminan en consonante + y, cambian a -ied (study, studied), pero play y stay solo agregan -ed. Ojo: en worked y cooked la -ed suena como una t, no como sílaba extra."},{"id":"9-3","title_es":"Verbos irregulares","words":[{"en":"go / went","es":"ir / fui","pos":"verb","ex_en":"We went to the movies on Saturday.","ex_es":"Fuimos al cine el sábado."},{"en":"have / had","es":"tener / tuve","pos":"verb","ex_en":"I had a great weekend.","ex_es":"Tuve un fin de semana excelente."},{"en":"eat / ate","es":"comer / comí","pos":"verb","ex_en":"They ate tacos al pastor last night.","ex_es":"Comieron tacos al pastor anoche."},{"en":"see / saw","es":"ver / vi","pos":"verb","ex_en":"I saw your brother at the mall.","ex_es":"Vi a tu hermano en la plaza."},{"en":"buy / bought","es":"comprar / compré","pos":"verb","ex_en":"She bought new shoes yesterday.","ex_es":"Compró zapatos nuevos ayer."},{"en":"get / got","es":"llegar, conseguir / llegué","pos":"verb","ex_en":"I got home at eleven.","ex_es":"Llegué a casa a las once."},{"en":"make / made","es":"hacer / hice","pos":"verb","ex_en":"My grandma made tamales for everyone.","ex_es":"Mi abuela hizo tamales para todos."},{"en":"drink / drank","es":"tomar, beber / tomé","pos":"verb","ex_en":"We drank coffee after lunch.","ex_es":"Tomamos café después de comer."}],"sentences":[{"en":"I went to bed early.","es":"Me fui a dormir temprano."},{"en":"We had breakfast at a café.","es":"Desayunamos en un café."},{"en":"He bought a gift for his wife.","es":"Compró un regalo para su esposa."},{"en":"I saw a great movie last weekend.","es":"Vi una película muy buena el fin de semana pasado."},{"en":"My friends came over and we made pizza.","es":"Mis amigos vinieron y hicimos pizza."}],"tip_es":"Los verbos irregulares no usan -ed y hay que memorizarlos: go se vuelve went, eat se vuelve ate y buy se vuelve bought. La buena noticia es que la forma es igual para todas las personas: I went, she went, they went."},{"id":"9-4","title_es":"Preguntas y negativos con did","words":[{"en":"did","es":"auxiliar del pasado","pos":"verb","ex_en":"Did you have a good weekend?","ex_es":"¿Pasaste un buen fin de semana?"},{"en":"didn't","es":"no (en pasado)","pos":"verb","ex_en":"I didn't go to the party.","ex_es":"No fui a la fiesta."},{"en":"what did you do","es":"qué hiciste","pos":"phrase","ex_en":"What did you do on Sunday?","ex_es":"¿Qué hiciste el domingo?"},{"en":"how was","es":"qué tal estuvo","pos":"phrase","ex_en":"How was your trip to Guadalajara?","ex_es":"¿Qué tal tu viaje a Guadalajara?"},{"en":"fun","es":"divertido","pos":"adj","ex_en":"The party was really fun.","ex_es":"La fiesta estuvo muy divertida."},{"en":"boring","es":"aburrido","pos":"adj","ex_en":"The class was long and boring.","ex_es":"La clase fue larga y aburrida."},{"en":"relax / relaxed","es":"relajarse / me relajé","pos":"verb","ex_en":"We relaxed at home on Sunday.","ex_es":"Nos relajamos en casa el domingo."},{"en":"sleep / slept","es":"dormir / dormí","pos":"verb","ex_en":"I slept ten hours last night.","ex_es":"Dormí diez horas anoche."}],"sentences":[{"en":"Did you sleep well?","es":"¿Dormiste bien?"},{"en":"She didn't call me yesterday.","es":"No me habló ayer."},{"en":"Where did you go last weekend?","es":"¿A dónde fuiste el fin de semana pasado?"},{"en":"We didn't eat at home last night.","es":"No cenamos en casa anoche."},{"en":"Did they like the movie? Yes, they did.","es":"¿Les gustó la película? Sí, les gustó."}],"tip_es":"En preguntas y negativos el verbo regresa a su forma base, porque did ya marca el pasado: Did you go? I didn't go. Un error muy común es decir Did you went? o I didn't went. Ojo también: bored es cómo te sientes y boring es cómo es algo."},{"id":"9-5","title_es":"De vacaciones","words":[{"en":"vacation","es":"vacaciones","pos":"noun","ex_en":"We were on vacation in July.","ex_es":"Estuvimos de vacaciones en julio."},{"en":"beach","es":"playa","pos":"noun","ex_en":"The beach in Mazatlán was beautiful.","ex_es":"La playa de Mazatlán estaba hermosa."},{"en":"trip","es":"viaje","pos":"noun","ex_en":"Our trip to Chiapas was amazing.","ex_es":"Nuestro viaje a Chiapas fue increíble."},{"en":"travel / traveled","es":"viajar / viajé","pos":"verb","ex_en":"They traveled by bus to Mérida.","ex_es":"Viajaron en camión a Mérida."},{"en":"swim / swam","es":"nadar / nadé","pos":"verb","ex_en":"The kids swam in the ocean every day.","ex_es":"Los niños nadaron en el mar todos los días."},{"en":"take / took","es":"tomar / tomé","pos":"verb","ex_en":"I took a lot of pictures.","ex_es":"Tomé muchas fotos."},{"en":"souvenir","es":"recuerdo (de viaje)","pos":"noun","ex_en":"I bought a souvenir for my sister.","ex_es":"Compré un recuerdo para mi hermana."},{"en":"mountain","es":"montaña","pos":"noun","ex_en":"We climbed a mountain near the town.","ex_es":"Subimos una montaña cerca del pueblo."}],"sentences":[{"en":"How was your vacation?","es":"¿Qué tal tus vacaciones?"},{"en":"We stayed near the beach.","es":"Nos quedamos cerca de la playa."},{"en":"I didn't swim because the water was cold.","es":"No nadé porque el agua estaba fría."},{"en":"They took a trip to the mountains.","es":"Hicieron un viaje a las montañas."},{"en":"Last summer we traveled to Baja California by car.","es":"El verano pasado viajamos a Baja California en carro."}],"tip_es":"En inglés vacation casi siempre va en singular: my vacation was great, no my vacations were great. Además, en Estados Unidos se escribe traveled con una sola l, y travelled es la forma británica."},{"id":"9-6","title_es":"Contar una historia","words":[{"en":"first","es":"primero","pos":"adv","ex_en":"First, we had breakfast at the hotel.","ex_es":"Primero desayunamos en el hotel."},{"en":"then","es":"luego","pos":"adv","ex_en":"Then we walked to the museum.","ex_es":"Luego caminamos al museo."},{"en":"after that","es":"después de eso","pos":"phrase","ex_en":"After that, we ate lunch downtown.","ex_es":"Después de eso, comimos en el centro."},{"en":"finally","es":"al final, por fin","pos":"adv","ex_en":"Finally, we got home at midnight.","ex_es":"Al final, llegamos a casa a medianoche."},{"en":"suddenly","es":"de repente","pos":"adv","ex_en":"Suddenly, it started to rain.","ex_es":"De repente empezó a llover."},{"en":"lose / lost","es":"perder / perdí","pos":"verb","ex_en":"I lost my phone on the bus.","ex_es":"Perdí mi celular en el camión."},{"en":"find / found","es":"encontrar / encontré","pos":"verb","ex_en":"A nice man found my wallet.","ex_es":"Un señor amable encontró mi cartera."},{"en":"meet / met","es":"conocer / conocí","pos":"verb","ex_en":"I met my best friend in college.","ex_es":"Conocí a mi mejor amiga en la universidad."}],"sentences":[{"en":"First, I took a shower.","es":"Primero me bañé."},{"en":"Then I met Ana for coffee.","es":"Luego vi a Ana para tomar un café."},{"en":"Suddenly, the lights went out.","es":"De repente se fue la luz."},{"en":"After that, we looked for a taxi.","es":"Después de eso, buscamos un taxi."},{"en":"Finally, I found my wallet under the bed.","es":"Al final, encontré mi cartera debajo de la cama."}],"tip_es":"Para contar una historia en orden usa first, then, after that y finally. Ojo: meet en pasado (met) significa conocer a alguien por primera vez, no conocer un lugar. Para lugares se usa visit: I visited Oaxaca."}],"dialogue":{"title_es":"El lunes en la oficina","setting_es":"Un compañero te pregunta qué hiciste el fin de semana.","lines":[{"who":"A","en":"Hi! How was your weekend?","es":"¡Hola! ¿Qué tal tu fin de semana?"},{"who":"B","en":"It was great, thanks. I went to Tepoztlán.","es":"Estuvo muy bien, gracias. Fui a Tepoztlán."},{"who":"A","en":"Nice! Did you go with your family?","es":"¡Qué bien! ¿Fuiste con tu familia?"},{"who":"B","en":"No, I went with two friends from college.","es":"No, fui con dos amigos de la universidad."},{"who":"A","en":"What did you do there?","es":"¿Qué hicieron allá?"},{"who":"B","en":"First, we climbed the mountain. Then we ate quesadillas.","es":"Primero subimos el cerro. Luego comimos quesadillas."},{"who":"A","en":"Sounds fun. Did you take any pictures?","es":"Suena divertido. ¿Tomaste fotos?"},{"who":"B","en":"Yes, I took a lot. Look!","es":"Sí, tomé muchas. ¡Mira!"},{"who":"A","en":"Beautiful! I stayed home and slept all weekend.","es":"¡Qué bonito! Yo me quedé en casa y dormí todo el fin de semana."},{"who":"B","en":"That sounds good too!","es":"¡Eso también suena bien!"}]}},{"id":10,"title_es":"Trabajo y escuela","title_en":"Work and school","level":"A2","goal_es":"Al terminar podrás hablar de tu trabajo o tu escuela, de lo que sabes hacer y de tus obligaciones.","lessons":[{"id":"10-1","title_es":"Profesiones","words":[{"en":"job","es":"trabajo, empleo","pos":"noun","ex_en":"I like my new job a lot.","ex_es":"Me gusta mucho mi nuevo trabajo."},{"en":"engineer","es":"ingeniero","pos":"noun","ex_en":"My sister is an engineer.","ex_es":"Mi hermana es ingeniera."},{"en":"lawyer","es":"abogado","pos":"noun","ex_en":"He works as a lawyer downtown.","ex_es":"Trabaja como abogado en el centro."},{"en":"accountant","es":"contador","pos":"noun","ex_en":"An accountant helps me with my taxes.","ex_es":"Un contador me ayuda con mis impuestos."},{"en":"mechanic","es":"mecánico","pos":"noun","ex_en":"The mechanic is fixing my car.","ex_es":"El mecánico está arreglando mi carro."},{"en":"police officer","es":"policía","pos":"noun","ex_en":"The police officer is very friendly.","ex_es":"El policía es muy amable."},{"en":"firefighter","es":"bombero","pos":"noun","ex_en":"My uncle was a firefighter for twenty years.","ex_es":"Mi tío fue bombero durante veinte años."},{"en":"salesperson","es":"vendedor","pos":"noun","ex_en":"The salesperson showed me three phones.","ex_es":"El vendedor me enseñó tres celulares."}],"sentences":[{"en":"What do you do?","es":"¿A qué te dedicas?"},{"en":"I'm an accountant at a bank.","es":"Soy contador en un banco."},{"en":"She works in a hospital.","es":"Trabaja en un hospital."},{"en":"My mom wants to be a lawyer.","es":"Mi mamá quiere ser abogada."},{"en":"Before, I was a salesperson in a store.","es":"Antes era vendedor en una tienda."}],"tip_es":"En inglés siempre se pone a o an antes de la profesión: I am an engineer, she is a lawyer. Decir I am engineer es un error muy común. Para preguntar a qué se dedica alguien, lo más natural es What do you do?"},{"id":"10-2","title_es":"En la oficina","words":[{"en":"meeting","es":"junta, reunión","pos":"noun","ex_en":"We have a meeting at ten.","ex_es":"Tenemos una junta a las diez."},{"en":"boss","es":"jefe","pos":"noun","ex_en":"My boss is very patient.","ex_es":"Mi jefe es muy paciente."},{"en":"coworker","es":"compañero de trabajo","pos":"noun","ex_en":"I have lunch with my coworkers.","ex_es":"Como con mis compañeros de trabajo."},{"en":"email","es":"correo electrónico","pos":"noun","ex_en":"I send about fifty emails a day.","ex_es":"Mando como cincuenta correos al día."},{"en":"printer","es":"impresora","pos":"noun","ex_en":"The printer isn't working again.","ex_es":"La impresora no funciona otra vez."},{"en":"report","es":"reporte, informe","pos":"noun","ex_en":"I'm writing a report for my boss.","ex_es":"Estoy escribiendo un reporte para mi jefe."},{"en":"deadline","es":"fecha límite","pos":"noun","ex_en":"The deadline is next Friday.","ex_es":"La fecha límite es el próximo viernes."},{"en":"schedule","es":"horario","pos":"noun","ex_en":"My schedule is from nine to six.","ex_es":"Mi horario es de nueve a seis."}],"sentences":[{"en":"My office is on the third floor.","es":"Mi oficina está en el tercer piso."},{"en":"The meeting starts at nine.","es":"La junta empieza a las nueve."},{"en":"I answer emails every morning.","es":"Contesto correos todas las mañanas."},{"en":"My coworker is helping me with the report.","es":"Mi compañero me está ayudando con el reporte."},{"en":"Yesterday the meeting was very long and boring.","es":"Ayer la junta fue muy larga y aburrida."}],"tip_es":"Junta de trabajo se dice meeting, pero una reunión con amigos es get-together. Además, compañero de trabajo es coworker y compañero de clase es classmate. Para decir mando un correo se usa send: I send an email."},{"id":"10-3","title_es":"En la escuela","words":[{"en":"classroom","es":"salón de clases","pos":"noun","ex_en":"Our classroom has big windows.","ex_es":"Nuestro salón tiene ventanas grandes."},{"en":"homework","es":"tarea","pos":"noun","ex_en":"I do my homework after dinner.","ex_es":"Hago mi tarea después de cenar."},{"en":"exam","es":"examen","pos":"noun","ex_en":"We have a math exam tomorrow.","ex_es":"Mañana tenemos examen de matemáticas."},{"en":"grade","es":"calificación","pos":"noun","ex_en":"She got a good grade in English.","ex_es":"Sacó buena calificación en inglés."},{"en":"subject","es":"materia","pos":"noun","ex_en":"My favorite subject is history.","ex_es":"Mi materia favorita es historia."},{"en":"math","es":"matemáticas","pos":"noun","ex_en":"Math is difficult for me.","ex_es":"Las matemáticas son difíciles para mí."},{"en":"notebook","es":"cuaderno","pos":"noun","ex_en":"Write the new words in your notebook.","ex_es":"Escribe las palabras nuevas en tu cuaderno."},{"en":"pass","es":"pasar, aprobar","pos":"verb","ex_en":"I studied a lot and passed the exam.","ex_es":"Estudié mucho y pasé el examen."}],"sentences":[{"en":"Do you have homework today?","es":"¿Tienes tarea hoy?"},{"en":"The exam was very easy.","es":"El examen estuvo muy fácil."},{"en":"I didn't do my homework last night.","es":"No hice mi tarea anoche."},{"en":"What subject do you like the most?","es":"¿Qué materia te gusta más?"},{"en":"He got a bad grade because he didn't study.","es":"Sacó mala calificación porque no estudió."}],"tip_es":"Con homework se usa do, no make: I do my homework. Homework no tiene plural, así que nunca digas homeworks. Para presentar un examen se dice take an exam, y pass an exam significa pasarlo o aprobarlo."},{"id":"10-4","title_es":"Habilidades: can y can't","words":[{"en":"can","es":"poder, saber hacer","pos":"verb","ex_en":"I can speak two languages.","ex_es":"Sé hablar dos idiomas."},{"en":"can't","es":"no poder, no saber","pos":"verb","ex_en":"My brother can't swim.","ex_es":"Mi hermano no sabe nadar."},{"en":"drive","es":"manejar","pos":"verb","ex_en":"Can you drive a truck?","ex_es":"¿Sabes manejar un camión?"},{"en":"fix","es":"arreglar","pos":"verb","ex_en":"My dad can fix almost anything.","ex_es":"Mi papá puede arreglar casi cualquier cosa."},{"en":"draw","es":"dibujar","pos":"verb","ex_en":"She can draw really well.","ex_es":"Ella sabe dibujar muy bien."},{"en":"sing","es":"cantar","pos":"verb","ex_en":"I can't sing, but I can dance.","ex_es":"No sé cantar, pero sé bailar."},{"en":"well","es":"bien","pos":"adv","ex_en":"He speaks English very well.","ex_es":"Habla inglés muy bien."},{"en":"skill","es":"habilidad","pos":"noun","ex_en":"Cooking is a useful skill.","ex_es":"Cocinar es una habilidad útil."}],"sentences":[{"en":"Can you speak English?","es":"¿Hablas inglés?"},{"en":"I can type very fast.","es":"Escribo muy rápido en la computadora."},{"en":"She can't come to the meeting today.","es":"Ella no puede venir a la junta hoy."},{"en":"Can you help me with this report?","es":"¿Me puedes ayudar con este reporte?"},{"en":"My grandpa can fix cars, but he can't drive.","es":"Mi abuelo sabe arreglar carros, pero no sabe manejar."}],"tip_es":"Can sirve para poder y también para saber hacer algo: I can swim significa sé nadar. Después de can el verbo va sin to y sin -s: she can drive, nunca she can to drive ni she cans drive."},{"id":"10-5","title_es":"Obligaciones: have to","words":[{"en":"have to","es":"tener que","pos":"phrase","ex_en":"I have to work on Saturday.","ex_es":"Tengo que trabajar el sábado."},{"en":"has to","es":"tiene que","pos":"phrase","ex_en":"She has to wake up at five.","ex_es":"Ella tiene que despertarse a las cinco."},{"en":"don't have to","es":"no tener que","pos":"phrase","ex_en":"We don't have to wear a tie.","ex_es":"No tenemos que usar corbata."},{"en":"uniform","es":"uniforme","pos":"noun","ex_en":"Nurses have to wear a uniform.","ex_es":"Las enfermeras tienen que usar uniforme."},{"en":"on time","es":"a tiempo","pos":"phrase","ex_en":"You have to arrive on time.","ex_es":"Tienes que llegar a tiempo."},{"en":"rule","es":"regla","pos":"noun","ex_en":"The school has a lot of rules.","ex_es":"La escuela tiene muchas reglas."},{"en":"finish","es":"terminar","pos":"verb","ex_en":"I have to finish this report today.","ex_es":"Tengo que terminar este reporte hoy."},{"en":"shift","es":"turno","pos":"noun","ex_en":"My shift starts at seven.","ex_es":"Mi turno empieza a las siete."}],"sentences":[{"en":"Do you have to work tomorrow?","es":"¿Tienes que trabajar mañana?"},{"en":"He has to take the bus to work.","es":"Tiene que tomar el camión al trabajo."},{"en":"Students don't have to wear a uniform here.","es":"Aquí los alumnos no tienen que usar uniforme."},{"en":"I had to stay late at the office.","es":"Tuve que quedarme tarde en la oficina."},{"en":"Does she have to work the night shift?","es":"¿Ella tiene que trabajar en el turno de noche?"}],"tip_es":"Have to expresa obligación y cambia a has to con he, she e it. Don't have to significa que no es necesario, no que está prohibido. En pasado se dice had to: I had to work."},{"id":"10-6","title_es":"Buscar trabajo","words":[{"en":"apply","es":"postularse, solicitar","pos":"verb","ex_en":"I want to apply for that job.","ex_es":"Quiero postularme para ese trabajo."},{"en":"interview","es":"entrevista","pos":"noun","ex_en":"I have a job interview on Monday.","ex_es":"Tengo una entrevista de trabajo el lunes."},{"en":"salary","es":"sueldo","pos":"noun","ex_en":"The salary is good, but the hours are long.","ex_es":"El sueldo es bueno, pero el horario es largo."},{"en":"part-time","es":"de medio tiempo","pos":"adj","ex_en":"She has a part-time job at a café.","ex_es":"Tiene un trabajo de medio tiempo en un café."},{"en":"full-time","es":"de tiempo completo","pos":"adj","ex_en":"I'm looking for a full-time job.","ex_es":"Busco un trabajo de tiempo completo."},{"en":"experience","es":"experiencia","pos":"noun","ex_en":"Do you have experience in sales?","ex_es":"¿Tienes experiencia en ventas?"},{"en":"hire","es":"contratar","pos":"verb","ex_en":"The company wants to hire ten people.","ex_es":"La empresa quiere contratar a diez personas."},{"en":"resume","es":"currículum","pos":"noun","ex_en":"Send your resume by email.","ex_es":"Manda tu currículum por correo."}],"sentences":[{"en":"I'm looking for a new job.","es":"Estoy buscando un trabajo nuevo."},{"en":"How was your interview?","es":"¿Cómo te fue en tu entrevista?"},{"en":"They hired me last week!","es":"¡Me contrataron la semana pasada!"},{"en":"I have three years of experience as an accountant.","es":"Tengo tres años de experiencia como contador."},{"en":"Do I have to send my resume first?","es":"¿Tengo que mandar mi currículum primero?"}],"tip_es":"Para solicitar un empleo se usa apply for: I applied for the job. Experience en el sentido laboral no lleva a: I have experience, no I have an experience. En Estados Unidos el currículum se llama resume."}],"dialogue":{"title_es":"Primer día de trabajo","setting_es":"Es tu primer día en una empresa y una compañera te da la bienvenida.","lines":[{"who":"A","en":"Hi, you're the new engineer, right?","es":"Hola, tú eres el nuevo ingeniero, ¿verdad?"},{"who":"B","en":"Yes, I'm Carlos. Nice to meet you.","es":"Sí, soy Carlos. Mucho gusto."},{"who":"A","en":"I'm Laura. I work in accounting.","es":"Soy Laura. Trabajo en contabilidad."},{"who":"B","en":"Nice! What time do we have to arrive?","es":"¡Qué bien! ¿A qué hora tenemos que llegar?"},{"who":"A","en":"At eight thirty, but the schedule is flexible.","es":"A las ocho y media, pero el horario es flexible."},{"who":"B","en":"Great. Do I have to wear a uniform?","es":"Perfecto. ¿Tengo que usar uniforme?"},{"who":"A","en":"No. Can you come to a meeting at ten?","es":"No. ¿Puedes venir a una junta a las diez?"},{"who":"B","en":"Sure. Where is the meeting room?","es":"Claro. ¿Dónde está la sala de juntas?"},{"who":"A","en":"It's on the second floor, next to the printer.","es":"Está en el segundo piso, junto a la impresora."},{"who":"B","en":"Perfect. Thanks for your help, Laura!","es":"Perfecto. ¡Gracias por tu ayuda, Laura!"}]}},{"id":11,"title_es":"Salud y cuerpo","title_en":"Health and the body","level":"A2","goal_es":"Al terminar podrás nombrar las partes del cuerpo, describir síntomas, ir al doctor y dar consejos de salud.","lessons":[{"id":"11-1","title_es":"El cuerpo","words":[{"en":"head","es":"cabeza","pos":"noun","ex_en":"I hit my head on the door.","ex_es":"Me pegué en la cabeza con la puerta."},{"en":"arm","es":"brazo","pos":"noun","ex_en":"My arm is very tired.","ex_es":"Tengo el brazo muy cansado."},{"en":"leg","es":"pierna","pos":"noun","ex_en":"He has long legs.","ex_es":"Tiene las piernas largas."},{"en":"hand","es":"mano","pos":"noun","ex_en":"Raise your hand, please.","ex_es":"Levanta la mano, por favor."},{"en":"foot","es":"pie","pos":"noun","ex_en":"My left foot is cold.","ex_es":"Tengo el pie izquierdo frío."},{"en":"back","es":"espalda","pos":"noun","ex_en":"Carrying heavy boxes is bad for your back.","ex_es":"Cargar cajas pesadas es malo para la espalda."},{"en":"neck","es":"cuello","pos":"noun","ex_en":"The giraffe has a very long neck.","ex_es":"La jirafa tiene el cuello muy largo."},{"en":"shoulder","es":"hombro","pos":"noun","ex_en":"Put the bag on your shoulder.","ex_es":"Ponte la bolsa en el hombro."}],"sentences":[{"en":"Wash your hands before dinner.","es":"Lávate las manos antes de cenar."},{"en":"My feet are tired.","es":"Tengo los pies cansados."},{"en":"Touch your head with your right hand.","es":"Tócate la cabeza con la mano derecha."},{"en":"I walked a lot and my legs are tired.","es":"Caminé mucho y tengo las piernas cansadas."},{"en":"He carried his son on his shoulders.","es":"Cargó a su hijo en los hombros."}],"tip_es":"En inglés se usa el posesivo con las partes del cuerpo: wash your hands, I hit my head. En español decimos la mano, pero en inglés the hand suena raro en estos casos. Ojo con el plural irregular: one foot, two feet."},{"id":"11-2","title_es":"Más partes del cuerpo","words":[{"en":"knee","es":"rodilla","pos":"noun","ex_en":"I hit my knee on the table.","ex_es":"Me pegué en la rodilla con la mesa."},{"en":"finger","es":"dedo (de la mano)","pos":"noun","ex_en":"She has a ring on every finger.","ex_es":"Tiene un anillo en cada dedo."},{"en":"toe","es":"dedo del pie","pos":"noun","ex_en":"I hit my toe on the bed.","ex_es":"Me pegué en el dedo del pie con la cama."},{"en":"stomach","es":"estómago","pos":"noun","ex_en":"My stomach is making noise.","ex_es":"Me está sonando el estómago."},{"en":"tooth","es":"diente","pos":"noun","ex_en":"My son lost his first tooth.","ex_es":"A mi hijo se le cayó su primer diente."},{"en":"ear","es":"oreja, oído","pos":"noun","ex_en":"She has small ears.","ex_es":"Tiene las orejas pequeñas."},{"en":"nose","es":"nariz","pos":"noun","ex_en":"My nose is red because of the cold.","ex_es":"Tengo la nariz roja por el frío."},{"en":"chest","es":"pecho","pos":"noun","ex_en":"The ball hit him in the chest.","ex_es":"La pelota le pegó en el pecho."}],"sentences":[{"en":"Brush your teeth after every meal.","es":"Lávate los dientes después de cada comida."},{"en":"Babies have very small fingers.","es":"Los bebés tienen dedos muy pequeños."},{"en":"Close your eyes and touch your nose.","es":"Cierra los ojos y tócate la nariz."},{"en":"The dentist checked all my teeth.","es":"El dentista revisó todos mis dientes."},{"en":"Wear a hat to cover your ears.","es":"Ponte un gorro para taparte las orejas."}],"tip_es":"Tooth tiene plural irregular: one tooth, two teeth (igual que foot, feet). Finger son los dedos de la mano y toe los del pie. Ear puede ser oreja u oído, según el contexto."},{"id":"11-3","title_es":"¿Cómo te sientes? Síntomas","words":[{"en":"sick","es":"enfermo","pos":"adj","ex_en":"I feel sick today.","ex_es":"Hoy me siento enfermo."},{"en":"headache","es":"dolor de cabeza","pos":"noun","ex_en":"I have a terrible headache.","ex_es":"Tengo un dolor de cabeza terrible."},{"en":"fever","es":"fiebre","pos":"noun","ex_en":"The baby has a fever.","ex_es":"El bebé tiene fiebre."},{"en":"cough","es":"tos","pos":"noun","ex_en":"My cough is worse at night.","ex_es":"Mi tos empeora en la noche."},{"en":"cold","es":"gripa, resfriado","pos":"noun","ex_en":"I think I have a cold.","ex_es":"Creo que tengo gripa."},{"en":"sore throat","es":"dolor de garganta","pos":"noun","ex_en":"I have a sore throat and I can't talk.","ex_es":"Me duele la garganta y no puedo hablar."},{"en":"hurt","es":"doler","pos":"verb","ex_en":"My back hurts a lot.","ex_es":"Me duele mucho la espalda."},{"en":"dizzy","es":"mareado","pos":"adj","ex_en":"I feel dizzy when I stand up.","ex_es":"Me mareo cuando me paro."}],"sentences":[{"en":"What's wrong?","es":"¿Qué tienes?"},{"en":"How do you feel today?","es":"¿Cómo te sientes hoy?"},{"en":"My head hurts and I feel dizzy.","es":"Me duele la cabeza y me siento mareado."},{"en":"She stayed home because she had a fever.","es":"Se quedó en casa porque tenía fiebre."},{"en":"I have a bad cough and a sore throat.","es":"Tengo mucha tos y me duele la garganta."}],"tip_es":"Para los síntomas se usa have: I have a headache, I have a fever, nunca I am fever. Con hurt, la parte del cuerpo es el sujeto: my head hurts, my feet hurt. No digas me hurts the head."},{"id":"11-4","title_es":"En el doctor","words":[{"en":"appointment","es":"cita","pos":"noun","ex_en":"I have a doctor's appointment at four.","ex_es":"Tengo cita con el doctor a las cuatro."},{"en":"patient","es":"paciente","pos":"noun","ex_en":"The doctor has many patients today.","ex_es":"El doctor tiene muchos pacientes hoy."},{"en":"medicine","es":"medicina","pos":"noun","ex_en":"Take this medicine after meals.","ex_es":"Tómate esta medicina después de las comidas."},{"en":"pill","es":"pastilla","pos":"noun","ex_en":"Take one pill every eight hours.","ex_es":"Tómate una pastilla cada ocho horas."},{"en":"prescription","es":"receta médica","pos":"noun","ex_en":"You need a prescription for this medicine.","ex_es":"Necesitas receta para esta medicina."},{"en":"pharmacy","es":"farmacia","pos":"noun","ex_en":"Is there a pharmacy near here?","ex_es":"¿Hay una farmacia cerca de aquí?"},{"en":"temperature","es":"temperatura","pos":"noun","ex_en":"The nurse took my temperature.","ex_es":"La enfermera me tomó la temperatura."},{"en":"allergic","es":"alérgico","pos":"adj","ex_en":"I'm allergic to penicillin.","ex_es":"Soy alérgico a la penicilina."}],"sentences":[{"en":"I'd like to make an appointment, please.","es":"Quisiera hacer una cita, por favor."},{"en":"What are your symptoms?","es":"¿Cuáles son sus síntomas?"},{"en":"Are you allergic to any medicine?","es":"¿Es alérgico a alguna medicina?"},{"en":"The doctor gave me a prescription for my cough.","es":"El doctor me dio una receta para la tos."},{"en":"I bought the pills at the pharmacy yesterday.","es":"Compré las pastillas en la farmacia ayer."}],"tip_es":"Ojo con este falso amigo: la receta del doctor es prescription, y la receta de cocina es recipe. Con medicinas se usa el verbo take: take a pill, take this medicine. Y alérgico a se dice allergic to."},{"id":"11-5","title_es":"Consejos: should y shouldn't","words":[{"en":"should","es":"deberías, debería","pos":"verb","ex_en":"You should see a doctor.","ex_es":"Deberías ir al doctor."},{"en":"shouldn't","es":"no deberías","pos":"verb","ex_en":"You shouldn't eat so much sugar.","ex_es":"No deberías comer tanta azúcar."},{"en":"rest","es":"descansar","pos":"verb","ex_en":"You should rest for two days.","ex_es":"Deberías descansar dos días."},{"en":"advice","es":"consejo","pos":"noun","ex_en":"Can I give you some advice?","ex_es":"¿Te puedo dar un consejo?"},{"en":"healthy","es":"saludable, sano","pos":"adj","ex_en":"Fruit and vegetables are healthy.","ex_es":"Las frutas y verduras son saludables."},{"en":"exercise","es":"hacer ejercicio","pos":"verb","ex_en":"I exercise three times a week.","ex_es":"Hago ejercicio tres veces por semana."},{"en":"stay in bed","es":"quedarse en cama","pos":"phrase","ex_en":"The doctor told me to stay in bed.","ex_es":"El doctor me dijo que me quedara en cama."},{"en":"junk food","es":"comida chatarra","pos":"noun","ex_en":"Kids shouldn't eat a lot of junk food.","ex_es":"Los niños no deberían comer mucha comida chatarra."}],"sentences":[{"en":"You should drink more water.","es":"Deberías tomar más agua."},{"en":"What should I do?","es":"¿Qué debería hacer?"},{"en":"You shouldn't go to work with a fever.","es":"No deberías ir a trabajar con fiebre."},{"en":"Should I take this medicine with food?","es":"¿Debo tomar esta medicina con comida?"},{"en":"My doctor gave me good advice about healthy food.","es":"Mi doctor me dio buenos consejos sobre comida saludable."}],"tip_es":"Should sirve para dar consejos y va seguido del verbo sin to: you should rest, no you should to rest. Advice es incontable: se dice some advice o a piece of advice, nunca an advice ni advices."},{"id":"11-6","title_es":"Accidentes y emergencias","words":[{"en":"emergency","es":"emergencia","pos":"noun","ex_en":"Call 911, it's an emergency!","ex_es":"¡Llama al 911, es una emergencia!"},{"en":"ambulance","es":"ambulancia","pos":"noun","ex_en":"The ambulance arrived in ten minutes.","ex_es":"La ambulancia llegó en diez minutos."},{"en":"hospital","es":"hospital","pos":"noun","ex_en":"They took him to the hospital.","ex_es":"Lo llevaron al hospital."},{"en":"break / broke","es":"romper / me rompí","pos":"verb","ex_en":"I broke my arm playing soccer.","ex_es":"Me rompí el brazo jugando futbol."},{"en":"cut","es":"cortar, cortarse","pos":"verb","ex_en":"Be careful, you can cut your finger.","ex_es":"Cuidado, te puedes cortar el dedo."},{"en":"fall / fell","es":"caerse / me caí","pos":"verb","ex_en":"My grandpa fell down the stairs.","ex_es":"Mi abuelo se cayó de las escaleras."},{"en":"burn","es":"quemar, quemarse","pos":"verb","ex_en":"Don't touch the pan, you can burn your hand.","ex_es":"No toques el sartén, te puedes quemar la mano."},{"en":"bandage","es":"venda, curita","pos":"noun","ex_en":"Put a bandage on that cut.","ex_es":"Ponte una venda en esa cortada."}],"sentences":[{"en":"Help! Call an ambulance!","es":"¡Ayuda! ¡Llamen a una ambulancia!"},{"en":"Are you OK? Did you fall?","es":"¿Estás bien? ¿Te caíste?"},{"en":"I cut my finger with a knife.","es":"Me corté el dedo con un cuchillo."},{"en":"You should go to the hospital right now.","es":"Deberías ir al hospital ahora mismo."},{"en":"She fell off her bike and broke her wrist.","es":"Se cayó de la bici y se rompió la muñeca."}],"tip_es":"Break, fall y cut son verbos irregulares: broke, fell y cut (cut no cambia en pasado). Para decir me rompí el brazo se usa el posesivo: I broke my arm. En Estados Unidos el número de emergencias también es 911."}],"dialogue":{"title_es":"En el consultorio","setting_es":"No te sientes bien y vas con el doctor.","lines":[{"who":"A","en":"Good morning. What's wrong?","es":"Buenos días. ¿Qué tiene?"},{"who":"B","en":"I feel sick. I have a headache and fever.","es":"Me siento mal. Tengo dolor de cabeza y fiebre."},{"who":"A","en":"When did it start?","es":"¿Cuándo empezó?"},{"who":"B","en":"Two days ago. I also have a bad cough.","es":"Hace dos días. También tengo mucha tos."},{"who":"A","en":"Let me check your throat. Does it hurt?","es":"Déjeme revisarle la garganta. ¿Le duele?"},{"who":"B","en":"Yes, a little. Is it serious?","es":"Sí, un poco. ¿Es grave?"},{"who":"A","en":"No, it's just a bad cold.","es":"No, es solo una gripa fuerte."},{"who":"B","en":"What should I do?","es":"¿Qué debo hacer?"},{"who":"A","en":"You should rest and drink a lot of water.","es":"Debe descansar y tomar mucha agua."},{"who":"B","en":"OK. Do I need a prescription?","es":"Está bien. ¿Necesito receta?"}]}},{"id":12,"title_es":"Viajes: aeropuerto y hotel","title_en":"Airports and hotels","level":"B1","goal_es":"Al terminar podrás moverte en un aeropuerto, reservar un hotel, resolver problemas y pedir favores con amabilidad.","lessons":[{"id":"12-1","title_es":"En el aeropuerto","words":[{"en":"flight","es":"vuelo","pos":"noun","ex_en":"Our flight to Chicago leaves at six in the morning.","ex_es":"Nuestro vuelo a Chicago sale a las seis de la mañana."},{"en":"passport","es":"pasaporte","pos":"noun","ex_en":"Don't forget your passport, you need it for international flights.","ex_es":"No olvides tu pasaporte, lo necesitas para vuelos internacionales."},{"en":"boarding pass","es":"pase de abordar","pos":"noun","ex_en":"You can download your boarding pass on your phone.","ex_es":"Puedes descargar tu pase de abordar en tu celular."},{"en":"gate","es":"puerta (de embarque)","pos":"noun","ex_en":"Our flight is now boarding at gate twelve.","ex_es":"Nuestro vuelo ya está abordando en la puerta doce."},{"en":"check in","es":"registrarse, hacer check-in","pos":"phrase","ex_en":"We have to check in two hours before the flight.","ex_es":"Tenemos que hacer el check-in dos horas antes del vuelo."},{"en":"luggage","es":"equipaje","pos":"noun","ex_en":"How much luggage can I bring on this flight?","ex_es":"¿Cuánto equipaje puedo llevar en este vuelo?"},{"en":"carry-on","es":"maleta de mano","pos":"noun","ex_en":"My carry-on is too big for the overhead bin.","ex_es":"Mi maleta de mano es demasiado grande para el compartimento."},{"en":"departure","es":"salida","pos":"noun","ex_en":"Check the departure time on the screen.","ex_es":"Revisa la hora de salida en la pantalla."}],"sentences":[{"en":"Excuse me, where is gate twenty?","es":"Disculpe, ¿dónde está la puerta veinte?"},{"en":"Can I see your passport and boarding pass, please?","es":"¿Me permite su pasaporte y su pase de abordar, por favor?"},{"en":"Do you have any luggage to check?","es":"¿Tiene equipaje para documentar?"},{"en":"I only have a carry-on and a small backpack.","es":"Solo traigo una maleta de mano y una mochila pequeña."},{"en":"The departures board says our flight is on time.","es":"La pantalla de salidas dice que nuestro vuelo va a tiempo."}],"tip_es":"Check in significa registrarse, en el aeropuerto o en el hotel. Luggage y baggage son incontables: se dice two pieces of luggage o two bags, nunca two luggages."},{"id":"12-2","title_es":"En el avión","words":[{"en":"security","es":"control de seguridad","pos":"noun","ex_en":"The line at security was very long this morning.","ex_es":"La fila en el control de seguridad estaba muy larga esta mañana."},{"en":"delayed","es":"retrasado","pos":"adj","ex_en":"Our flight was delayed because of the storm.","ex_es":"Nuestro vuelo se retrasó por la tormenta."},{"en":"aisle seat","es":"asiento de pasillo","pos":"noun","ex_en":"I prefer an aisle seat on long flights.","ex_es":"Prefiero un asiento de pasillo en vuelos largos."},{"en":"window seat","es":"asiento de ventanilla","pos":"noun","ex_en":"My son always wants the window seat.","ex_es":"Mi hijo siempre quiere el asiento de ventanilla."},{"en":"take off","es":"despegar","pos":"phrase","ex_en":"The plane can't take off because of the snow.","ex_es":"El avión no puede despegar por la nieve."},{"en":"land","es":"aterrizar","pos":"verb","ex_en":"We landed in Los Angeles at midnight.","ex_es":"Aterrizamos en Los Ángeles a medianoche."},{"en":"seat belt","es":"cinturón de seguridad","pos":"noun","ex_en":"Please fasten your seat belt.","ex_es":"Por favor, abróchese el cinturón de seguridad."},{"en":"flight attendant","es":"sobrecargo","pos":"noun","ex_en":"The flight attendant brought me a glass of water.","ex_es":"La sobrecargo me trajo un vaso de agua."}],"sentences":[{"en":"Please put your laptop in a separate tray.","es":"Por favor, ponga su laptop en una charola aparte."},{"en":"Our flight is delayed two hours.","es":"Nuestro vuelo tiene dos horas de retraso."},{"en":"I asked for an aisle seat, but they gave me the middle seat.","es":"Pedí un asiento de pasillo, pero me dieron el de en medio."},{"en":"Keep your seat belt on until the plane stops.","es":"Mantenga el cinturón abrochado hasta que el avión se detenga."},{"en":"The flight attendant told us to turn off our phones.","es":"La sobrecargo nos dijo que apagáramos los celulares."}],"tip_es":"Para hablar de retrasos se usa be delayed: my flight is delayed two hours. Take off (despegar) es un phrasal verb y en pasado es took off. Su opuesto es land (aterrizar), que es regular: landed."},{"id":"12-3","title_es":"Reservar un hotel","words":[{"en":"reservation","es":"reservación","pos":"noun","ex_en":"I'd like to make a reservation for three nights.","ex_es":"Quisiera hacer una reservación para tres noches."},{"en":"book","es":"reservar","pos":"verb","ex_en":"We booked the hotel online last month.","ex_es":"Reservamos el hotel en línea el mes pasado."},{"en":"single room","es":"habitación sencilla","pos":"noun","ex_en":"A single room costs eighty dollars a night.","ex_es":"Una habitación sencilla cuesta ochenta dólares la noche."},{"en":"double room","es":"habitación doble","pos":"noun","ex_en":"Do you have a double room for this weekend?","ex_es":"¿Tienen una habitación doble para este fin de semana?"},{"en":"available","es":"disponible","pos":"adj","ex_en":"Sorry, we don't have any rooms available tonight.","ex_es":"Lo siento, no tenemos habitaciones disponibles esta noche."},{"en":"per night","es":"por noche","pos":"phrase","ex_en":"How much is the room per night?","ex_es":"¿Cuánto cuesta la habitación por noche?"},{"en":"check out","es":"entregar la habitación","pos":"phrase","ex_en":"What time do we have to check out?","ex_es":"¿A qué hora tenemos que entregar la habitación?"},{"en":"front desk","es":"recepción","pos":"noun","ex_en":"Please leave your key at the front desk.","ex_es":"Por favor, deje su llave en la recepción."}],"sentences":[{"en":"Is breakfast included in the price?","es":"¿El desayuno está incluido en el precio?"},{"en":"I booked a double room for two nights.","es":"Reservé una habitación doble para dos noches."},{"en":"Do you have any rooms available for next Friday?","es":"¿Tienen habitaciones disponibles para el próximo viernes?"},{"en":"Check out is at noon, but you can leave your bags here.","es":"La salida es a mediodía, pero puede dejar sus maletas aquí."},{"en":"Your reservation is under the name Martínez, is that correct?","es":"Su reservación está a nombre de Martínez, ¿es correcto?"}],"tip_es":"En el habla diaria se usa book mucho más que reserve: I booked a room. Para decir a nombre de se usa under: the reservation is under Martínez. Ojo: una habitación doble es double room, no double habitation."},{"id":"12-4","title_es":"En el hotel","words":[{"en":"key card","es":"tarjeta de la habitación","pos":"noun","ex_en":"My key card doesn't open the door.","ex_es":"Mi tarjeta no abre la puerta."},{"en":"towel","es":"toalla","pos":"noun","ex_en":"We need two more towels, please.","ex_es":"Necesitamos dos toallas más, por favor."},{"en":"elevator","es":"elevador","pos":"noun","ex_en":"The elevator is at the end of the hall.","ex_es":"El elevador está al final del pasillo."},{"en":"room service","es":"servicio a la habitación","pos":"noun","ex_en":"We ordered room service because we were very tired.","ex_es":"Pedimos servicio a la habitación porque estábamos muy cansados."},{"en":"wake-up call","es":"llamada para despertar","pos":"noun","ex_en":"I asked for a wake-up call at six.","ex_es":"Pedí una llamada para despertarme a las seis."},{"en":"password","es":"contraseña","pos":"noun","ex_en":"What's the password for the Wi-Fi?","ex_es":"¿Cuál es la contraseña del wifi?"},{"en":"pool","es":"alberca","pos":"noun","ex_en":"The pool is open from eight to ten.","ex_es":"La alberca está abierta de ocho a diez."},{"en":"guest","es":"huésped","pos":"noun","ex_en":"Hotel guests get a free breakfast every morning.","ex_es":"Los huéspedes del hotel tienen desayuno gratis todas las mañanas."}],"sentences":[{"en":"Your room is on the fifth floor.","es":"Su habitación está en el quinto piso."},{"en":"Take the elevator and turn left.","es":"Tome el elevador y dé vuelta a la izquierda."},{"en":"Here is your key card and the Wi-Fi password.","es":"Aquí tiene su tarjeta y la contraseña del wifi."},{"en":"Is the pool open for guests after nine at night?","es":"¿La alberca está abierta para los huéspedes después de las nueve de la noche?"},{"en":"I'd like to order room service for breakfast tomorrow.","es":"Quisiera pedir servicio a la habitación para el desayuno de mañana."}],"tip_es":"En Estados Unidos se dice elevator, no lift, que es británico. Ojo con los pisos: en EE. UU. la planta baja es el first floor, así que su second floor es nuestro primer piso."},{"id":"12-5","title_es":"Problemas y quejas","words":[{"en":"complaint","es":"queja","pos":"noun","ex_en":"I'd like to make a complaint about my room.","ex_es":"Quisiera poner una queja sobre mi habitación."},{"en":"noisy","es":"ruidoso","pos":"adj","ex_en":"The room next to ours was very noisy all night.","ex_es":"El cuarto de al lado estuvo muy ruidoso toda la noche."},{"en":"dirty","es":"sucio","pos":"adj","ex_en":"The bathroom was dirty when we arrived.","ex_es":"El baño estaba sucio cuando llegamos."},{"en":"refund","es":"reembolso","pos":"noun","ex_en":"The airline gave me a full refund.","ex_es":"La aerolínea me dio un reembolso completo."},{"en":"air conditioning","es":"aire acondicionado","pos":"noun","ex_en":"The air conditioning in our room doesn't work.","ex_es":"El aire acondicionado de nuestro cuarto no funciona."},{"en":"miss","es":"perder (un vuelo, un camión)","pos":"verb","ex_en":"We missed our connecting flight in Dallas.","ex_es":"Perdimos nuestro vuelo de conexión en Dallas."},{"en":"upgrade","es":"mejora de categoría","pos":"noun","ex_en":"They gave us a free upgrade to a suite.","ex_es":"Nos subieron gratis de categoría a una suite."},{"en":"apologize","es":"disculparse","pos":"verb","ex_en":"The manager apologized for the problem.","ex_es":"El gerente se disculpó por el problema."}],"sentences":[{"en":"There's no hot water in my room.","es":"No hay agua caliente en mi cuarto."},{"en":"The towels in the bathroom are dirty.","es":"Las toallas del baño están sucias."},{"en":"I'm sorry, but the room is too noisy to sleep.","es":"Lo siento, pero el cuarto es demasiado ruidoso para dormir."},{"en":"The airline lost my luggage and I need help.","es":"La aerolínea perdió mi equipaje y necesito ayuda."},{"en":"We missed our flight, so we asked for a refund.","es":"Perdimos el vuelo, así que pedimos un reembolso."}],"tip_es":"Para perder un vuelo o un camión se usa miss, no lose: I missed my flight. Lose es perder un objeto: I lost my passport. Una queja amable suele empezar con I'm sorry, but y luego el problema."},{"id":"12-6","title_es":"Pedir favores con could you","words":[{"en":"could you","es":"podría usted, podrías","pos":"phrase","ex_en":"Could you help me with my bags, please?","ex_es":"¿Podría ayudarme con mis maletas, por favor?"},{"en":"could I","es":"podría yo","pos":"phrase","ex_en":"Could I have a map of the city?","ex_es":"¿Me podría dar un mapa de la ciudad?"},{"en":"would you mind","es":"le molestaría","pos":"phrase","ex_en":"Would you mind taking a picture of us?","ex_es":"¿Le molestaría tomarnos una foto?"},{"en":"recommend","es":"recomendar","pos":"verb","ex_en":"Can you recommend a good restaurant near the hotel?","ex_es":"¿Me puede recomendar un buen restaurante cerca del hotel?"},{"en":"store","es":"guardar","pos":"verb","ex_en":"Could you store our bags until three?","ex_es":"¿Nos podría guardar las maletas hasta las tres?"},{"en":"call a taxi","es":"pedir un taxi","pos":"phrase","ex_en":"The receptionist can call a taxi for you.","ex_es":"La recepcionista le puede pedir un taxi."},{"en":"sightseeing","es":"turismo, conocer lugares","pos":"noun","ex_en":"We spent the whole day sightseeing downtown.","ex_es":"Pasamos todo el día conociendo el centro."},{"en":"tip","es":"propina","pos":"noun","ex_en":"In the United States, people usually leave a tip of twenty percent.","ex_es":"En Estados Unidos, la gente normalmente deja veinte por ciento de propina."}],"sentences":[{"en":"Could you speak more slowly, please?","es":"¿Podría hablar más despacio, por favor?"},{"en":"Could I check out a little later tomorrow?","es":"¿Podría entregar la habitación un poco más tarde mañana?"},{"en":"Would you mind waiting five minutes?","es":"¿Le molestaría esperar cinco minutos?"},{"en":"What places do you recommend for sightseeing in the city?","es":"¿Qué lugares me recomienda para conocer la ciudad?"},{"en":"Could you call a taxi to take us to the airport?","es":"¿Podría pedirnos un taxi para ir al aeropuerto?"}],"tip_es":"Could you es más amable que can you y es ideal con desconocidos. Después de would you mind el verbo va con -ing: would you mind waiting? Para aceptar se responde no, not at all, porque significa no me molesta."}],"dialogue":{"title_es":"Llegada al hotel","setting_es":"Llegas a tu hotel en San Francisco después de un vuelo largo.","lines":[{"who":"A","en":"Good evening and welcome. How can I help you?","es":"Buenas noches y bienvenido. ¿En qué le puedo ayudar?"},{"who":"B","en":"Hi, I have a reservation under the name Ramírez.","es":"Hola, tengo una reservación a nombre de Ramírez."},{"who":"A","en":"Let me check. Yes, a double room for three nights.","es":"Déjeme revisar. Sí, una habitación doble por tres noches."},{"who":"B","en":"That's right. Is breakfast included?","es":"Así es. ¿El desayuno está incluido?"},{"who":"A","en":"Yes, it's served from seven to ten in the restaurant.","es":"Sí, se sirve de siete a diez en el restaurante."},{"who":"B","en":"Great. Could I check out at one on Sunday?","es":"Perfecto. ¿Podría entregar la habitación a la una el domingo?"},{"who":"A","en":"Sure, no problem. Here is your key card. You're in room 504.","es":"Claro, sin problema. Aquí tiene su tarjeta. Está en la habitación 504."},{"who":"B","en":"Thank you. What's the password for the Wi-Fi?","es":"Gracias. ¿Cuál es la contraseña del wifi?"},{"who":"A","en":"It's on the card, next to your room number.","es":"Está en la tarjeta, junto al número de su habitación."},{"who":"B","en":"Perfect. Thanks for your help!","es":"Perfecto. ¡Gracias por su ayuda!"}]}},{"id":13,"title_es":"Planes y futuro","title_en":"Plans and the future","level":"B1","goal_es":"Al terminar podrás hablar de tus planes, hacer predicciones, hacer promesas y aceptar o rechazar invitaciones.","lessons":[{"id":"13-1","title_es":"Planes con going to","words":[{"en":"going to","es":"ir a (futuro)","pos":"phrase","ex_en":"I'm going to visit my aunt next month.","ex_es":"Voy a visitar a mi tía el próximo mes."},{"en":"save up","es":"ahorrar","pos":"verb","ex_en":"We want to save up for a new car.","ex_es":"Queremos ahorrar para un coche nuevo."},{"en":"move out","es":"mudarse (dejar la casa)","pos":"verb","ex_en":"My brother is going to move out in June.","ex_es":"Mi hermano se va a mudar en junio."},{"en":"sign up","es":"inscribirse","pos":"verb","ex_en":"I'm going to sign up for a yoga class.","ex_es":"Me voy a inscribir a una clase de yoga."},{"en":"get married","es":"casarse","pos":"phrase","ex_en":"They're going to get married in December.","ex_es":"Se van a casar en diciembre."},{"en":"take a break","es":"tomar un descanso","pos":"phrase","ex_en":"After the exam, I'm going to take a break.","ex_es":"Después del examen, voy a tomar un descanso."},{"en":"remodel","es":"remodelar","pos":"verb","ex_en":"My parents are going to remodel the kitchen.","ex_es":"Mis papás van a remodelar la cocina."},{"en":"the day after tomorrow","es":"pasado mañana","pos":"phrase","ex_en":"We're leaving the day after tomorrow.","ex_es":"Nos vamos pasado mañana."}],"sentences":[{"en":"What are you going to do this weekend?","es":"¿Qué vas a hacer este fin de semana?"},{"en":"I'm going to stay home and relax.","es":"Me voy a quedar en casa a descansar."},{"en":"She isn't going to work tomorrow.","es":"Ella no va a trabajar mañana."},{"en":"Are you going to sign up for the English course?","es":"¿Te vas a inscribir al curso de inglés?"},{"en":"We're going to save up and travel to Oaxaca next year.","es":"Vamos a ahorrar y viajar a Oaxaca el próximo año."}],"tip_es":"Usa going to para planes que ya decidiste antes de hablar. La estructura es sujeto + am/is/are + going to + verbo base: I'm going to study. En conversación suena como gonna, pero no lo escribas en textos formales."},{"id":"13-2","title_es":"Decisiones y promesas con will","words":[{"en":"promise","es":"prometer","pos":"verb","ex_en":"I promise I'll call you tonight.","ex_es":"Te prometo que te llamo hoy en la noche."},{"en":"offer","es":"ofrecer","pos":"verb","ex_en":"He didn't offer to help us.","ex_es":"Él no se ofreció a ayudarnos."},{"en":"decide","es":"decidir","pos":"verb","ex_en":"I can't decide what to order.","ex_es":"No puedo decidir qué pedir."},{"en":"pick up","es":"recoger","pos":"verb","ex_en":"I'll pick up the kids after school.","ex_es":"Yo recojo a los niños después de la escuela."},{"en":"help out","es":"echar la mano","pos":"verb","ex_en":"I'll help out with the party on Saturday.","ex_es":"Yo echo la mano con la fiesta el sábado."},{"en":"right away","es":"de inmediato","pos":"adv","ex_en":"I'll send you the address right away.","ex_es":"Te mando la dirección de inmediato."},{"en":"on second thought","es":"pensándolo bien","pos":"phrase","ex_en":"On second thought, I'll have the soup.","ex_es":"Pensándolo bien, voy a pedir la sopa."},{"en":"I'll get it","es":"yo voy, yo contesto","pos":"phrase","ex_en":"Someone's at the door. I'll get it!","ex_es":"Alguien está tocando. ¡Yo voy!"}],"sentences":[{"en":"Don't worry, I'll help you with the boxes.","es":"No te preocupes, te ayudo con las cajas."},{"en":"I promise I won't be late again.","es":"Te prometo que no voy a llegar tarde otra vez."},{"en":"It's cold in here. I'll close the window.","es":"Hace frío aquí. Voy a cerrar la ventana."},{"en":"Will you pick me up at the station?","es":"¿Me recoges en la estación?"},{"en":"I think I'll take the bus today.","es":"Creo que hoy me voy a ir en camión."}],"tip_es":"Usa will para decisiones que tomas en el momento, promesas y ofrecimientos. La forma negativa es won't. Ojo: en español muchas veces usamos presente (te ayudo), pero en inglés necesitas I'll help you."},{"id":"13-3","title_es":"Predicciones","words":[{"en":"probably","es":"probablemente","pos":"adv","ex_en":"It will probably rain tonight.","ex_es":"Probablemente va a llover hoy en la noche."},{"en":"definitely","es":"definitivamente","pos":"adv","ex_en":"She will definitely love your gift.","ex_es":"Definitivamente le va a encantar tu regalo."},{"en":"forecast","es":"pronóstico","pos":"noun","ex_en":"The weather forecast says it will be sunny.","ex_es":"El pronóstico del clima dice que va a estar soleado."},{"en":"likely","es":"probable","pos":"adj","ex_en":"It's likely to snow in the mountains.","ex_es":"Es probable que nieve en las montañas."},{"en":"I bet","es":"apuesto a que","pos":"phrase","ex_en":"I bet they'll win the game.","ex_es":"Apuesto a que van a ganar el partido."},{"en":"go up","es":"subir","pos":"verb","ex_en":"Rent is going to go up next year.","ex_es":"La renta va a subir el próximo año."},{"en":"in the future","es":"en el futuro","pos":"phrase","ex_en":"In the future, cars will drive themselves.","ex_es":"En el futuro, los coches se van a manejar solos."},{"en":"doubt","es":"dudar","pos":"verb","ex_en":"I doubt he'll come to the meeting.","ex_es":"Dudo que venga a la junta."}],"sentences":[{"en":"I think robots will do many jobs in the future.","es":"Creo que los robots harán muchos trabajos en el futuro."},{"en":"According to the forecast, it's going to rain tomorrow.","es":"Según el pronóstico, va a llover mañana."},{"en":"Look at that sky! It's going to storm.","es":"¡Mira ese cielo! Va a haber tormenta."},{"en":"Mexico will probably win the next match.","es":"México probablemente va a ganar el próximo partido."},{"en":"I doubt prices will go down this year.","es":"Dudo que los precios bajen este año."}],"tip_es":"Para predicciones basadas en tu opinión usa will: I think it will rain. Si tienes una evidencia que ves ahora, usa going to: Look at those clouds, it's going to rain. Probably va después de will, pero antes de won't: it will probably, it probably won't."},{"id":"13-4","title_es":"Invitaciones","words":[{"en":"invite","es":"invitar","pos":"verb","ex_en":"I want to invite you to my birthday party.","ex_es":"Te quiero invitar a mi fiesta de cumpleaños."},{"en":"would you like to","es":"¿te gustaría...?","pos":"phrase","ex_en":"Would you like to go for a coffee?","ex_es":"¿Te gustaría ir por un café?"},{"en":"feel like","es":"tener ganas de","pos":"verb","ex_en":"I don't feel like cooking tonight.","ex_es":"No tengo ganas de cocinar hoy en la noche."},{"en":"I'd love to","es":"me encantaría","pos":"phrase","ex_en":"I'd love to, thanks for asking!","ex_es":"¡Me encantaría, gracias por preguntar!"},{"en":"take a rain check","es":"dejarlo para otra ocasión","pos":"phrase","ex_en":"Can I take a rain check on dinner?","ex_es":"¿Podemos dejar la cena para otra ocasión?"},{"en":"make it","es":"poder ir, lograr llegar","pos":"verb","ex_en":"Sorry, I can't make it on Friday.","ex_es":"Perdón, el viernes no voy a poder ir."},{"en":"get-together","es":"reunión","pos":"noun","ex_en":"We're having a small get-together on Saturday.","ex_es":"Vamos a hacer una pequeña reunión el sábado."},{"en":"join","es":"acompañar, unirse","pos":"verb","ex_en":"Why don't you join us for lunch?","ex_es":"¿Por qué no nos acompañas a comer?"}],"sentences":[{"en":"Would you like to come to my house for dinner?","es":"¿Te gustaría venir a cenar a mi casa?"},{"en":"I'd love to, but I have to work late.","es":"Me encantaría, pero tengo que trabajar hasta tarde."},{"en":"Do you feel like going for tacos tonight?","es":"¿Tienes ganas de ir por unos tacos hoy en la noche?"},{"en":"Thanks for the invitation, but I can't make it.","es":"Gracias por la invitación, pero no voy a poder ir."},{"en":"How about next weekend instead?","es":"¿Qué tal mejor el próximo fin de semana?"}],"tip_es":"Después de would you like usa to + verbo: Would you like to come? Pero después de feel like y how about usa el verbo con -ing: feel like going, how about meeting. Para rechazar con amabilidad di I'd love to, but... y da una razón."},{"id":"13-5","title_es":"Planes fijos y horarios","words":[{"en":"schedule","es":"agenda, horario","pos":"noun","ex_en":"My schedule is packed this week.","ex_es":"Mi agenda está llenísima esta semana."},{"en":"available","es":"disponible","pos":"adj","ex_en":"Are you available on Thursday morning?","ex_es":"¿Estás disponible el jueves en la mañana?"},{"en":"reschedule","es":"cambiar la fecha, reprogramar","pos":"verb","ex_en":"Can we reschedule the meeting for Monday?","ex_es":"¿Podemos cambiar la junta para el lunes?"},{"en":"call off","es":"cancelar","pos":"verb","ex_en":"They had to call off the concert because of the rain.","ex_es":"Tuvieron que cancelar el concierto por la lluvia."},{"en":"put off","es":"posponer, dejar para después","pos":"verb","ex_en":"Don't put off your homework until Sunday.","ex_es":"No dejes tu tarea para el domingo."},{"en":"deadline","es":"fecha límite","pos":"noun","ex_en":"The deadline for the project is next Friday.","ex_es":"La fecha límite del proyecto es el próximo viernes."},{"en":"set a date","es":"fijar una fecha","pos":"phrase","ex_en":"We still need to set a date for the trip.","ex_es":"Todavía tenemos que fijar una fecha para el viaje."},{"en":"pencil in","es":"apuntar tentativamente","pos":"verb","ex_en":"I'll pencil in our lunch for Tuesday.","ex_es":"Voy a apuntar nuestra comida para el martes, por si acaso."}],"sentences":[{"en":"I'm meeting my cousin at the airport tomorrow.","es":"Mañana voy a ver a mi primo en el aeropuerto."},{"en":"What are you doing on Saturday night?","es":"¿Qué vas a hacer el sábado en la noche?"},{"en":"We're having a barbecue on Sunday afternoon.","es":"Vamos a hacer una carne asada el domingo en la tarde."},{"en":"The train leaves at seven fifteen tomorrow morning.","es":"El tren sale mañana a las siete y cuarto de la mañana."},{"en":"Sorry, I'm not available on Monday. Can we reschedule?","es":"Perdón, no estoy disponible el lunes. ¿Lo podemos cambiar?"}],"tip_es":"Para planes fijos que ya acordaste con alguien, con hora o lugar, usa el presente continuo: I'm seeing the dentist on Friday. Para horarios oficiales como trenes, vuelos o clases, usa el presente simple: The flight leaves at six."},{"id":"13-6","title_es":"Metas y sueños","words":[{"en":"goal","es":"meta","pos":"noun","ex_en":"My goal is to run a marathon.","ex_es":"Mi meta es correr un maratón."},{"en":"achieve","es":"lograr","pos":"verb","ex_en":"You can achieve anything if you work hard.","ex_es":"Puedes lograr cualquier cosa si te esfuerzas."},{"en":"look forward to","es":"tener muchas ganas de","pos":"phrase","ex_en":"I look forward to our vacation every year.","ex_es":"Cada año espero con muchas ganas nuestras vacaciones."},{"en":"hope to","es":"esperar (con ilusión)","pos":"phrase","ex_en":"I hope to find a better job soon.","ex_es":"Espero encontrar un mejor trabajo pronto."},{"en":"about to","es":"a punto de","pos":"phrase","ex_en":"Hurry up, the movie is about to start.","ex_es":"Apúrate, la película está a punto de empezar."},{"en":"someday","es":"algún día","pos":"adv","ex_en":"Someday I'm going to open my own café.","ex_es":"Algún día voy a abrir mi propia cafetería."},{"en":"by the end of","es":"para finales de","pos":"phrase","ex_en":"I want to speak English well by the end of the year.","ex_es":"Quiero hablar bien inglés para finales del año."},{"en":"give up","es":"rendirse","pos":"verb","ex_en":"Don't give up on your dreams.","ex_es":"No te rindas con tus sueños."}],"sentences":[{"en":"My goal is to get a better job next year.","es":"Mi meta es conseguir un mejor trabajo el próximo año."},{"en":"I hope to visit Canada someday.","es":"Espero conocer Canadá algún día."},{"en":"We're looking forward to seeing you at the wedding.","es":"Tenemos muchas ganas de verte en la boda."},{"en":"By the end of the course, you'll understand movies in English.","es":"Para el final del curso, vas a entender películas en inglés."},{"en":"It won't be easy, but I'm not going to give up.","es":"No va a ser fácil, pero no me voy a rendir."}],"tip_es":"Después de look forward to va un verbo con -ing, porque aquí to es preposición: I'm looking forward to meeting you, no to meet you. Es un error muy común de los hispanohablantes, sobre todo en correos."}],"dialogue":{"title_es":"Planes para el puente","setting_es":"Un amigo te invita a un viaje para el fin de semana largo.","lines":[{"who":"A","en":"Hey! Do you have any plans for the long weekend?","es":"¡Hola! ¿Tienes planes para el puente?"},{"who":"B","en":"Not really. I think I'll just stay home and rest.","es":"No mucho. Creo que nada más me voy a quedar en casa a descansar."},{"who":"A","en":"Some friends and I are going to Valle de Bravo. Would you like to join us?","es":"Unos amigos y yo vamos a Valle de Bravo. ¿Te gustaría acompañarnos?"},{"who":"B","en":"I'd love to! When are you leaving?","es":"¡Me encantaría! ¿Cuándo se van?"},{"who":"A","en":"We're leaving on Friday at eight in the morning.","es":"Nos vamos el viernes a las ocho de la mañana."},{"who":"B","en":"Perfect. I'll ask my boss if I can take Friday off.","es":"Perfecto. Le voy a preguntar a mi jefe si me puedo tomar el viernes."},{"who":"A","en":"Great. The forecast says it's going to be sunny all weekend.","es":"Genial. El pronóstico dice que va a estar soleado todo el fin de semana."},{"who":"B","en":"Awesome. I'll bring snacks for the road.","es":"Qué padre. Yo llevo botanas para el camino."},{"who":"A","en":"Thanks! I'm really looking forward to it.","es":"¡Gracias! Tengo muchísimas ganas de ir."},{"who":"B","en":"Me too. I'll text you tonight to confirm.","es":"Yo también. Te mando mensaje hoy en la noche para confirmar."}]}},{"id":14,"title_es":"Experiencias","title_en":"Life experiences","level":"B1","goal_es":"Al terminar podrás hablar de lo que has vivido con el present perfect y usar already, yet, for y since sin confundirte.","lessons":[{"id":"14-1","title_es":"¿Alguna vez has...?","words":[{"en":"ever","es":"alguna vez","pos":"adv","ex_en":"Have you ever seen a ghost?","ex_es":"¿Alguna vez has visto un fantasma?"},{"en":"been to","es":"haber ido a, conocer (un lugar)","pos":"phrase","ex_en":"Have you ever been to Guadalajara?","ex_es":"¿Alguna vez has ido a Guadalajara?"},{"en":"go skydiving","es":"aventarse en paracaídas","pos":"phrase","ex_en":"I want to go skydiving before I turn forty.","ex_es":"Quiero aventarme en paracaídas antes de cumplir cuarenta."},{"en":"ride a horse","es":"montar a caballo","pos":"phrase","ex_en":"I learned to ride a horse at my grandpa's ranch.","ex_es":"Aprendí a montar a caballo en el rancho de mi abuelo."},{"en":"grasshopper","es":"chapulín","pos":"noun","ex_en":"Grasshoppers are a popular snack in Oaxaca.","ex_es":"Los chapulines son una botana muy popular en Oaxaca."},{"en":"celebrity","es":"celebridad, famoso","pos":"noun","ex_en":"Have you ever met a celebrity?","ex_es":"¿Alguna vez has conocido a un famoso?"},{"en":"once","es":"una vez","pos":"adv","ex_en":"I've been to New York once.","ex_es":"He ido a Nueva York una vez."},{"en":"twice","es":"dos veces","pos":"adv","ex_en":"She has visited Spain twice.","ex_es":"Ella ha visitado España dos veces."}],"sentences":[{"en":"Have you ever been to a baseball game?","es":"¿Alguna vez has ido a un partido de béisbol?"},{"en":"Yes, I have. I went to one last summer.","es":"Sí. Fui a uno el verano pasado."},{"en":"I've never eaten grasshoppers, but I want to try them.","es":"Nunca he comido chapulines, pero quiero probarlos."},{"en":"My sister has met two famous singers.","es":"Mi hermana ha conocido a dos cantantes famosos."},{"en":"How many times have you flown on a plane?","es":"¿Cuántas veces te has subido a un avión?"}],"tip_es":"Para hablar de experiencias de tu vida sin decir cuándo pasaron, usa have o has + participio: I have seen, she has gone. Responde corto con Yes, I have o No, I haven't, en lugar de solo Yes o No."},{"id":"14-2","title_es":"Already, yet y just","words":[{"en":"already","es":"ya","pos":"adv","ex_en":"I've already finished my homework.","ex_es":"Ya terminé mi tarea."},{"en":"yet","es":"todavía, ya (en preguntas)","pos":"adv","ex_en":"Have you had lunch yet?","ex_es":"¿Ya comiste?"},{"en":"just","es":"acabar de","pos":"adv","ex_en":"He's just arrived home.","ex_es":"Él acaba de llegar a la casa."},{"en":"still","es":"todavía, aún","pos":"adv","ex_en":"I still haven't called my mom.","ex_es":"Todavía no le he llamado a mi mamá."},{"en":"wrap up","es":"terminar, cerrar","pos":"verb","ex_en":"Let's wrap up the meeting in five minutes.","ex_es":"Cerremos la junta en cinco minutos."},{"en":"hand in","es":"entregar","pos":"verb","ex_en":"Don't forget to hand in your essay on Monday.","ex_es":"No olvides entregar tu ensayo el lunes."},{"en":"sort out","es":"resolver, arreglar","pos":"verb","ex_en":"I need to sort out my papers before the trip.","ex_es":"Necesito arreglar mis papeles antes del viaje."},{"en":"to-do list","es":"lista de pendientes","pos":"noun","ex_en":"My to-do list is very long today.","ex_es":"Mi lista de pendientes está muy larga hoy."}],"sentences":[{"en":"Have you finished the report yet?","es":"¿Ya terminaste el reporte?"},{"en":"No, I haven't finished it yet.","es":"No, todavía no lo he terminado."},{"en":"I've already sent the email to the client.","es":"Ya le mandé el correo al cliente."},{"en":"The bus has just left. We missed it!","es":"El camión acaba de irse. ¡Lo perdimos!"},{"en":"She still hasn't sorted out her visa.","es":"Ella todavía no ha resuelto lo de su visa."}],"tip_es":"Already va normalmente entre have y el participio: I've already eaten. Yet va al final en preguntas y negativas: Have you eaten yet? I haven't eaten yet. Just significa acabar de: I've just arrived es Acabo de llegar."},{"id":"14-3","title_es":"For y since","words":[{"en":"for","es":"durante, desde hace","pos":"prep","ex_en":"I've lived here for five years.","ex_es":"Llevo cinco años viviendo aquí."},{"en":"since","es":"desde","pos":"prep","ex_en":"She has worked here since 2019.","ex_es":"Ella trabaja aquí desde 2019."},{"en":"how long","es":"cuánto tiempo","pos":"phrase","ex_en":"How long have you known Pedro?","ex_es":"¿Desde hace cuánto conoces a Pedro?"},{"en":"decade","es":"década","pos":"noun","ex_en":"They've been friends for over a decade.","ex_es":"Han sido amigos por más de una década."},{"en":"childhood","es":"infancia","pos":"noun","ex_en":"We've known each other since childhood.","ex_es":"Nos conocemos desde la infancia."},{"en":"ages","es":"mucho tiempo, siglos","pos":"noun","ex_en":"I haven't seen you for ages!","ex_es":"¡Hace siglos que no te veo!"},{"en":"get to know","es":"conocer (a alguien poco a poco)","pos":"phrase","ex_en":"I'd like to get to know your family better.","ex_es":"Me gustaría conocer mejor a tu familia."},{"en":"lately","es":"últimamente","pos":"adv","ex_en":"Have you been busy lately?","ex_es":"¿Has estado ocupado últimamente?"}],"sentences":[{"en":"How long have you lived in Monterrey?","es":"¿Cuánto tiempo llevas viviendo en Monterrey?"},{"en":"I've lived here for almost ten years.","es":"Llevo casi diez años viviendo aquí."},{"en":"We've been married since 2015.","es":"Estamos casados desde 2015."},{"en":"I haven't seen my cousins since Christmas.","es":"No he visto a mis primos desde Navidad."},{"en":"She's been learning English for six months.","es":"Ella lleva seis meses aprendiendo inglés."}],"tip_es":"Usa for con periodos de tiempo (for two years, for a week) y since con el momento en que empezó (since Monday, since 2010). Error común: I live here since 2010. Lo correcto es I have lived here since 2010."},{"id":"14-4","title_es":"¿Present perfect o pasado simple?","words":[{"en":"recently","es":"recientemente","pos":"adv","ex_en":"Have you seen any good movies recently?","ex_es":"¿Has visto alguna película buena recientemente?"},{"en":"so far","es":"hasta ahora","pos":"phrase","ex_en":"So far, I've read three books this month.","ex_es":"Hasta ahora, he leído tres libros este mes."},{"en":"in my life","es":"en mi vida","pos":"phrase","ex_en":"I've never been so tired in my life.","ex_es":"Nunca he estado tan cansado en mi vida."},{"en":"once in a lifetime","es":"única en la vida","pos":"phrase","ex_en":"Seeing the whales was a once in a lifetime experience.","ex_es":"Ver las ballenas fue una experiencia única en la vida."},{"en":"unforgettable","es":"inolvidable","pos":"adj","ex_en":"Our trip to Chiapas was unforgettable.","ex_es":"Nuestro viaje a Chiapas fue inolvidable."},{"en":"go through","es":"pasar por, vivir","pos":"verb","ex_en":"Many students go through stress during exams.","ex_es":"Muchos estudiantes pasan por estrés durante los exámenes."},{"en":"experience","es":"experiencia","pos":"noun","ex_en":"Working in a hotel was a great experience.","ex_es":"Trabajar en un hotel fue una gran experiencia."},{"en":"the other day","es":"el otro día","pos":"phrase","ex_en":"I saw your brother the other day.","ex_es":"Vi a tu hermano el otro día."}],"sentences":[{"en":"I've been to Puerto Vallarta, but I went there years ago.","es":"He ido a Puerto Vallarta, pero fue hace años."},{"en":"Have you seen the new superhero movie? Yes, I saw it Sunday.","es":"¿Ya viste la nueva película de superhéroes? Sí, la vi el domingo."},{"en":"So far, this year has been really good.","es":"Hasta ahora, este año ha sido muy bueno."},{"en":"I've never had such an unforgettable experience in my life.","es":"Nunca he tenido una experiencia tan inolvidable en mi vida."},{"en":"When did you start working here?","es":"¿Cuándo empezaste a trabajar aquí?"}],"tip_es":"Si dices cuándo pasó (yesterday, in 2020, last week, the other day), usa past simple: I saw it yesterday. Si no importa cuándo o el periodo sigue abierto (this year, so far, ever), usa present perfect. Nunca digas I have seen it yesterday."},{"id":"14-5","title_es":"Logros y cambios","words":[{"en":"accomplish","es":"lograr, cumplir","pos":"verb","ex_en":"It feels great to accomplish a big goal.","ex_es":"Se siente increíble cumplir una meta grande."},{"en":"improve","es":"mejorar","pos":"verb","ex_en":"I want to improve my pronunciation.","ex_es":"Quiero mejorar mi pronunciación."},{"en":"graduate","es":"graduarse","pos":"verb","ex_en":"She has just graduated from college.","ex_es":"Ella acaba de graduarse de la universidad."},{"en":"get promoted","es":"recibir un ascenso","pos":"phrase","ex_en":"I hope to get promoted next year.","ex_es":"Espero recibir un ascenso el próximo año."},{"en":"quit","es":"dejar (un hábito o trabajo)","pos":"verb","ex_en":"My dad has quit smoking.","ex_es":"Mi papá ya dejó de fumar."},{"en":"take up","es":"empezar (un pasatiempo)","pos":"verb","ex_en":"I want to take up painting this year.","ex_es":"Quiero empezar a pintar este año."},{"en":"grow up","es":"crecer","pos":"verb","ex_en":"Where did you grow up?","ex_es":"¿Dónde creciste?"},{"en":"proud","es":"orgulloso","pos":"adj","ex_en":"I'm so proud of you!","ex_es":"¡Estoy muy orgulloso de ti!"}],"sentences":[{"en":"My English has improved a lot since I started this course.","es":"Mi inglés ha mejorado mucho desde que empecé este curso."},{"en":"Have you taken up any new hobbies lately?","es":"¿Has empezado algún pasatiempo nuevo últimamente?"},{"en":"He has just graduated, and his parents are very proud.","es":"Acaba de graduarse y sus papás están muy orgullosos."},{"en":"I've quit drinking soda, and I feel much better.","es":"Dejé de tomar refresco y me siento mucho mejor."},{"en":"How has your city changed since you were a kid?","es":"¿Cómo ha cambiado tu ciudad desde que eras niño?"}],"tip_es":"El present perfect es ideal para cambios con un resultado visible hoy: My English has improved. Aprende los participios irregulares más comunes: grow, grew, grown. take, took, taken. quit, quit, quit."},{"id":"14-6","title_es":"Viajes y aventuras","words":[{"en":"abroad","es":"en el extranjero","pos":"adv","ex_en":"Have you ever lived abroad?","ex_es":"¿Alguna vez has vivido en el extranjero?"},{"en":"sightseeing","es":"recorrido turístico","pos":"noun","ex_en":"We did a lot of sightseeing in Rome.","ex_es":"Hicimos muchos recorridos turísticos en Roma."},{"en":"bucket list","es":"lista de cosas por hacer en la vida","pos":"noun","ex_en":"Visiting Japan is on my bucket list.","ex_es":"Conocer Japón está en mi lista de cosas por hacer en la vida."},{"en":"breathtaking","es":"impresionante","pos":"adj","ex_en":"The view from the pyramid was breathtaking.","ex_es":"La vista desde la pirámide fue impresionante."},{"en":"get lost","es":"perderse","pos":"phrase","ex_en":"It's easy to get lost in Mexico City.","ex_es":"Es fácil perderse en la Ciudad de México."},{"en":"backpack","es":"viajar de mochilazo","pos":"verb","ex_en":"They want to backpack through South America.","ex_es":"Quieren viajar de mochilazo por Sudamérica."},{"en":"off the beaten path","es":"poco turístico","pos":"phrase","ex_en":"We like towns that are off the beaten path.","ex_es":"Nos gustan los pueblos poco turísticos."},{"en":"culture shock","es":"choque cultural","pos":"noun","ex_en":"I had a big culture shock when I moved to Canada.","ex_es":"Tuve un gran choque cultural cuando me mudé a Canadá."}],"sentences":[{"en":"Have you ever traveled abroad by yourself?","es":"¿Alguna vez has viajado solo al extranjero?"},{"en":"My parents have gone to Spain. They come back next week.","es":"Mis papás se fueron a España. Regresan la próxima semana."},{"en":"I've been to Spain twice, and I loved it.","es":"He ido a España dos veces y me encantó."},{"en":"We've gotten lost three times today!","es":"¡Nos hemos perdido tres veces hoy!"},{"en":"Seeing the northern lights is at the top of my bucket list.","es":"Ver la aurora boreal es lo primero en mi lista de sueños."}],"tip_es":"Has been to significa que la persona fue y ya regresó. Has gone to significa que se fue y sigue allá. She has been to Paris (ya volvió). She has gone to Paris (todavía está en París)."}],"dialogue":{"title_es":"Reencuentro en el café","setting_es":"Te encuentras en un café a un amigo que no veías desde hace mucho.","lines":[{"who":"A","en":"Hey! I haven't seen you for ages!","es":"¡Hola! ¡Hace siglos que no te veo!"},{"who":"B","en":"I know! How have you been?","es":"¡Ya sé! ¿Cómo has estado?"},{"who":"A","en":"Great, thanks. I've just come back from Peru.","es":"Muy bien, gracias. Acabo de regresar de Perú."},{"who":"B","en":"Wow! Have you been to Machu Picchu?","es":"¡Órale! ¿Fuiste a Machu Picchu?"},{"who":"A","en":"Yes, I have. It was breathtaking. Have you ever been there?","es":"Sí. Fue impresionante. ¿Tú has ido alguna vez?"},{"who":"B","en":"No, I haven't, but it's on my bucket list.","es":"No, pero está en mi lista de sueños."},{"who":"A","en":"You should go. So, what's new with you?","es":"Deberías ir. ¿Y qué hay de nuevo contigo?"},{"who":"B","en":"I've changed jobs. I've worked at a bank since March.","es":"Cambié de trabajo. Trabajo en un banco desde marzo."},{"who":"A","en":"That's great! Do you like it?","es":"¡Qué bien! ¿Te gusta?"},{"who":"B","en":"Yes, so far it's been a great experience.","es":"Sí, hasta ahora ha sido una gran experiencia."}]}},{"id":15,"title_es":"Opiniones y sentimientos","title_en":"Opinions and feelings","level":"B1","goal_es":"Al terminar podrás expresar emociones, dar tu opinión, estar de acuerdo o en desacuerdo y comparar cosas.","lessons":[{"id":"15-1","title_es":"¿Cómo te sientes?","words":[{"en":"excited","es":"emocionado","pos":"adj","ex_en":"I'm so excited about the concert!","ex_es":"¡Estoy muy emocionado por el concierto!"},{"en":"disappointed","es":"decepcionado","pos":"adj","ex_en":"She was disappointed with her grade.","ex_es":"Ella estaba decepcionada con su calificación."},{"en":"worried","es":"preocupado","pos":"adj","ex_en":"My mom is worried because I came home late.","ex_es":"Mi mamá está preocupada porque llegué tarde a la casa."},{"en":"embarrassed","es":"apenado, avergonzado","pos":"adj","ex_en":"I was so embarrassed when I fell in the street.","ex_es":"Me dio muchísima pena cuando me caí en la calle."},{"en":"frustrated","es":"frustrado","pos":"adj","ex_en":"He gets frustrated when the internet is slow.","ex_es":"Se frustra cuando el internet está lento."},{"en":"relieved","es":"aliviado","pos":"adj","ex_en":"I felt relieved when the exam was over.","ex_es":"Me sentí aliviado cuando terminó el examen."},{"en":"annoyed","es":"molesto, irritado","pos":"adj","ex_en":"I'm annoyed because my neighbor's music is too loud.","ex_es":"Estoy molesto porque la música de mi vecino está muy fuerte."},{"en":"overwhelmed","es":"abrumado","pos":"adj","ex_en":"I feel overwhelmed with so much work.","ex_es":"Me siento abrumado con tanto trabajo."}],"sentences":[{"en":"The movie was boring, so I was bored.","es":"La película estaba aburrida, así que me aburrí."},{"en":"I'm really excited about my new job.","es":"Estoy muy emocionado por mi nuevo trabajo."},{"en":"Why do you look so worried?","es":"¿Por qué te ves tan preocupado?"},{"en":"It was an exhausting day, and now I'm exhausted.","es":"Fue un día agotador y ahora estoy agotado."},{"en":"She felt embarrassed when she forgot his name.","es":"Le dio pena cuando olvidó el nombre de él."}],"tip_es":"Los adjetivos con -ed describen cómo te sientes (I'm bored, estoy aburrido) y los de -ing describen lo que causa el sentimiento (The class is boring). Cuidado: embarrassed significa apenado, no embarazada, que en inglés es pregnant."},{"id":"15-2","title_es":"Dar tu opinión","words":[{"en":"in my opinion","es":"en mi opinión","pos":"phrase","ex_en":"In my opinion, the book is better than the movie.","ex_es":"En mi opinión, el libro es mejor que la película."},{"en":"personally","es":"personalmente","pos":"adv","ex_en":"Personally, I don't like spicy food.","ex_es":"Personalmente, no me gusta la comida picante."},{"en":"as far as I know","es":"que yo sepa","pos":"phrase","ex_en":"As far as I know, the store opens at nine.","ex_es":"Que yo sepa, la tienda abre a las nueve."},{"en":"it seems to me","es":"me parece que","pos":"phrase","ex_en":"It seems to me that he's very tired.","ex_es":"Me parece que él está muy cansado."},{"en":"point of view","es":"punto de vista","pos":"noun","ex_en":"From my point of view, it's a good idea.","ex_es":"Desde mi punto de vista, es una buena idea."},{"en":"believe","es":"creer","pos":"verb","ex_en":"I believe everyone deserves a second chance.","ex_es":"Creo que todos merecen una segunda oportunidad."},{"en":"honestly","es":"honestamente, la verdad","pos":"adv","ex_en":"Honestly, I didn't like the ending.","ex_es":"La verdad, no me gustó el final."},{"en":"make sense","es":"tener sentido","pos":"phrase","ex_en":"That doesn't make sense.","ex_es":"Eso no tiene sentido."}],"sentences":[{"en":"In my opinion, public transportation in this city needs to improve.","es":"En mi opinión, el transporte público de esta ciudad necesita mejorar."},{"en":"Personally, I prefer living in a small town.","es":"Personalmente, prefiero vivir en un pueblo."},{"en":"What do you think about working from home?","es":"¿Qué opinas de trabajar desde casa?"},{"en":"It seems to me that people are always in a hurry.","es":"Me parece que la gente siempre anda con prisa."},{"en":"Honestly, his plan doesn't make sense to me.","es":"Honestamente, su plan no tiene sentido para mí."}],"tip_es":"Para pedir una opinión se dice What do you think about...?, no How do you think...? Para dar la tuya usa I think..., In my opinion... o Personally... y evita traducir literal según yo como according to me."},{"id":"15-3","title_es":"De acuerdo y en desacuerdo","words":[{"en":"agree","es":"estar de acuerdo","pos":"verb","ex_en":"I agree with you about the new schedule.","ex_es":"Estoy de acuerdo contigo sobre el nuevo horario."},{"en":"disagree","es":"no estar de acuerdo","pos":"verb","ex_en":"My brother and I often disagree about politics.","ex_es":"Mi hermano y yo seguido no estamos de acuerdo sobre política."},{"en":"exactly","es":"exacto","pos":"adv","ex_en":"Exactly! That's what I was trying to say.","ex_es":"¡Exacto! Eso es lo que trataba de decir."},{"en":"I see your point","es":"entiendo tu punto","pos":"phrase","ex_en":"I see your point, but I still think it's expensive.","ex_es":"Entiendo tu punto, pero sigo pensando que es caro."},{"en":"on the other hand","es":"por otro lado","pos":"phrase","ex_en":"The city is noisy. On the other hand, there's a lot to do.","ex_es":"La ciudad es ruidosa. Por otro lado, hay mucho que hacer."},{"en":"fair enough","es":"es justo, está bien","pos":"phrase","ex_en":"You want to leave early? Fair enough.","ex_es":"¿Te quieres ir temprano? Está bien, es justo."},{"en":"not necessarily","es":"no necesariamente","pos":"phrase","ex_en":"Expensive things are not necessarily better.","ex_es":"Las cosas caras no necesariamente son mejores."},{"en":"argue","es":"discutir, pelear","pos":"verb","ex_en":"My parents argue about money sometimes.","ex_es":"Mis papás a veces discuten por dinero."}],"sentences":[{"en":"I totally agree with you.","es":"Estoy totalmente de acuerdo contigo."},{"en":"I'm sorry, but I don't agree with that idea.","es":"Perdón, pero no estoy de acuerdo con esa idea."},{"en":"You're right, but on the other hand, it's very far.","es":"Tienes razón, pero por otro lado, queda muy lejos."},{"en":"I see your point, but I think we need more time.","es":"Entiendo tu punto, pero creo que necesitamos más tiempo."},{"en":"We don't have to agree on everything.","es":"No tenemos que estar de acuerdo en todo."}],"tip_es":"Agree es un verbo, así que se dice I agree, nunca I am agree. En negativo di I don't agree o I disagree. Ojo: argue significa discutir o pelear con palabras, no argumentar de forma tranquila."},{"id":"15-4","title_es":"Comparar cosas","words":[{"en":"than","es":"que (en comparaciones)","pos":"conj","ex_en":"My new apartment is bigger than my old one.","ex_es":"Mi departamento nuevo es más grande que el anterior."},{"en":"less","es":"menos","pos":"adv","ex_en":"This phone is less expensive than that one.","ex_es":"Este celular es menos caro que ese."},{"en":"as good as","es":"tan bueno como","pos":"phrase","ex_en":"The sequel isn't as good as the first movie.","ex_es":"La secuela no es tan buena como la primera película."},{"en":"worse","es":"peor","pos":"adj","ex_en":"The traffic is worse on Fridays.","ex_es":"El tráfico está peor los viernes."},{"en":"crowded","es":"lleno de gente","pos":"adj","ex_en":"The subway is very crowded at rush hour.","ex_es":"El metro está muy lleno en hora pico."},{"en":"convenient","es":"práctico, conveniente","pos":"adj","ex_en":"Living near work is very convenient.","ex_es":"Vivir cerca del trabajo es muy práctico."},{"en":"affordable","es":"accesible (de precio)","pos":"adj","ex_en":"It's hard to find affordable housing downtown.","ex_es":"Es difícil encontrar vivienda accesible en el centro."},{"en":"similar","es":"parecido","pos":"adj","ex_en":"Your bag is similar to mine.","ex_es":"Tu bolsa es parecida a la mía."}],"sentences":[{"en":"Puebla is smaller than Mexico City, but it's very pretty.","es":"Puebla es más chica que la Ciudad de México, pero es muy bonita."},{"en":"Learning English is easier than I thought.","es":"Aprender inglés es más fácil de lo que pensaba."},{"en":"This restaurant is more affordable than the one downtown.","es":"Este restaurante es más accesible que el del centro."},{"en":"My cold is getting worse, not better.","es":"Mi gripa está cada vez peor, no mejor."},{"en":"The bus is cheaper, but the subway is more convenient.","es":"El camión es más barato, pero el metro es más práctico."}],"tip_es":"Los adjetivos cortos agregan -er (cheaper, bigger) y los largos usan more (more convenient). Irregulares: good, better y bad, worse. Error común: more better o more cheap. Nunca combines more con -er."},{"id":"15-5","title_es":"Lo mejor y lo peor","words":[{"en":"the best","es":"el mejor","pos":"phrase","ex_en":"This is the best taco place in town.","ex_es":"Esta es la mejor taquería de la ciudad."},{"en":"the worst","es":"el peor","pos":"phrase","ex_en":"Monday is the worst day of the week.","ex_es":"El lunes es el peor día de la semana."},{"en":"the most","es":"el más","pos":"phrase","ex_en":"What's the most beautiful place you've visited?","ex_es":"¿Cuál es el lugar más bonito que has visitado?"},{"en":"the least","es":"el menos","pos":"phrase","ex_en":"This is the least expensive option on the menu.","ex_es":"Esta es la opción menos cara del menú."},{"en":"by far","es":"por mucho","pos":"phrase","ex_en":"This is by far the hottest summer I remember.","ex_es":"Este es por mucho el verano más caluroso que recuerdo."},{"en":"one of the","es":"uno de los","pos":"phrase","ex_en":"Tokyo is one of the biggest cities in the world.","ex_es":"Tokio es una de las ciudades más grandes del mundo."},{"en":"talented","es":"talentoso","pos":"adj","ex_en":"My cousin is a very talented guitar player.","ex_es":"Mi primo es un guitarrista muy talentoso."},{"en":"impressive","es":"impresionante","pos":"adj","ex_en":"The view from the top was really impressive.","ex_es":"La vista desde arriba fue realmente impresionante."}],"sentences":[{"en":"What's the best movie you've ever seen?","es":"¿Cuál es la mejor película que has visto?"},{"en":"January is the coldest month of the year here.","es":"Enero es el mes más frío del año aquí."},{"en":"That was the worst meal I've ever had.","es":"Fue la peor comida que he probado en mi vida."},{"en":"She's the most talented singer in the band.","es":"Ella es la cantante más talentosa del grupo."},{"en":"Frida Kahlo is one of the most famous Mexican artists.","es":"Frida Kahlo es una de las artistas mexicanas más famosas."}],"tip_es":"El superlativo se forma con the + adjetivo con -est (the tallest) o the most + adjetivo largo (the most interesting). Para lugares o grupos usa in, no of: the best in the world. Se combina mucho con present perfect: the best I've ever seen."},{"id":"15-6","title_es":"Reaccionar y mostrar empatía","words":[{"en":"that's a shame","es":"qué lástima","pos":"phrase","ex_en":"You missed the concert? That's a shame.","ex_es":"¿Te perdiste el concierto? Qué lástima."},{"en":"I'm sorry to hear that","es":"lamento escuchar eso","pos":"phrase","ex_en":"Your dog is sick? I'm sorry to hear that.","ex_es":"¿Tu perro está enfermo? Lamento escuchar eso."},{"en":"no way","es":"¡no manches!, ¡no puede ser!","pos":"interj","ex_en":"No way! You won the lottery?","ex_es":"¡No manches! ¿Te ganaste la lotería?"},{"en":"cheer up","es":"animarse","pos":"verb","ex_en":"Cheer up! Tomorrow will be a better day.","ex_es":"¡Ánimo! Mañana va a ser un mejor día."},{"en":"hang in there","es":"aguanta, échale ganas","pos":"phrase","ex_en":"Hang in there. The semester is almost over.","ex_es":"Échale ganas. Ya casi se acaba el semestre."},{"en":"good for you","es":"qué bien por ti","pos":"phrase","ex_en":"You got the job? Good for you!","ex_es":"¿Te quedaste con el trabajo? ¡Qué bien por ti!"},{"en":"I know how you feel","es":"sé cómo te sientes","pos":"phrase","ex_en":"I know how you feel. I was nervous too.","ex_es":"Sé cómo te sientes. Yo también estaba nervioso."},{"en":"upset","es":"molesto, triste","pos":"adj","ex_en":"She was upset because nobody called her.","ex_es":"Ella estaba triste porque nadie le llamó."}],"sentences":[{"en":"I'm sorry to hear about your grandma.","es":"Lamento mucho lo de tu abuelita."},{"en":"That's great news! Congratulations!","es":"¡Qué buena noticia! ¡Felicidades!"},{"en":"Don't be so hard on yourself.","es":"No seas tan duro contigo mismo."},{"en":"What's wrong? You seem a little upset.","es":"¿Qué pasa? Te ves un poco triste."},{"en":"If you need to talk, I'm here for you.","es":"Si necesitas hablar, aquí estoy para ti."}],"tip_es":"En inglés se reacciona mucho con frases cortas como That's a shame, Good for you o No way! Ojo: I'm sorry no solo sirve para pedir perdón, también se usa para dar el pésame o mostrar compasión."}],"dialogue":{"title_es":"¿Ciudad grande o pequeña?","setting_es":"Platicas con un amigo de Querétaro sobre vivir en la capital.","lines":[{"who":"A","en":"So, how do you like living in Mexico City?","es":"Y qué tal, ¿te gusta vivir en la Ciudad de México?"},{"who":"B","en":"Honestly, I love it. There's always something to do.","es":"La verdad, me encanta. Siempre hay algo que hacer."},{"who":"A","en":"Really? I think it's too crowded and noisy.","es":"¿En serio? Yo creo que hay demasiada gente y mucho ruido."},{"who":"B","en":"I see your point, but the food is the best in the country.","es":"Entiendo tu punto, pero la comida es la mejor del país."},{"who":"A","en":"Fair enough. But the traffic is much worse than in Querétaro.","es":"Es justo. Pero el tráfico está mucho peor que en Querétaro."},{"who":"B","en":"That's true. On the other hand, the subway is very convenient.","es":"Es cierto. Por otro lado, el metro es muy práctico."},{"who":"A","en":"Maybe. Personally, I prefer a quieter life.","es":"Puede ser. Personalmente, prefiero una vida más tranquila."},{"who":"B","en":"I understand. Smaller cities are more relaxing.","es":"Te entiendo. Las ciudades más chicas son más relajantes."},{"who":"A","en":"Exactly! You should visit me in Querétaro sometime.","es":"¡Exacto! Deberías visitarme en Querétaro algún día."},{"who":"B","en":"I'd love to! I'm sure I'll be impressed.","es":"¡Me encantaría! Seguro me va a impresionar."}]}},{"id":16,"title_es":"Inglés profesional","title_en":"English for work","level":"B2","goal_es":"Al terminar podrás presentarte en una entrevista, escribir correos formales, participar en juntas y llamadas, y hacer peticiones con cortesía.","lessons":[{"id":"16-1","title_es":"La entrevista de trabajo","words":[{"en":"résumé","es":"currículum","pos":"noun","ex_en":"Please send your résumé before Friday.","ex_es":"Por favor, envíe su currículum antes del viernes."},{"en":"apply for","es":"solicitar, postularse a","pos":"verb","ex_en":"I'd like to apply for the sales job.","ex_es":"Me gustaría postularme al trabajo de ventas."},{"en":"position","es":"puesto","pos":"noun","ex_en":"The position requires three years of experience.","ex_es":"El puesto requiere tres años de experiencia."},{"en":"background","es":"formación, trayectoria","pos":"noun","ex_en":"My background is in accounting and finance.","ex_es":"Mi formación es en contabilidad y finanzas."},{"en":"strength","es":"fortaleza","pos":"noun","ex_en":"My biggest strength is solving problems quickly.","ex_es":"Mi mayor fortaleza es resolver problemas rápido."},{"en":"weakness","es":"debilidad","pos":"noun","ex_en":"One of my weaknesses is that I'm a perfectionist.","ex_es":"Una de mis debilidades es que soy perfeccionista."},{"en":"team player","es":"persona que trabaja bien en equipo","pos":"noun","ex_en":"I'm a team player, and I enjoy working with others.","ex_es":"Trabajo bien en equipo y me gusta colaborar con otros."},{"en":"hire","es":"contratar","pos":"verb","ex_en":"The company plans to hire ten new engineers.","ex_es":"La empresa planea contratar a diez ingenieros nuevos."}],"sentences":[{"en":"Tell me a little about yourself.","es":"Cuénteme un poco sobre usted."},{"en":"Why are you interested in this position?","es":"¿Por qué le interesa este puesto?"},{"en":"I have five years of experience in customer service.","es":"Tengo cinco años de experiencia en atención al cliente."},{"en":"Where do you see yourself in five years?","es":"¿Dónde se ve en cinco años?"},{"en":"What are your salary expectations for this role?","es":"¿Cuáles son sus expectativas salariales para este puesto?"}],"tip_es":"En una entrevista habla de tu experiencia con present perfect (I have worked in sales for five years) y de trabajos terminados con past simple (I worked at a bank in 2019). Error común: experience in sell. Lo correcto es experience in selling, con -ing después de in."},{"id":"16-2","title_es":"Correos formales","words":[{"en":"dear","es":"estimado","pos":"adj","ex_en":"Dear Ms. Johnson, thank you for your message.","ex_es":"Estimada Sra. Johnson, gracias por su mensaje."},{"en":"regarding","es":"respecto a, en relación con","pos":"prep","ex_en":"I'm writing regarding the invoice from last month.","ex_es":"Le escribo en relación con la factura del mes pasado."},{"en":"attach","es":"adjuntar","pos":"verb","ex_en":"I'll attach the contract to this email.","ex_es":"Voy a adjuntar el contrato a este correo."},{"en":"follow up","es":"dar seguimiento","pos":"verb","ex_en":"I'm writing to follow up on our meeting.","ex_es":"Le escribo para dar seguimiento a nuestra junta."},{"en":"best regards","es":"saludos cordiales","pos":"phrase","ex_en":"Best regards, Laura.","ex_es":"Saludos cordiales, Laura."},{"en":"as soon as possible","es":"lo antes posible","pos":"phrase","ex_en":"Please reply as soon as possible.","ex_es":"Por favor, responda lo antes posible."},{"en":"reach out","es":"contactar, escribir","pos":"verb","ex_en":"Feel free to reach out if you have any questions.","ex_es":"No dude en contactarme si tiene alguna pregunta."},{"en":"inquiry","es":"consulta","pos":"noun","ex_en":"Thank you for your inquiry about our services.","ex_es":"Gracias por su consulta sobre nuestros servicios."}],"sentences":[{"en":"I'm writing to ask about the job opening.","es":"Le escribo para preguntar sobre la vacante."},{"en":"Please find attached the documents you requested.","es":"Adjunto encontrará los documentos que solicitó."},{"en":"Thank you for getting back to me so quickly.","es":"Gracias por responderme tan rápido."},{"en":"Could you please confirm the date of the meeting?","es":"¿Podría confirmar la fecha de la junta, por favor?"},{"en":"I look forward to hearing from you.","es":"Quedo atento a su respuesta."}],"tip_es":"En correos formales empieza con Dear + título y apellido (Dear Mr. Smith) y cierra con Best regards o Sincerely. Quedo atento a su respuesta se dice I look forward to hearing from you, con -ing después de to."},{"id":"16-3","title_es":"Juntas de trabajo","words":[{"en":"agenda","es":"orden del día","pos":"noun","ex_en":"Let's look at the agenda for today's meeting.","ex_es":"Veamos el orden del día de la junta de hoy."},{"en":"minutes","es":"minuta","pos":"noun","ex_en":"Who is taking the minutes today?","ex_es":"¿Quién va a hacer la minuta hoy?"},{"en":"item","es":"punto (de una lista)","pos":"noun","ex_en":"The first item on the list is the budget.","ex_es":"El primer punto de la lista es el presupuesto."},{"en":"bring up","es":"mencionar, sacar un tema","pos":"verb","ex_en":"I'd like to bring up a problem with the delivery dates.","ex_es":"Me gustaría mencionar un problema con las fechas de entrega."},{"en":"move on","es":"pasar a otro tema","pos":"verb","ex_en":"If there are no more questions, let's move on.","ex_es":"Si no hay más preguntas, pasemos al siguiente tema."},{"en":"go over","es":"revisar, repasar","pos":"verb","ex_en":"Let's go over the numbers one more time.","ex_es":"Revisemos los números una vez más."},{"en":"point out","es":"señalar","pos":"verb","ex_en":"I'd like to point out that sales went up.","ex_es":"Me gustaría señalar que las ventas subieron."},{"en":"brainstorm","es":"hacer lluvia de ideas","pos":"verb","ex_en":"Let's brainstorm some ideas for the new campaign.","ex_es":"Hagamos una lluvia de ideas para la nueva campaña."}],"sentences":[{"en":"Let's get started. Thank you all for coming.","es":"Empecemos. Gracias a todos por venir."},{"en":"Sorry to interrupt, but could I add something?","es":"Perdón por interrumpir, pero ¿puedo agregar algo?"},{"en":"Could you clarify what you mean by that?","es":"¿Podrías aclarar a qué te refieres con eso?"},{"en":"Let's go over the main points before we finish.","es":"Repasemos los puntos principales antes de terminar."},{"en":"I'll send everyone the minutes after the meeting.","es":"Les mando la minuta a todos después de la junta."}],"tip_es":"Agenda es un falso amigo: en una junta, the agenda es el orden del día, y tu agenda personal se dice planner o calendar. Para pedir la palabra con cortesía usa Sorry to interrupt, but... o Could I add something?"},{"id":"16-4","title_es":"Llamadas y videollamadas","words":[{"en":"hold on","es":"espere un momento","pos":"verb","ex_en":"Hold on, please. I'll check.","ex_es":"Espere un momento, por favor. Lo reviso."},{"en":"put through","es":"comunicar, transferir (una llamada)","pos":"verb","ex_en":"Please hold while I put through your call.","ex_es":"Espere en la línea mientras le transfiero su llamada."},{"en":"take a message","es":"tomar un recado","pos":"phrase","ex_en":"She's not here. Can I take a message?","ex_es":"No se encuentra. ¿Le puedo tomar un recado?"},{"en":"call back","es":"devolver la llamada","pos":"verb","ex_en":"I'll call back in ten minutes.","ex_es":"Le regreso la llamada en diez minutos."},{"en":"speak up","es":"hablar más fuerte","pos":"verb","ex_en":"Could you speak up a little, please?","ex_es":"¿Podría hablar un poco más fuerte, por favor?"},{"en":"break up","es":"cortarse (la señal)","pos":"verb","ex_en":"The signal tends to break up in the elevator.","ex_es":"La señal se suele cortar en el elevador."},{"en":"mute","es":"silenciar","pos":"verb","ex_en":"Please mute your microphone when you're not speaking.","ex_es":"Por favor, silencien su micrófono cuando no estén hablando."},{"en":"extension","es":"extensión","pos":"noun","ex_en":"My extension is two one four.","ex_es":"Mi extensión es dos uno cuatro."}],"sentences":[{"en":"Good morning, this is Laura from Grupo Delta.","es":"Buenos días, habla Laura de Grupo Delta."},{"en":"May I speak with Mr. Ramírez, please?","es":"¿Puedo hablar con el señor Ramírez, por favor?"},{"en":"I'm afraid he's in a meeting right now.","es":"Me temo que está en una junta en este momento."},{"en":"Sorry, you're on mute. We can't hear you.","es":"Perdón, tienes el micrófono apagado. No te escuchamos."},{"en":"Could you repeat that? The connection is really bad.","es":"¿Podría repetir eso? Se escucha muy mal."}],"tip_es":"Al contestar el teléfono en inglés se dice This is Laura o Laura speaking, no I am Laura. Para pedir hablar con alguien usa May I speak with...? o Could you put me through to...?"},{"id":"16-5","title_es":"Peticiones con cortesía","words":[{"en":"would you mind","es":"¿le molestaría...?","pos":"phrase","ex_en":"Would you mind closing the door?","ex_es":"¿Le molestaría cerrar la puerta?"},{"en":"I was wondering if","es":"me preguntaba si","pos":"phrase","ex_en":"I was wondering if you could help me with this report.","ex_es":"Me preguntaba si me podría ayudar con este reporte."},{"en":"appreciate","es":"agradecer","pos":"verb","ex_en":"I'd appreciate it if you could reply today.","ex_es":"Le agradecería si pudiera responder hoy."},{"en":"approve","es":"aprobar","pos":"verb","ex_en":"We need the director to approve the budget.","ex_es":"Necesitamos que el director apruebe el presupuesto."},{"en":"feedback","es":"comentarios, retroalimentación","pos":"noun","ex_en":"Thanks for your feedback on my presentation.","ex_es":"Gracias por tus comentarios sobre mi presentación."},{"en":"on behalf of","es":"en nombre de","pos":"phrase","ex_en":"On behalf of the company, welcome to the team.","ex_es":"En nombre de la empresa, bienvenido al equipo."},{"en":"let me know","es":"avísame","pos":"phrase","ex_en":"Let me know if you need anything else.","ex_es":"Avísame si necesitas algo más."},{"en":"request","es":"solicitud","pos":"noun","ex_en":"I sent a request for two days off.","ex_es":"Mandé una solicitud para dos días libres."}],"sentences":[{"en":"Would you mind sending me the file again?","es":"¿Le molestaría enviarme el archivo otra vez?"},{"en":"I was wondering if we could move the call to Thursday.","es":"Me preguntaba si podríamos cambiar la llamada al jueves."},{"en":"I'd really appreciate your feedback on this proposal.","es":"Le agradecería mucho sus comentarios sobre esta propuesta."},{"en":"Could you possibly give me a little more time?","es":"¿Habría manera de que me diera un poco más de tiempo?"},{"en":"Please let me know if you have any questions.","es":"Por favor, avíseme si tiene alguna duda."}],"tip_es":"Después de Would you mind usa el verbo con -ing: Would you mind waiting? Si respondes No, not at all, significa que no te molesta, o sea que sí aceptas. I was wondering if... suena mucho más amable que Can you...?"},{"id":"16-6","title_es":"Condicionales en el trabajo","words":[{"en":"unless","es":"a menos que","pos":"conj","ex_en":"We won't finish on time unless we work on Saturday.","ex_es":"No vamos a terminar a tiempo a menos que trabajemos el sábado."},{"en":"as long as","es":"siempre y cuando","pos":"phrase","ex_en":"You can work from home as long as you finish your tasks.","ex_es":"Puedes trabajar desde casa siempre y cuando termines tus pendientes."},{"en":"in case","es":"por si acaso","pos":"phrase","ex_en":"Bring your laptop in case we need it.","ex_es":"Trae tu laptop por si la necesitamos."},{"en":"budget","es":"presupuesto","pos":"noun","ex_en":"We don't have enough budget for a new office.","ex_es":"No tenemos suficiente presupuesto para una oficina nueva."},{"en":"afford","es":"costear, darse el lujo de","pos":"verb","ex_en":"We can't afford to lose this client.","ex_es":"No nos podemos dar el lujo de perder a este cliente."},{"en":"raise","es":"aumento de sueldo","pos":"noun","ex_en":"If I get a raise, I'll buy a car.","ex_es":"Si me dan un aumento, me voy a comprar un coche."},{"en":"opportunity","es":"oportunidad","pos":"noun","ex_en":"This job is a great opportunity for me.","ex_es":"Este trabajo es una gran oportunidad para mí."},{"en":"turn down","es":"rechazar","pos":"verb","ex_en":"It's hard to turn down a good offer.","ex_es":"Es difícil rechazar una buena oferta."}],"sentences":[{"en":"If we finish the project early, the client will be happy.","es":"Si terminamos el proyecto antes, el cliente va a estar contento."},{"en":"If I were the manager, I would hire more people.","es":"Si yo fuera el gerente, contrataría a más gente."},{"en":"What would you do if you lost your job?","es":"¿Qué harías si perdieras tu trabajo?"},{"en":"If you need help, just let me know.","es":"Si necesitas ayuda, nada más avísame."},{"en":"I'll accept the offer as long as I can work remotely.","es":"Voy a aceptar la oferta siempre y cuando pueda trabajar a distancia."}],"tip_es":"Primer condicional, para situaciones reales: If + presente, will + verbo. Segundo condicional, para situaciones imaginarias: If + pasado, would + verbo. En inglés formal se dice If I were. Nunca pongas will después de if: If it rains, no If it will rain."}],"dialogue":{"title_es":"La entrevista","setting_es":"Tienes una entrevista para un puesto de ventas en una empresa internacional.","lines":[{"who":"A","en":"Good morning. Thank you for coming in today.","es":"Buenos días. Gracias por venir hoy."},{"who":"B","en":"Good morning. Thank you for the opportunity.","es":"Buenos días. Gracias por la oportunidad."},{"who":"A","en":"So, tell me a little about your background.","es":"Bueno, cuénteme un poco sobre su trayectoria."},{"who":"B","en":"I studied business, and I've worked in sales for six years.","es":"Estudié administración y he trabajado en ventas durante seis años."},{"who":"A","en":"What would you say is your biggest strength?","es":"¿Cuál diría que es su mayor fortaleza?"},{"who":"B","en":"I'm a team player, and I'm very good with clients.","es":"Trabajo bien en equipo y soy muy bueno con los clientes."},{"who":"A","en":"Great. What would you do if a client was unhappy?","es":"Muy bien. ¿Qué haría si un cliente estuviera inconforme?"},{"who":"B","en":"I would listen carefully and try to find a solution quickly.","es":"Lo escucharía con atención y trataría de encontrar una solución rápido."},{"who":"A","en":"Excellent. We'll be in touch by the end of the week.","es":"Excelente. Nos comunicaremos con usted antes de que termine la semana."},{"who":"B","en":"Thank you. I look forward to hearing from you.","es":"Gracias. Quedo en espera de su respuesta."}]}}];
